"""enlg Hint Discovery Engine.

Scans a sequence of tokens, identifies the hint keyword, and locks the
canonical semantic intent. Operates strictly under the 'fail-closed' principle.
"""

from typing import List
from dataclasses import dataclass
from enlg.lexer.tokens import Token, TokenType
from enlg.core.intents import INTENT_REGISTRY, CONNECTORS
from enlg.diagnostics.diagnostics import UnknownHintError, IntentAmbiguityError

@dataclass
class LockedStatement:
    intent_id: str
    hint_token: Token
    remaining_tokens: List[Token]


class IntentDiscoveryEngine:
    """Discovers and locks the semantic intent for a statement."""

    @staticmethod
    def process_statement(statement_tokens: List[Token]) -> LockedStatement:
        if not statement_tokens:
            raise UnknownHintError("Statement is empty.")

        candidate_hints = []
        remaining_tokens = []

        # Pass 1: Identify all potential hint identifiers
        for token in statement_tokens:
            if token.type == TokenType.IDENTIFIER:
                val = token.value.lower()
                if val in INTENT_REGISTRY:
                    if not candidate_hints:
                        candidate_hints.append((val, token))
                        continue
            remaining_tokens.append(token)

        # Pass 2: Enforce fail-closed intent locking
        if len(candidate_hints) == 0:
            # Fallback checks (e.g., direct assignment `x = 10` without 'set')
            if IntentDiscoveryEngine._is_implicit_assignment(statement_tokens):
                return LockedStatement("ASSIGN_VARIABLE", statement_tokens[0], statement_tokens)
            raise UnknownHintError("No valid hint keyword found in statement.")

        if len(candidate_hints) > 1:
            # Check if all hints resolve to the same intent (e.g. "declare and create")
            intents_found = {INTENT_REGISTRY[alias] for alias, _ in candidate_hints}
            if len(intents_found) > 1:
                conflicting = ", ".join(sorted(intents_found))
                raise IntentAmbiguityError(f"Found conflicting intents: {conflicting}. Refusing to guess.")

            # If they map to the same intent, just take the first one

        alias, hint_token = candidate_hints[0]
        canonical_intent = INTENT_REGISTRY[alias]

        return LockedStatement(canonical_intent, hint_token, remaining_tokens)

    @staticmethod
    def _is_implicit_assignment(tokens: List[Token]) -> bool:
        if len(tokens) >= 3:
            if tokens[0].type == TokenType.IDENTIFIER and tokens[1].type == TokenType.SYMBOL and tokens[1].value == "=":
                return True
        return False

enlg/parser/expressions.py:
"""enlg Expression Parser - Complete Pratt Parser Edition.

Parses atomic expressions, grouping with parentheses, unary operators,
binary operators with mathematical precedence, indexing, list/map collections,
and intent-based calls/instantiations.
"""

from typing import List, Tuple, Optional
from enlg.lexer.tokens import Token, TokenType
from enlg.ast.nodes import (
    ExpressionNode, LiteralNode, IdentifierNode, 
    BooleanNode, NullNode, ListNode, MapNode, FunctionCallNode,
    BinaryOpNode, UnaryOpNode
)
from enlg.diagnostics.diagnostics import SyntaxError

# Precedence table (higher number = tighter binding)
PRECEDENCE_MAP = {
    "or": 1, "||": 1,
    "and": 2, "&&": 2,
    "==": 3, "!=": 3, "<": 3, "<=": 3, ">": 3, ">=": 3,
    "is": 3, "is not": 3, "equals": 3, "equal": 3, "matches": 3, "not equal": 3,
    "greater than": 3, "less than": 3, "greater than or equal to": 3, "less than or equal to": 3,
    "exceeds": 3, "reaches": 3, "above": 3, "below": 3, "at least": 3, "at most": 3,
    "|": 4, "^": 4,
    "&": 5,
    "<<": 6, ">>": 6,
    "+": 7, "-": 7, "plus": 7, "minus": 7,
    "*": 8, "/": 8, "%": 8, "//": 8, "times": 8, "divided": 8, "mod": 8, "modulo": 8,
    "**": 9, "power": 9
}

class ExpressionParser:

    @staticmethod
    def parse(tokens: List[Token]) -> ExpressionNode:
        """Parses a token stream into an ExpressionNode tree using Pratt parsing."""
        if not tokens:
            raise SyntaxError("E1003", "Expected expression, found nothing.")

        node, remaining = ExpressionParser._parse_pratt(tokens, min_prec=0)
        if remaining:
            raise SyntaxError("E1003", f"Unexpected tokens after expression: {[t.value for t in remaining]}")
        return node

    @staticmethod
    def _match_binary_op(tokens: List[Token]) -> Tuple[Optional[str], Optional[int], int]:
        """
        Attempts to match an infix binary operator from the start of tokens.
        Returns (canonical_op_str, precedence, tokens_consumed_count).
        If no operator matches, returns (None, None, 0).
        """
        if not tokens:
            return None, None, 0

        t0 = tokens[0]
        val0 = t0.value.lower()

        # 1. Symbol Operators
        if t0.type == TokenType.SYMBOL and val0 in PRECEDENCE_MAP:
            return val0, PRECEDENCE_MAP[val0], 1

        # 2. Multi-word and single-word English Operators
        if t0.type == TokenType.IDENTIFIER:
            # Check 6-word phrase: "is greater than or equal to", "is less than or equal to"
            if len(tokens) >= 6:
                w6 = " ".join([tokens[i].value.lower() for i in range(6)])
                if w6 in ("is greater than or equal to",):
                    return ">=", PRECEDENCE_MAP[">="], 6
                elif w6 in ("is less than or equal to",):
                    return "<=", PRECEDENCE_MAP["<="], 6

            # Check 5-word phrase: "is greater than or equal", "greater than or equal to"
            if len(tokens) >= 5:
                w5 = " ".join([tokens[i].value.lower() for i in range(5)])
                if w5 in ("is greater than or equal", "greater than or equal to"):
                    return ">=", PRECEDENCE_MAP[">="], 5
                elif w5 in ("is less than or equal", "less than or equal to"):
                    return "<=", PRECEDENCE_MAP["<="], 5

            # Check 4-word phrase: "greater than or equal", "less than or equal", "is not equal to"
            if len(tokens) >= 4:
                w4 = " ".join([tokens[i].value.lower() for i in range(4)])
                if w4 in ("greater than or equal",):
                    return ">=", PRECEDENCE_MAP[">="], 4
                elif w4 in ("less than or equal",):
                    return "<=", PRECEDENCE_MAP["<="], 4
                elif w4 in ("is not equal to",):
                    return "!=", PRECEDENCE_MAP["!="], 4

            # Check 3-word phrase: "is greater than", "is less than", "is equal to", "is at least"
            if len(tokens) >= 3:
                w3 = " ".join([tokens[i].value.lower() for i in range(3)])
                if w3 in ("is greater than", "is above"):
                    return ">", PRECEDENCE_MAP[">"], 3
                elif w3 in ("is less than", "is below", "is under"):
                    return "<", PRECEDENCE_MAP["<"], 3
                elif w3 in ("is at least",):
                    return ">=", PRECEDENCE_MAP[">="], 3
                elif w3 in ("is at most", "is up to"):
                    return "<=", PRECEDENCE_MAP["<="], 3
                elif w3 in ("is not equal", "not equal to"):
                    return "!=", PRECEDENCE_MAP["!="], 3
                elif w3 in ("is equal to", "is same as"):
                    return "==", PRECEDENCE_MAP["=="], 3

            # Check 2-word operators: "greater than", "less than", "at least", "at most"
            if len(tokens) >= 2:
                w2 = f"{val0} {tokens[1].value.lower()}"
                if w2 in ("is not", "not equal", "differs from"):
                    return "!=", PRECEDENCE_MAP["!="], 2
                elif w2 in ("greater than", "is above"):
                    return ">", PRECEDENCE_MAP[">"], 2
                elif w2 in ("less than", "is below", "is under"):
                    return "<", PRECEDENCE_MAP["<"], 2
                elif w2 in ("at least",):
                    return ">=", PRECEDENCE_MAP[">="], 2
                elif w2 in ("at most", "up to"):
                    return "<=", PRECEDENCE_MAP["<="], 2
                elif w2 in ("equal to", "equals to", "same as"):
                    return "==", PRECEDENCE_MAP["=="], 2
                elif w2 == "integer divided":
                    return "//", PRECEDENCE_MAP["//"], 2
                elif w2 == "left shift":
                    return "<<", PRECEDENCE_MAP["<<"], 2
                elif w2 == "right shift":
                    return ">>", PRECEDENCE_MAP[">>"], 2
                elif w2 == "bitwise and":
                    return "&", PRECEDENCE_MAP["&"], 2
                elif w2 == "bitwise or":
                    return "|", PRECEDENCE_MAP["|"], 2
                elif w2 == "bitwise xor":
                    return "^", PRECEDENCE_MAP["^"], 2

            # Check 1-word English operators
            if val0 in ("plus", "added"):
                return "+", PRECEDENCE_MAP["+"], 1
            elif val0 in ("minus", "subtracted"):
                return "-", PRECEDENCE_MAP["-"], 1
            elif val0 in ("times", "multiplied"):
                return "*", PRECEDENCE_MAP["*"], 1
            elif val0 == "divided":
                return "/", PRECEDENCE_MAP["/"], 1
            elif val0 in ("modulo", "mod"):
                return "%", PRECEDENCE_MAP["%"], 1
            elif val0 == "power":
                return "**", PRECEDENCE_MAP["**"], 1
            elif val0 in ("and",):
                return "&&", PRECEDENCE_MAP["and"], 1
            elif val0 in ("or",):
                return "||", PRECEDENCE_MAP["or"], 1
            elif val0 in ("exceeds", "above"):
                return ">", PRECEDENCE_MAP[">"], 1
            elif val0 in ("below", "under"):
                return "<", PRECEDENCE_MAP["<"], 1
            elif val0 in ("reaches",):
                return ">=", PRECEDENCE_MAP[">="], 1
            elif val0 in ("is", "equals", "equal", "matches"):
                return "==", PRECEDENCE_MAP["=="], 1

        return None, None, 0

    @staticmethod
    def _parse_pratt(tokens: List[Token], min_prec: int = 0) -> Tuple[ExpressionNode, List[Token]]:
        """Precedence Climbing Pratt Parser."""
        if not tokens:
            raise SyntaxError("E1003", "Expected expression, found nothing.")

        # 1. Parse Prefix / Atom
        left_node, remaining = ExpressionParser._parse_prefix(tokens)

        # 2. Infix / Postfix Loop
        while remaining:
            # Check Postfix Indexing `arr[idx]`
            if remaining[0].type == TokenType.SYMBOL and remaining[0].value == "[":
                idx_tokens = remaining[1:]
                bracket_level = 1
                pos = 0
                while pos < len(idx_tokens):
                    if idx_tokens[pos].type == TokenType.SYMBOL and idx_tokens[pos].value == "[":
                        bracket_level += 1
                    elif idx_tokens[pos].type == TokenType.SYMBOL and idx_tokens[pos].value == "]":
                        bracket_level -= 1
                        if bracket_level == 0:
                            break
                    pos += 1
                if pos >= len(idx_tokens):
                    raise SyntaxError("E1002", "Unmatched '[' bracket in index expression.")

                idx_expr = ExpressionParser.parse(idx_tokens[:pos])
                left_node = BinaryOpNode(left=left_node, op="[]", right=idx_expr)
                remaining = idx_tokens[pos+1:]
                continue

            # Check Infix Binary Operator
            op_sym, op_prec, consumed = ExpressionParser._match_binary_op(remaining)
            if op_sym is None or op_prec < min_prec:
                break

            # Right associativity for power '**'
            next_prec = op_prec if op_sym == "**" else op_prec + 1
            right_node, remaining = ExpressionParser._parse_pratt(remaining[consumed:], min_prec=next_prec)
            left_node = BinaryOpNode(left=left_node, op=op_sym, right=right_node)

        return left_node, remaining

    @staticmethod
    def _parse_prefix(tokens: List[Token]) -> Tuple[ExpressionNode, List[Token]]:
        """Parses prefix unary, grouping parentheses, atoms, and keyword intents."""
        token = tokens[0]
        val_lower = token.value.lower()

        # 1. Grouping Parentheses: `( expr )`
        if token.type == TokenType.SYMBOL and token.value == "(":
            paren_level = 1
            pos = 1
            while pos < len(tokens):
                if tokens[pos].type == TokenType.SYMBOL and tokens[pos].value == "(":
                    paren_level += 1
                elif tokens[pos].type == TokenType.SYMBOL and tokens[pos].value == ")":
                    paren_level -= 1
                    if paren_level == 0:
                        break
                pos += 1
            if pos >= len(tokens):
                raise SyntaxError("E1002", "Unmatched '(' in expression.")

            inner_expr = ExpressionParser.parse(tokens[1:pos])
            return inner_expr, tokens[pos+1:]

        # 2. Intent Expressions (call, new, await, native)
        from enlg.core.intents import INTENT_REGISTRY
        intent = INTENT_REGISTRY.get(val_lower)
        if token.type == TokenType.IDENTIFIER and intent == "FUNC_CALL":
            return ExpressionParser._parse_function_call(tokens)
        elif token.type == TokenType.IDENTIFIER and intent == "CLASS_NEW":
            return ExpressionParser._parse_instantiation(tokens)
        elif token.type == TokenType.IDENTIFIER and intent == "ASYNC_AWAIT":
            return ExpressionParser._parse_await(tokens)
        elif token.type == TokenType.IDENTIFIER and intent == "PYTHON_INTEROP":
            return ExpressionParser._parse_interop(tokens)

        # 3. Unary Operators (-, !, ~, not)
        if token.type == TokenType.SYMBOL and token.value in ("-", "!", "~"):
            op = token.value
            operand_node, rest = ExpressionParser._parse_pratt(tokens[1:], min_prec=8)
            if op == "-" and isinstance(operand_node, LiteralNode) and operand_node.type_name == "number":
                return LiteralNode(value=f"-{operand_node.value}", type_name="number"), rest
            return UnaryOpNode(op=op, operand=operand_node), rest

        if token.type == TokenType.IDENTIFIER and val_lower == "not":
            operand_node, rest = ExpressionParser._parse_pratt(tokens[1:], min_prec=3)
            return UnaryOpNode(op="not", operand=operand_node), rest

        # 4. Primitives & Literals
        if token.type == TokenType.NUMBER:
            return LiteralNode(value=token.value, type_name="number"), tokens[1:]
        elif token.type == TokenType.STRING:
            return LiteralNode(value=token.value, type_name="string"), tokens[1:]
        elif token.type == TokenType.IDENTIFIER:
            if val_lower == "true":
                return BooleanNode(value=True), tokens[1:]
            elif val_lower == "false":
                return BooleanNode(value=False), tokens[1:]
            elif val_lower == "null":
                return NullNode(), tokens[1:]
            else:
                return IdentifierNode(name=token.value), tokens[1:]

        # 5. Lists [...]
        elif token.type == TokenType.SYMBOL and token.value == "[":
            return ExpressionParser._parse_list(tokens)

        # 6. Maps {...}
        elif token.type == TokenType.SYMBOL and token.value == "{":
            return ExpressionParser._parse_map(tokens)

        raise SyntaxError("E1003", f"Unexpected token in expression: '{token.value}'")

    @staticmethod
    def _parse_single(tokens: List[Token]) -> Tuple[ExpressionNode, List[Token]]:
        """Legacy helper for single atom/prefix expression parsing."""
        return ExpressionParser._parse_prefix(tokens)

    @staticmethod
    def _parse_list(tokens: List[Token]) -> Tuple[ListNode, List[Token]]:
        elements = []
        pos = 1

        while pos < len(tokens):
            t = tokens[pos]
            if t.type == TokenType.SYMBOL and t.value == "]":
                return ListNode(elements=elements), tokens[pos+1:]
            if t.type == TokenType.SYMBOL and t.value == ",":
                pos += 1
                continue

            node, remaining = ExpressionParser._parse_pratt(tokens[pos:], min_prec=0)
            elements.append(node)
            pos = len(tokens) - len(remaining)

        raise SyntaxError("E1002", "Unmatched '[' bracket in list expression.")

    @staticmethod
    def _parse_map(tokens: List[Token]) -> Tuple[MapNode, List[Token]]:
        pairs = {}
        pos = 1

        while pos < len(tokens):
            t = tokens[pos]
            if t.type == TokenType.SYMBOL and t.value == "}":
                return MapNode(pairs=pairs), tokens[pos+1:]
            if t.type == TokenType.SYMBOL and t.value == ",":
                pos += 1
                continue

            key_token = tokens[pos]
            if key_token.type != TokenType.STRING:
                raise SyntaxError("E1003", f"Map keys must be strings, found: {key_token.value}")
            key = key_token.value
            pos += 1

            if pos >= len(tokens) or not (tokens[pos].type == TokenType.SYMBOL and tokens[pos].value == ":"):
                raise SyntaxError("E1003", f"Expected ':' after map key '{key}'")
            pos += 1

            val_node, remaining = ExpressionParser._parse_pratt(tokens[pos:], min_prec=0)
            pairs[key] = val_node
            pos = len(tokens) - len(remaining)

        raise SyntaxError("E1002", "Unmatched '{' brace in map expression.")

    @staticmethod
    def _parse_function_call(tokens: List[Token]) -> Tuple[FunctionCallNode, List[Token]]:
        if len(tokens) < 2 or tokens[1].type != TokenType.IDENTIFIER:
            raise SyntaxError("E1003", "Missing function name in call expression.")

        func_name = tokens[1].value
        pos = 2
        args = []

        from enlg.core.intents import CONNECTORS

        while pos < len(tokens):
            t_val = tokens[pos].value.lower() if tokens[pos].type == TokenType.IDENTIFIER else ""

            if t_val in ("from", "using"):
                if pos + 1 < len(tokens) and tokens[pos+1].type == TokenType.IDENTIFIER:
                    mod_name = tokens[pos+1].value
                    if "." not in func_name:
                        func_name = f"{mod_name}.{func_name}"
                    pos += 2
                    continue

            if len(args) > 0:
                # Subsequent arguments MUST be preceded by a comma or connector
                if tokens[pos].type == TokenType.SYMBOL and tokens[pos].value == ",":
                    pos += 1
                elif tokens[pos].type == TokenType.IDENTIFIER and t_val in CONNECTORS:
                    pos += 1
                else:
                    # Argument list has ended; remaining tokens belong to outer expression (e.g. '- 1')
                    break
            else:
                # Skip leading connectors for first argument ('with', 'using', 'to', etc.)
                if tokens[pos].type == TokenType.IDENTIFIER and t_val in CONNECTORS:
                    pos += 1
                    continue

            if pos >= len(tokens):
                break

            try:
                arg_node, remaining = ExpressionParser._parse_prefix(tokens[pos:])
                args.append(arg_node)
                pos = len(tokens) - len(remaining)
            except SyntaxError:
                break

        return FunctionCallNode(name=func_name, arguments=args), tokens[pos:]

    @staticmethod
    def _parse_instantiation(tokens: List[Token]) -> Tuple['InstantiateNode', List[Token]]:
        from enlg.ast.nodes import InstantiateNode
        if len(tokens) < 2 or tokens[1].type != TokenType.IDENTIFIER:
            raise SyntaxError("E1003", "Missing class name in instantiation.")

        class_name = tokens[1].value
        pos = 2
        args = []

        from enlg.core.intents import CONNECTORS
        while pos < len(tokens) and tokens[pos].type == TokenType.IDENTIFIER and tokens[pos].value.lower() in CONNECTORS:
            pos += 1

        while pos < len(tokens):
            if tokens[pos].type == TokenType.SYMBOL and tokens[pos].value == ",":
                pos += 1
                continue

            try:
                arg_node, remaining = ExpressionParser._parse_prefix(tokens[pos:])
                args.append(arg_node)
                pos = len(tokens) - len(remaining)
            except SyntaxError:
                break

        return InstantiateNode(class_name=class_name, arguments=args), tokens[pos:]

    @staticmethod
    def _parse_await(tokens: List[Token]) -> Tuple['AwaitNode', List[Token]]:
        from enlg.ast.nodes import AwaitNode
        if len(tokens) < 2:
            raise SyntaxError("E1003", "Missing expression to await.")

        pos = 1
        from enlg.core.intents import CONNECTORS
        while pos < len(tokens) and tokens[pos].type == TokenType.IDENTIFIER and tokens[pos].value.lower() in CONNECTORS:
            pos += 1

        expr_node, remaining = ExpressionParser._parse_prefix(tokens[pos:])
        return AwaitNode(expression=expr_node), remaining

    @staticmethod
    def _parse_interop(tokens: List[Token]) -> Tuple['PythonInteropNode', List[Token]]:
        from enlg.ast.nodes import PythonInteropNode
        if len(tokens) < 2:
            raise SyntaxError("E1003", "Missing target for python interop.")

        target = tokens[1].value
        pos = 2
        args = []

        from enlg.core.intents import CONNECTORS
        while pos < len(tokens) and tokens[pos].type == TokenType.IDENTIFIER and tokens[pos].value.lower() in CONNECTORS:
            pos += 1

        while pos < len(tokens):
            if tokens[pos].type == TokenType.SYMBOL and tokens[pos].value == ",":
                pos += 1
                continue
            try:
                arg_node, remaining = ExpressionParser._parse_prefix(tokens[pos:])
                args.append(arg_node)
                pos = len(tokens) - len(remaining)
            except SyntaxError:
                break

        return PythonInteropNode(target=target, arguments=args), tokens[pos:]

enlg/parser/slot_parser.py:
"""enlg Flexible Slot Parser.

Transforms LockedStatements into explicitly typed AST Nodes by extracting
operands flexibly. Adheres to fail-closed mechanics if slots are missing.
"""

from typing import List, Optional
from enlg.lexer.tokens import Token, TokenType
from enlg.parser.discovery import LockedStatement
from enlg.ast.nodes import (
    StatementNode, VariableDeclNode, AssignmentNode, OutputNode
)
from enlg.parser.expressions import ExpressionParser
from enlg.diagnostics.diagnostics import SyntaxError

class SlotParser:
    """Extracts operands from a LockedStatement into an AST node."""

    @staticmethod
    def parse(statement: LockedStatement) -> StatementNode:
        return SlotParser.parse_with_body(statement, None)

    @staticmethod
    def parse_with_body(statement: LockedStatement, body: Optional['BlockNode']) -> StatementNode:
        from enlg.ast.nodes import BlockNode, IfNode, WhileNode
        intent = statement.intent_id
        tokens = statement.remaining_tokens

        if intent == "DECLARE_VARIABLE":
            return SlotParser._parse_declaration(tokens)
        elif intent in ("ASSIGN_VARIABLE", "ASSIGN_COMPOUND_ADD", "ASSIGN_COMPOUND_SUB", "ASSIGN_COMPOUND_MUL", "ASSIGN_COMPOUND_DIV"):
            return SlotParser._parse_assignment(tokens, intent)
        elif intent == "OUTPUT_DISPLAY":
            return SlotParser._parse_output(tokens)
        elif intent in ("COND_IF", "COND_ELIF"):
            if not body:
                raise SyntaxError("E1003", "If/Else If statement requires an indented block.")
            return SlotParser._parse_if(tokens, body)
        elif intent == "COND_ELSE":
            raise SyntaxError("E1003", "Else statement must directly follow an if block.")
        elif intent in ("LOOP_WHILE", "LOOP_REPEAT"):
            if not body:
                raise SyntaxError("E1003", "Loop statement requires an indented block.")
            return SlotParser._parse_while(tokens, body)
        elif intent == "FUNC_DEF":
            if not body:
                raise SyntaxError("E1003", "Function definition requires an indented block.")
            return SlotParser._parse_function_def(tokens, body)
        elif intent == "FUNC_RETURN":
            return SlotParser._parse_return(tokens)
        elif intent == "BLOCK_TRY":
            if not body:
                raise SyntaxError("E1003", "Attempt/try block requires an indented block.")
            from enlg.ast.nodes import AttemptNode
            return AttemptNode(body=body)
        elif intent == "BLOCK_CATCH":
            if not body:
                raise SyntaxError("E1003", "Rescue/catch block requires an indented block.")
            return SlotParser._parse_rescue(tokens, body)
        elif intent == "STMT_RAISE":
            return SlotParser._parse_raise(tokens)
        elif intent == "STMT_IMPORT":
            return SlotParser._parse_import(tokens)
        elif intent in (
            "AI_TRAIN", "AI_PREDICT", "AI_EVALUATE",
            "AI_LOAD", "AI_PREPROCESS", "AI_SPLIT",
            "AI_SAVE", "AI_RESTORE", "AI_FIT",
            "DL_COMPILE", "DL_FORWARD",
            "SEC_SCAN", "SEC_ENCRYPT",
            "CLOUD_DEPLOY", "CLOUD_FETCH",
        ):
            return SlotParser._parse_domain_op(intent, tokens)
        elif intent == "CLASS_DEF":
            if not body:
                raise SyntaxError("E1003", "Class definition requires an indented block.")
            return SlotParser._parse_class_def(tokens, body)
        elif intent in ("CLASS_NEW", "FUNC_CALL", "ASYNC_AWAIT", "PYTHON_INTEROP"):
            return SlotParser._parse_expression_statement(statement)

        raise SyntaxError("E1003", f"Unsupported intent for slot parsing: {intent}")

    @staticmethod
    def _parse_class_def(tokens: List[Token], body: 'BlockNode') -> 'StatementNode':
        from enlg.ast.nodes import ClassDefNode
        if not tokens:
            raise SyntaxError("E1003", "Missing class name.")

        name = tokens[0].value
        base_classes = []
        pos = 1

        # Check for inheritance keywords
        from enlg.core.intents import CONNECTORS
        while pos < len(tokens):
            val = tokens[pos].value.lower()
            if val in ("inherits", "extends"):
                pos += 1
                while pos < len(tokens):
                    if tokens[pos].type == TokenType.SYMBOL and tokens[pos].value == ",":
                        pos += 1
                        continue
                    if tokens[pos].type == TokenType.IDENTIFIER:
                        base_classes.append(tokens[pos].value)
                    else:
                        raise SyntaxError("E1003", f"Invalid base class name: {tokens[pos].value}")
                    pos += 1
                break
            pos += 1

        return ClassDefNode(name=name, base_classes=base_classes, body=body)

    @staticmethod
    def _parse_expression_statement(statement: LockedStatement) -> 'StatementNode':
        full_tokens = [statement.hint_token] + statement.remaining_tokens
        expr_node = ExpressionParser.parse(full_tokens)
        return expr_node

    @staticmethod
    def _parse_rescue(tokens: List[Token], body: 'BlockNode') -> 'StatementNode':
        from enlg.ast.nodes import RescueNode
        if not tokens:
            raise SyntaxError("E1003", "Missing error variable in rescue block.")
        # Just grab the first identifier as the error name
        for t in tokens:
            if t.type == TokenType.IDENTIFIER:
                return RescueNode(error_name=t.value, body=body)
        raise SyntaxError("E1003", "Could not find error identifier in rescue statement.")

    @staticmethod
    def _parse_raise(tokens: List[Token]) -> 'StatementNode':
        from enlg.ast.nodes import RaiseNode
        if not tokens:
            raise SyntaxError("E1003", "Missing expression to throw.")
        expr_node = ExpressionParser.parse(tokens)
        return RaiseNode(expression=expr_node)

    @staticmethod
    def _parse_import(tokens: List[Token]) -> 'StatementNode':
        from enlg.ast.nodes import ImportNode
        if not tokens:
            raise SyntaxError("E1003", "Invalid module name in import statement.")

        module_name = tokens[0].value
        return ImportNode(module=module_name, aliases=[])

    @staticmethod
    def _parse_function_def(tokens: List[Token], body: 'BlockNode') -> 'StatementNode':
        from enlg.ast.nodes import FunctionDefNode
        if not tokens:
            raise SyntaxError("E1003", "Missing function name.")

        is_async = False
        pos = 0
        if tokens[0].type == TokenType.IDENTIFIER and tokens[0].value.lower() == "async":
            is_async = True
            pos = 1

        if pos >= len(tokens):
            raise SyntaxError("E1003", "Missing function name after async modifier.")

        name = tokens[pos].value
        params = []
        pos += 1

        # skip connectors
        from enlg.core.intents import CONNECTORS
        while pos < len(tokens) and tokens[pos].type == TokenType.IDENTIFIER and tokens[pos].value.lower() in CONNECTORS:
            pos += 1

        while pos < len(tokens):
            if tokens[pos].type == TokenType.SYMBOL and tokens[pos].value == ",":
                pos += 1
                continue
            if tokens[pos].type == TokenType.IDENTIFIER:
                params.append(tokens[pos].value)
            else:
                raise SyntaxError("E1003", f"Invalid parameter name: {tokens[pos].value}")
            pos += 1

        return FunctionDefNode(name=name, parameters=params, body=body, is_async=is_async)

    @staticmethod
    def _parse_return(tokens: List[Token]) -> 'StatementNode':
        from enlg.ast.nodes import ReturnNode
        if not tokens:
            return ReturnNode(expression=None)
        expr_node = ExpressionParser.parse(tokens)
        return ReturnNode(expression=expr_node)

    @staticmethod
    def _parse_if(tokens: List[Token], body: 'BlockNode') -> 'IfNode':
        from enlg.ast.nodes import IfNode
        if not tokens:
            raise SyntaxError("E1003", "Missing condition in if statement.")
        # Simplified for Phase 5: we parse the condition as a single atomic expression.
        # Future phases will add boolean operators (==, <, >).
        expr_node = ExpressionParser.parse(tokens)
        return IfNode(condition=expr_node, body=body)

    @staticmethod
    def _parse_while(tokens: List[Token], body: 'BlockNode') -> 'WhileNode':
        from enlg.ast.nodes import WhileNode
        if not tokens:
            raise SyntaxError("E1003", "Missing condition in while loop.")
        expr_node = ExpressionParser.parse(tokens)
        return WhileNode(condition=expr_node, body=body)

    @staticmethod
    def _parse_declaration(tokens: List[Token]) -> VariableDeclNode:
        identifier: Optional[str] = None
        expr_tokens: List[Token] = []

        SILENT_ARTICLES = {"a", "an", "the"}
        SILENT_CONNECTORS = {"as", "of", "to", "is", "with", "be"}

        # Flexibly find the identifier and the expression part
        for t in tokens:
            if t.type == TokenType.SYMBOL and t.value == "=":
                continue # Skip explicit equals

            if identifier is None:
                if t.type == TokenType.IDENTIFIER and t.value.lower() in SILENT_ARTICLES:
                    continue # Skip leading article
                if t.type == TokenType.IDENTIFIER and t.value.lower() not in SILENT_CONNECTORS:
                    identifier = t.value
                    continue
                else:
                    expr_tokens.append(t)
            else:
                expr_tokens.append(t)

        if identifier is None:
            raise SyntaxError("E1003", "Missing identifier in variable declaration.")

        # Strip leading/trailing connectors from expression tokens (e.g. 'of 78' -> '78', 'to' -> stripped)
        while expr_tokens and (
            (expr_tokens[0].type == TokenType.SYMBOL and expr_tokens[0].value == "=") or
            (expr_tokens[0].type == TokenType.IDENTIFIER and expr_tokens[0].value.lower() in SILENT_CONNECTORS)
        ):
            expr_tokens.pop(0)

        while expr_tokens and (
            (expr_tokens[-1].type == TokenType.SYMBOL and expr_tokens[-1].value == "=") or
            (expr_tokens[-1].type == TokenType.IDENTIFIER and expr_tokens[-1].value.lower() in SILENT_CONNECTORS)
        ):
            expr_tokens.pop()

        expr_node = None
        if expr_tokens:
            expr_node = ExpressionParser.parse(expr_tokens)

        return VariableDeclNode(identifier=identifier, value=expr_node)

    @staticmethod
    def _parse_assignment(tokens: List[Token], intent: str = "ASSIGN_VARIABLE") -> AssignmentNode:
        from enlg.ast.nodes import IdentifierNode, BinaryOpNode

        compound_ops = {
            "+=": "+", "-=": "-", "*=": "*", "/=": "/", "%=": "%",
            "**=": "**", "//=": "//", "&=": "&", "|=": "|", "^=": "^",
            "<<=": "<<", ">>=": ">>"
        }

        intent_ops = {
            "ASSIGN_COMPOUND_ADD": "+",
            "ASSIGN_COMPOUND_SUB": "-",
            "ASSIGN_COMPOUND_MUL": "*",
            "ASSIGN_COMPOUND_DIV": "/"
        }

        identifier: Optional[str] = None
        expr_tokens: List[Token] = []
        found_compound_op: Optional[str] = intent_ops.get(intent)

        for t in tokens:
            if t.type == TokenType.SYMBOL and t.value == "=":
                continue
            elif t.type == TokenType.SYMBOL and t.value in compound_ops:
                found_compound_op = compound_ops[t.value]
                continue

            if identifier is None and t.type == TokenType.IDENTIFIER:
                identifier = t.value
            else:
                expr_tokens.append(t)

        if identifier is None:
            raise SyntaxError("E1003", "Missing target identifier for assignment.")

        # Strip leading connectors from assignment expression (e.g. 'set score to 50' -> '50')
        while expr_tokens and (
            (expr_tokens[0].type == TokenType.SYMBOL and expr_tokens[0].value == "=") or
            (expr_tokens[0].type == TokenType.IDENTIFIER and expr_tokens[0].value.lower() in ("to", "as", "is", "with", "equals"))
        ):
            expr_tokens.pop(0)

        if not expr_tokens:
            raise SyntaxError("E1003", "Missing value in assignment expression.")

        rhs_node = ExpressionParser.parse(expr_tokens)
        if found_compound_op:
            final_val = BinaryOpNode(left=IdentifierNode(name=identifier), op=found_compound_op, right=rhs_node)
        else:
            final_val = rhs_node

        return AssignmentNode(identifier=identifier, value=final_val)

    @staticmethod
    def _parse_output(tokens: List[Token]) -> OutputNode:
        if not tokens:
            raise SyntaxError("E1003", "Missing expression for output statement.")

        SILENT_OUTPUT_GLUE = {"the", "a", "message", "text", "result"}
        clean_tokens = list(tokens)
        while len(clean_tokens) > 1 and clean_tokens[0].type == TokenType.IDENTIFIER and clean_tokens[0].value.lower() in SILENT_OUTPUT_GLUE:
            clean_tokens.pop(0)

        expr_node = ExpressionParser.parse(clean_tokens)
        return OutputNode(expression=expr_node)

    @staticmethod
    def _parse_domain_op(intent: str, tokens: List[Token]) -> 'DomainOpNode':
        from enlg.ast.nodes import DomainOpNode, IdentifierNode
        from enlg.core.intents import CONNECTORS
        if not tokens:
            raise SyntaxError("E1003", f"Missing parameters for domain operation '{intent}'")

        # Extract 'from <module>' scoping (Only 'from', not 'using', to avoid breaking 'predict X using Y')
        from_module = None
        filtered_tokens = []
        pos = 0
        while pos < len(tokens):
            if tokens[pos].type == TokenType.IDENTIFIER and tokens[pos].value.lower() == "from":
                if pos + 1 < len(tokens) and tokens[pos+1].type == TokenType.IDENTIFIER:
                    from_module = tokens[pos+1].value
                    pos += 2
                    continue
            filtered_tokens.append(tokens[pos])
            pos += 1

        tokens = filtered_tokens

        # ── Auto-store intents: "load X from Y", "restore X from Y"
        # First token is the DESTINATION var name (doesn't exist yet → LOAD_CONST)
        AUTO_STORE_INTENTS = {"AI_LOAD", "AI_RESTORE"}

        # ── Store-back intents: var EXISTS in env, result stored back into same var
        # AI_PREPROCESS: "preprocess email_data" → LOAD_VAR → preprocess → STORE_VAR
        # AI_TRAIN:      "train model with data" → LOAD_VAR → train → STORE_VAR
        # AI_FIT:        "fit net with data"     → LOAD_VAR → fit   → STORE_VAR
        STORE_BACK_INTENTS = {"AI_TRAIN", "AI_FIT", "AI_PREPROCESS"}
        if intent in STORE_BACK_INTENTS and tokens[0].type == TokenType.IDENTIFIER:
            model_var = tokens[0].value
            model_node = IdentifierNode(name=model_var)
            rest = tokens[1:]
            filtered = [t for t in rest
                        if not (t.type == TokenType.IDENTIFIER and t.value.lower() in CONNECTORS)]
            args = []
            pos = 0
            while pos < len(filtered):
                if filtered[pos].type == TokenType.SYMBOL and filtered[pos].value == ",":
                    pos += 1
                    continue
                try:
                    arg_node, rest2 = ExpressionParser._parse_single(filtered[pos:])
                    args.append(arg_node)
                    consumed = len(filtered[pos:]) - len(rest2)
                    pos += consumed if consumed > 0 else 1
                except Exception:
                    break
            return DomainOpNode(op=intent, target=model_node, arguments=args,
                                store_result=model_var, store_back=True, from_module=from_module)

        store_result = None

        if intent == "AI_SPLIT" and tokens[0].type == TokenType.IDENTIFIER:
            # Pattern: split <source_var> into <train_var> and <test_var>
            source_var = tokens[0].value
            source_node = IdentifierNode(name=source_var)
            remaining_after_source = tokens[1:]
            # Collect identifier tokens after filtering connectors (into, and)
            dest_vars = [t.value for t in remaining_after_source
                         if t.type == TokenType.IDENTIFIER and t.value.lower() not in CONNECTORS]
            # Also collect any numeric ratio tokens
            ratio_args = [t for t in remaining_after_source
                          if t.type == TokenType.NUMBER]
            args = [IdentifierNode(name=v) for v in dest_vars]
            # store_result encodes "train_var:test_var" so generator knows both names
            store_result = ":".join(dest_vars) if dest_vars else source_var
            return DomainOpNode(op=intent, target=source_node, arguments=args, store_result=store_result, from_module=from_module)

        if intent in AUTO_STORE_INTENTS and tokens[0].type == TokenType.IDENTIFIER:
            # Variable name to store result into
            store_result = tokens[0].value
            remaining_after_var = tokens[1:]
            # Filter connectors
            filtered = [t for t in remaining_after_var
                        if not (t.type == TokenType.IDENTIFIER and t.value.lower() in CONNECTORS)]
            args = []
            pos = 0
            while pos < len(filtered):
                if filtered[pos].type == TokenType.SYMBOL and filtered[pos].value == ",":
                    pos += 1
                    continue
                try:
                    arg_node, rest = ExpressionParser._parse_single(filtered[pos:])
                    args.append(arg_node)
                    consumed = len(filtered[pos:]) - len(rest)
                    pos += consumed if consumed > 0 else 1
                except Exception:
                    break
            # target is a dummy identifier (the var itself)
            target_node = IdentifierNode(name=store_result)
            return DomainOpNode(op=intent, target=target_node, arguments=args, store_result=store_result, from_module=from_module)

        # Standard ops: target is first expression, rest are args
        target_node, remaining = ExpressionParser._parse_single(tokens)

        # Filter connectors from remaining tokens
        filtered_remaining = [t for t in remaining if not (t.type == TokenType.IDENTIFIER and t.value.lower() in CONNECTORS)]

        args = []
        pos = 0
        while pos < len(filtered_remaining):
            if filtered_remaining[pos].type == TokenType.SYMBOL and filtered_remaining[pos].value == ",":
                pos += 1
                continue
            try:
                arg_node, rest = ExpressionParser._parse_single(filtered_remaining[pos:])
                args.append(arg_node)
                pos = len(filtered_remaining) - len(rest)
            except SyntaxError:
                break

        return DomainOpNode(op=intent, target=target_node, arguments=args, from_module=from_module)

