# enlg/stdlib/std.py
# The Master "Dot-Free" Wrapper Library for enlg

import builtins
import os
import sys

# Try importing common libraries for fallback
try: import pandas as pd
except ImportError: pd = None

try: import numpy as np
except ImportError: np = None

try: import math
except ImportError: math = None

# ── Data Science Wrappers ──────────────────────────────────────────────
def read_csv(filepath):
    if pd: return pd.read_csv(filepath)
    raise RuntimeError("pandas not installed")

def read_json(filepath):
    if pd: return pd.read_json(filepath)
    raise RuntimeError("pandas not installed")

def drop_empty(df):
    if hasattr(df, "dropna"): return df.dropna()
    return df

def copy_data(df):
    if hasattr(df, "copy"): return df.copy()
    return df

def slice_data(df, start, end):
    start = int(start) if isinstance(start, str) else start
    end = int(end) if isinstance(end, str) else end
    if hasattr(df, "iloc"): return df.iloc[start:end]
    return df[start:end]

# ── NumPy & Math Wrappers ──────────────────────────────────────────────
def array(data):
    if np:
        cleaned = []
        for x in data:
            if isinstance(x, str):
                try:
                    num = float(x)
                    x = int(num) if num.is_integer() else num
                except ValueError:
                    pass
            cleaned.append(x)
        return np.array(cleaned)
    raise RuntimeError("numpy not installed")

def mean(data):
    if np: return np.mean(data)
    raise RuntimeError("numpy not installed")

def zeros(shape):
    if np: return np.zeros(shape)
    raise RuntimeError("numpy not installed")

def ones(shape):
    if np: return np.ones(shape)
    raise RuntimeError("numpy not installed")

def reshape(arr, shape):
    if np: return np.reshape(arr, shape)
    raise RuntimeError("numpy not installed")

def sum_all(data):
    if np: return np.sum(data)
    return sum(data)

def matrix_mul(a, b):
    if np: return np.matmul(a, b)
    raise RuntimeError("numpy not installed")

def get_length(obj):
    return len(obj)

def get_item(obj, index):
    index = int(index) if isinstance(index, str) else index
    return obj[index]

def print_type(obj):
    return type(obj).__name__

def read_text(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        return f.read()

def write_text(filepath, content):
    with open(filepath, 'w', encoding='utf-8') as f:
        f.write(str(content))

def get_env(key):
    return os.environ.get(key, "")

def list_files(dirpath="."):
    return os.listdir(dirpath)

# ── The "God Call" (Run any python method using spaces instead of dots) ─
def run_py(path_string, *args):
    """
    Examples:
    run_py("pandas read_csv", "file.csv") -> pandas.read_csv("file.csv")
    run_py("math sqrt", 16) -> math.sqrt(16)
    """
    parts = path_string.split(" ")

    import importlib
    try:
        obj = importlib.import_module(parts[0])
    except ImportError:
        if hasattr(builtins, parts[0]):
            obj = getattr(builtins, parts[0])
        else:
            raise RuntimeError(f"Could not find module or object '{parts[0]}'")

    for p in parts[1:]:
        obj = getattr(obj, p)

    if callable(obj):
        return obj(*args)
    return obj

enlgd/ast_nodes.py:
"""enlgd Abstract Syntax Tree (AST) Nodes.

Defines the node structures representing stylesheets, rules, declarations, media queries, variables, and animations.
"""

from dataclasses import dataclass, field
from typing import List, Optional

class ASTNode:
    """Base class for all .enlgd AST nodes."""
    pass

@dataclass
class DeclarationNode(ASTNode):
    """Represents a single CSS property declaration."""
    property_name: str
    value: str

@dataclass
class VariableNode(ASTNode):
    """Represents a CSS Custom Property (:root variable)."""
    var_type: str  # color, size, etc.
    name: str      # e.g. "primary" -> will emit --primary
    value: str     # e.g. "#1e3c72" or "16px"

@dataclass
class RuleNode(ASTNode):
    """Represents a CSS rule set with a selector and declarations."""
    selector: str
    declarations: List[DeclarationNode] = field(default_factory=list)

@dataclass
class MediaRuleNode(ASTNode):
    """Represents an @media query block containing nested rules."""
    query: str  # e.g. "(max-width: 768px)" or "(orientation: portrait)"
    rules: List[RuleNode] = field(default_factory=list)

@dataclass
class KeyframeFrameNode(ASTNode):
    """Represents a single keyframe step (e.g. 0%, 100%, from, to)."""
    stop: str  # e.g. "0%", "100%"
    declarations: List[DeclarationNode] = field(default_factory=list)

@dataclass
class KeyframeNode(ASTNode):
    """Represents an @keyframes animation definition."""
    name: str
    frames: List[KeyframeFrameNode] = field(default_factory=list)

@dataclass
class StylesheetNode(ASTNode):
    """Represents the entire compiled .enlgd stylesheet."""
    variables: List[VariableNode] = field(default_factory=list)
    rules: List[RuleNode] = field(default_factory=list)
    media_rules: List[MediaRuleNode] = field(default_factory=list)
    keyframes: List[KeyframeNode] = field(default_factory=list)

enlgd/emitter.py:
"""enlgd CSS Emitter.

Traverses an ENLGD AST (StylesheetNode) and compiles it into valid, standard CSS.
"""

from typing import List
from .ast_nodes import (
    StylesheetNode, RuleNode, DeclarationNode,
    MediaRuleNode, VariableNode, KeyframeNode, KeyframeFrameNode
)

class ENLGDEmitter:
    """Emits standard CSS from an ENLGD StylesheetNode AST."""

    def __init__(self, stylesheet: StylesheetNode):
        self.stylesheet = stylesheet

    def emit(self) -> str:
        css_blocks: List[str] = []

        # 1. CSS Custom Properties (:root variables)
        if self.stylesheet.variables:
            var_lines = [":root {"]
            for var in self.stylesheet.variables:
                var_lines.append(f"  --{var.name}: {var.value};")
            var_lines.append("}")
            css_blocks.append("\n".join(var_lines))

        # 2. Keyframe Animations
        for kf in self.stylesheet.keyframes:
            kf_lines = [f"@keyframes {kf.name} {{"]
            for frame in kf.frames:
                kf_lines.append(f"  {frame.stop} {{")
                for decl in frame.declarations:
                    kf_lines.append(f"    {decl.property_name}: {decl.value};")
                kf_lines.append("  }")
            kf_lines.append("}")
            css_blocks.append("\n".join(kf_lines))

        # 3. Standard Rule Blocks
        for rule in self.stylesheet.rules:
            rule_str = self._emit_rule(rule)
            if rule_str:
                css_blocks.append(rule_str)

        # 4. Media Queries
        for media in self.stylesheet.media_rules:
            media_lines = [f"@media {media.query} {{"]
            for rule in media.rules:
                inner_rule = self._emit_rule(rule, indent=2)
                if inner_rule:
                    media_lines.append(inner_rule)
            media_lines.append("}")
            css_blocks.append("\n".join(media_lines))

        return "\n\n".join(css_blocks)

    def _emit_rule(self, rule: RuleNode, indent: int = 0) -> str:
        if not rule.declarations:
            return ""
        pad = " " * indent
        lines = [f"{pad}{rule.selector} {{"]
        for decl in rule.declarations:
            lines.append(f"{pad}  {decl.property_name}: {decl.value};")
        lines.append(f"{pad}}}")
        return "\n".join(lines)

enlgd/parser.py:
"""enlgd Parser.

Parses tokens into an ENLGD Stylesheet AST (StylesheetNode).
Supports:
- Variable definitions: define [color|size|value] "name" as [value]
- Rule blocks: for [selector] apply: ... end, style [selector]: ... end
- Pseudo states: when [selector] is [hovered|focused|active|...] apply: ... end
- Media queries: when screen is [smaller|larger] than [N] apply: ... end
- Connector words: multi-declaration chaining (and, with, also)
- Units & Shorthands: auto-px, percentages, viewport units (vh/vw), degrees
- Gradients: background gradient from [A] to [B] at [deg]
- Keyframe animations: animation [name]: at [N] percent: ... end
"""

from typing import List, Optional, Tuple
from .tokens import Token, TokenType, PROPERTY_MAPPINGS, STATE_MAPPINGS, CONNECTORS
from .ast_nodes import (
    StylesheetNode, RuleNode, DeclarationNode,
    MediaRuleNode, VariableNode, KeyframeNode, KeyframeFrameNode, ASTNode
)

# Properties that are typically unitless numbers
UNITLESS_PROPERTIES = {
    "line-height", "opacity", "z-index", "font-weight", "flex",
    "flex-grow", "flex-shrink", "order"
}

def _format_css_value(prop: str, raw_val: str) -> str:
    """Auto-appends px for bare numbers on length/size properties."""
    val = raw_val.strip()
    if val.isdigit() and prop not in UNITLESS_PROPERTIES:
        return f"{val}px"
    return val

class ENLGDParser:
    """Builds a StylesheetNode AST from tokens."""

    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def parse(self) -> StylesheetNode:
        stylesheet = StylesheetNode()

        while not self._is_at_end():
            self._skip_newlines()
            if self._is_at_end():
                break

            t = self._peek()

            # 1. CSS Variables: define [type] "name" as [value]
            if t.type == TokenType.KEYWORD and t.value == "define":
                var_node = self._parse_variable()
                if var_node:
                    stylesheet.variables.append(var_node)
                continue

            # 2. Keyframes: animation "name": ... end
            if t.type == TokenType.KEYWORD and t.value == "animation":
                kf_node = self._parse_keyframe()
                if kf_node:
                    stylesheet.keyframes.append(kf_node)
                continue

            # 3. Media Queries: when screen is ... apply:
            if t.type == TokenType.KEYWORD and t.value == "when" and self._peek_offset(1) and self._peek_offset(1).value == "screen":
                media_node = self._parse_media_query()
                if media_node:
                    stylesheet.media_rules.append(media_node)
                continue

            # 4. Pseudo-state Rules: when [selector] is [state] apply:
            if t.type == TokenType.KEYWORD and t.value == "when":
                rule_node = self._parse_when_rule()
                if rule_node:
                    stylesheet.rules.append(rule_node)
                continue

            # 5. Standard Rule Blocks: for [selector] apply: | style [selector]: | apply to [selector]:
            if (t.type == TokenType.KEYWORD and t.value in ("for", "style", "apply")) or t.type in (TokenType.STRING, TokenType.IDENTIFIER):
                rule_node = self._parse_rule()
                if rule_node:
                    stylesheet.rules.append(rule_node)
                continue

            # Skip unmatched token
            self._advance()

        return stylesheet

    # --- Parser Handlers ---

    def _parse_variable(self) -> Optional[VariableNode]:
        # define [type] "name" as [value]
        self._advance() # consume 'define'

        var_type = "value"
        if not self._is_at_end() and self._peek().value in ("color", "size", "spacing", "font", "value"):
            var_type = self._advance().value

        name = ""
        if not self._is_at_end() and self._peek().type in (TokenType.STRING, TokenType.IDENTIFIER):
            name = self._advance().value.strip('"\'')

        # consume 'as' or '=' if present
        if not self._is_at_end() and self._peek().value in ("as", "="):
            self._advance()

        # collect value tokens until end of line
        val_parts = []
        while not self._is_at_end() and self._peek().type not in (TokenType.NEWLINE, TokenType.EOF, TokenType.DEDENT):
            val_tok = self._advance()
            val_parts.append(val_tok.value.strip('"\'') if val_tok.type == TokenType.STRING else val_tok.value)

        val_str = " ".join(val_parts)
        if var_type == "size" and val_str.isdigit():
            val_str = f"{val_str}px"

        return VariableNode(var_type=var_type, name=name, value=val_str)

    def _parse_rule(self) -> Optional[RuleNode]:
        # for [selector] apply: | apply to [selector]: | style [selector]:
        t = self._peek()
        if t.type == TokenType.KEYWORD:
            kw = self._advance().value
            if kw == "apply" and not self._is_at_end() and self._peek().value == "to":
                self._advance() # consume 'to'

        # Extract Selector
        selector_parts = []
        while not self._is_at_end() and self._peek().type not in (TokenType.SYMBOL, TokenType.NEWLINE, TokenType.INDENT):
            tok = self._peek()
            if tok.value == "apply":
                self._advance()
                break
            selector_parts.append(tok.value.strip('"\'') if tok.type == TokenType.STRING else tok.value)
            self._advance()

        # Consume ':' if present
        if not self._is_at_end() and self._peek().type == TokenType.SYMBOL and self._peek().value == ":":
            self._advance()

        selector = " ".join(selector_parts).strip()
        declarations = self._parse_declarations_block()

        return RuleNode(selector=selector, declarations=declarations)

    def _parse_when_rule(self) -> Optional[RuleNode]:
        # when [selector] is [state] apply:
        self._advance() # consume 'when'

        selector_parts = []
        while not self._is_at_end() and self._peek().value not in ("is", "apply", ":"):
            tok = self._advance()
            selector_parts.append(tok.value.strip('"\'') if tok.type == TokenType.STRING else tok.value)

        # consume 'is'
        if not self._is_at_end() and self._peek().value == "is":
            self._advance()

        # extract state (e.g. hovered -> :hover)
        state = ":hover"
        if not self._is_at_end() and self._peek().type not in (TokenType.KEYWORD, TokenType.SYMBOL, TokenType.NEWLINE):
            state_tok = self._advance()
            raw_state = state_tok.value
            if raw_state.startswith(":"):
                state = raw_state
            else:
                state = STATE_MAPPINGS.get(raw_state.lower(), f":{raw_state}")

        # consume 'apply' or ':'
        if not self._is_at_end() and self._peek().value == "apply":
            self._advance()
        if not self._is_at_end() and self._peek().type == TokenType.SYMBOL and self._peek().value == ":":
            self._advance()

        base_sel = " ".join(selector_parts).strip()
        full_selector = f"{base_sel}{state}"
        declarations = self._parse_declarations_block()

        return RuleNode(selector=full_selector, declarations=declarations)

    def _parse_media_query(self) -> Optional[MediaRuleNode]:
        # when screen is smaller than 768 apply:
        # when screen is larger than 1200 apply:
        # when screen is portrait apply:
        self._advance() # consume 'when'
        if not self._is_at_end() and self._peek().value == "screen":
            self._advance() # consume 'screen'
        if not self._is_at_end() and self._peek().value == "is":
            self._advance() # consume 'is'

        query = "(max-width: 768px)"
        if not self._is_at_end():
            cond = self._advance().value.lower()
            if cond in ("smaller", "max"):
                if not self._is_at_end() and self._peek().value == "than":
                    self._advance() # consume 'than'
                val = self._advance().value if not self._is_at_end() else "768"
                val_formatted = f"{val}px" if val.isdigit() else val
                query = f"(max-width: {val_formatted})"
            elif cond in ("larger", "min"):
                if not self._is_at_end() and self._peek().value == "than":
                    self._advance() # consume 'than'
                val = self._advance().value if not self._is_at_end() else "1200"
                val_formatted = f"{val}px" if val.isdigit() else val
                query = f"(min-width: {val_formatted})"
            elif cond == "portrait":
                query = "(orientation: portrait)"
            elif cond == "landscape":
                query = "(orientation: landscape)"

        # consume 'apply' or ':'
        if not self._is_at_end() and self._peek().value == "apply":
            self._advance()
        if not self._is_at_end() and self._peek().type == TokenType.SYMBOL and self._peek().value == ":":
            self._advance()

        # Parse nested rules inside media query
        rules = []
        self._skip_newlines()
        if not self._is_at_end() and self._peek().type == TokenType.INDENT:
            self._advance()

        while not self._is_at_end():
            self._skip_newlines()
            if self._is_at_end():
                break
            if self._peek().value in ("end", "finish"):
                self._advance()
                break
            if self._peek().type == TokenType.DEDENT:
                self._advance()
                self._skip_newlines()
                if self._is_at_end() or self._peek().value in ("end", "finish"):
                    if not self._is_at_end() and self._peek().value in ("end", "finish"):
                        self._advance()
                    break
                if self._peek().type == TokenType.DEDENT:
                    self._advance()
                    break
                if self._peek().value not in ("for", "style", "apply", "when") and self._peek().type not in (TokenType.STRING, TokenType.IDENTIFIER):
                    break

            t = self._peek()
            if t.value == "when":
                rule = self._parse_when_rule()
                if rule:
                    rules.append(rule)
            elif (t.type == TokenType.KEYWORD and t.value in ("for", "style", "apply")) or t.type in (TokenType.STRING, TokenType.IDENTIFIER):
                rule = self._parse_rule()
                if rule:
                    rules.append(rule)
            else:
                self._advance()
            self._skip_newlines()

        return MediaRuleNode(query=query, rules=rules)

    def _parse_keyframe(self) -> Optional[KeyframeNode]:
        # animation "name":
        self._advance() # consume 'animation'
        name = "custom-anim"
        if not self._is_at_end() and self._peek().type in (TokenType.STRING, TokenType.IDENTIFIER):
            name = self._advance().value.strip('"\'')
        if not self._is_at_end() and self._peek().type == TokenType.SYMBOL and self._peek().value == ":":
            self._advance()

        frames = []
        self._skip_newlines()
        if not self._is_at_end() and self._peek().type == TokenType.INDENT:
            self._advance()

        while not self._is_at_end():
            self._skip_newlines()
            if self._is_at_end():
                break
            if self._peek().value in ("end", "finish"):
                self._advance()
                break
            if self._peek().type == TokenType.DEDENT:
                self._advance()
                self._skip_newlines()
                if self._is_at_end() or self._peek().value in ("end", "finish"):
                    if not self._is_at_end() and self._peek().value in ("end", "finish"):
                        self._advance()
                    break
                if self._peek().type == TokenType.DEDENT:
                    self._advance()
                    break
                if self._peek().value not in ("at", "from", "to") and self._peek().type != TokenType.NUMBER:
                    break

            # at N percent: / from: / to:
            stop = "0%"
            if not self._is_at_end() and self._peek().value == "at":
                self._advance() # consume 'at'
                num = self._advance().value if not self._is_at_end() else "0"
                if not self._is_at_end() and self._peek().value in ("percent", "%"):
                    self._advance()
                stop = f"{num}%" if not num.endswith("%") else num
            elif not self._is_at_end() and self._peek().value in ("from", "to"):
                stop = self._advance().value
            elif not self._is_at_end() and self._peek().type == TokenType.NUMBER:
                num = self._advance().value
                if not self._is_at_end() and self._peek().value in ("percent", "%"):
                    self._advance()
                stop = f"{num}%" if not num.endswith("%") else num

            if not self._is_at_end() and self._peek().type == TokenType.SYMBOL and self._peek().value == ":":
                self._advance()

            decls = self._parse_declarations_block()
            frames.append(KeyframeFrameNode(stop=stop, declarations=decls))
            self._skip_newlines()

        return KeyframeNode(name=name, frames=frames)

    def _parse_declarations_block(self) -> List[DeclarationNode]:
        """Parses declarations inside a rule, handling connectors, gradients, variables."""
        declarations: List[DeclarationNode] = []
        self._skip_newlines()

        has_indent = not self._is_at_end() and self._peek().type == TokenType.INDENT
        if has_indent:
            self._advance()

        while not self._is_at_end():
            self._skip_newlines()
            if self._is_at_end() or self._peek().type == TokenType.DEDENT:
                break
            if self._peek().value in ("end", "finish"):
                self._advance()
                break

            # Parse line with possible connector chaining
            line_decls = self._parse_declaration_line()
            declarations.extend(line_decls)
            self._skip_newlines()

        if has_indent and not self._is_at_end() and self._peek().type == TokenType.DEDENT:
            self._advance()

        # Consume trailing 'end' or 'finish' for this block if present
        self._skip_newlines()
        if not self._is_at_end() and self._peek().value in ("end", "finish"):
            self._advance()

        return declarations

    def _parse_declaration_line(self) -> List[DeclarationNode]:
        """Parses a single declaration or multiple declarations linked by connectors ('and', 'with', 'also')."""
        decls: List[DeclarationNode] = []

        while not self._is_at_end() and self._peek().type not in (TokenType.NEWLINE, TokenType.EOF, TokenType.DEDENT):
            t = self._peek()

            # End block keyword
            if t.value in ("end", "finish"):
                break

            # Skip connector if at start of chain segment
            if t.type == TokenType.CONNECTOR:
                self._advance()
                continue

            # Must be a property or identifier
            if t.type in (TokenType.PROPERTY, TokenType.IDENTIFIER, TokenType.KEYWORD):
                prop_tok = self._advance()
                prop_name = PROPERTY_MAPPINGS.get(prop_tok.value.lower(), prop_tok.value)

                # Parse value for this property
                val_parts = []
                while not self._is_at_end() and self._peek().type not in (TokenType.NEWLINE, TokenType.EOF, TokenType.DEDENT, TokenType.CONNECTOR):
                    tok = self._peek()

                    # Handle 'use [color|size|value] "name"' -> var(--name)
                    if tok.value == "use":
                        self._advance()
                        if not self._is_at_end() and self._peek().value in ("color", "size", "spacing", "font", "value"):
                            self._advance()
                        var_name = self._advance().value.strip('"\'') if not self._is_at_end() else "var"
                        val_parts.append(f"var(--{var_name})")
                        continue

                    # Handle 'gradient from "A" to "B" at 135 degrees'
                    if tok.value == "gradient":
                        self._advance()
                        grad_val = self._parse_gradient_value()
                        val_parts.append(grad_val)
                        continue

                    # Handle 'percent', 'vh', 'vw', 'degrees' units following numbers
                    if tok.value in ("percent", "%"):
                        self._advance()
                        if val_parts and val_parts[-1].isdigit():
                            val_parts[-1] = f"{val_parts[-1]}%"
                        continue

                    if tok.value in ("viewport-height", "vh"):
                        self._advance()
                        if val_parts and val_parts[-1].isdigit():
                            val_parts[-1] = f"{val_parts[-1]}vh"
                        continue

                    if tok.value in ("viewport-width", "vw"):
                        self._advance()
                        if val_parts and val_parts[-1].isdigit():
                            val_parts[-1] = f"{val_parts[-1]}vw"
                        continue

                    if tok.value in ("degrees", "deg"):
                        self._advance()
                        if val_parts and val_parts[-1].isdigit():
                            val_parts[-1] = f"{val_parts[-1]}deg"
                        continue

                    # Regular value token
                    self._advance()
                    v = tok.value.strip('"\'') if tok.type == TokenType.STRING else tok.value
                    val_parts.append(v)

                raw_val = " ".join(val_parts)
                final_val = _format_css_value(prop_name, raw_val)
                decls.append(DeclarationNode(property_name=prop_name, value=final_val))
            else:
                self._advance()

        return decls

    def _parse_gradient_value(self) -> str:
        # from "#1e3c72" to "#2a5298" at 135 degrees
        color1 = "#1e3c72"
        color2 = "#2a5298"
        deg = "135deg"

        while not self._is_at_end() and self._peek().type not in (TokenType.NEWLINE, TokenType.EOF, TokenType.DEDENT, TokenType.CONNECTOR):
            tok = self._advance()
            if tok.value == "from" and not self._is_at_end():
                color1 = self._advance().value.strip('"\'')
            elif tok.value == "to" and not self._is_at_end():
                color2 = self._advance().value.strip('"\'')
            elif tok.value in ("at", "degrees", "deg") and not self._is_at_end():
                num = self._advance().value
                if not self._is_at_end() and self._peek().value in ("degrees", "deg"):
                    self._advance()
                deg = f"{num}deg" if not num.endswith("deg") else num

        return f"linear-gradient({deg}, {color1}, {color2})"

    def _skip_newlines(self):
        while not self._is_at_end() and self._peek().type == TokenType.NEWLINE:
            self._advance()

    def _peek(self) -> Token:
        return self.tokens[self.pos]

    def _peek_offset(self, offset: int) -> Optional[Token]:
        if self.pos + offset < len(self.tokens):
            return self.tokens[self.pos + offset]
        return None

    def _advance(self) -> Token:
        tok = self.tokens[self.pos]
        if self.pos < len(self.tokens) - 1:
            self.pos += 1
        return tok

    def _is_at_end(self) -> bool:
        return self.pos >= len(self.tokens) or self.tokens[self.pos].type == TokenType.EOF

enlgdb/ast_nodes.py:
"""AST Node definitions for enlgdb."""

from dataclasses import dataclass, field
from typing import List, Optional, Any, Dict


class ASTNode:
    """Base class for all AST nodes."""
    pass


@dataclass
class DomainHeaderNode(ASTNode):
    domain: str = "enlgdb"


@dataclass
class CreateDatabaseNode(ASTNode):
    db_name: str


@dataclass
class UseDatabaseNode(ASTNode):
    db_name: str


@dataclass
class ShowDatabasesNode(ASTNode):
    pass


@dataclass
class ShowTablesNode(ASTNode):
    db_name: Optional[str] = None


@dataclass
class DropDatabaseNode(ASTNode):
    db_name: str
    confirmation_token: str


@dataclass
class HintNode(ASTNode):
    hints: Dict[str, Any] = field(default_factory=dict)


@dataclass
class ColumnDefNode(ASTNode):
    name: str
    data_type: str
    is_primary_key: bool = False
    autoincrement: bool = False
    not_null: bool = False
    unique: bool = False
    default_value: Optional[Any] = None
    references_table: Optional[str] = None
    references_column: Optional[str] = None
    hints: Dict[str, Any] = field(default_factory=dict)


@dataclass
class CreateTableNode(ASTNode):
    table_name: str
    columns: List[ColumnDefNode] = field(default_factory=list)
    if_not_exists: bool = True
    hints: Dict[str, Any] = field(default_factory=dict)


@dataclass
class InsertNode(ASTNode):
    table_name: str
    values: Dict[str, Any] = field(default_factory=dict)
    hints: Dict[str, Any] = field(default_factory=dict)


@dataclass
class BinaryOpNode(ASTNode):
    left: Any
    operator: str
    right: Any


@dataclass
class UnaryOpNode(ASTNode):
    operator: str
    operand: Any


@dataclass
class FunctionCallNode(ASTNode):
    name: str
    arguments: List[Any] = field(default_factory=list)


@dataclass
class IdentifierNode(ASTNode):
    name: str


@dataclass
class LiteralNode(ASTNode):
    value: Any
    literal_type: str  # "string", "number", "boolean", "null"


@dataclass
class OrderByNode(ASTNode):
    field: str
    direction: str = "ASC"  # "ASC" or "DESC"


@dataclass
class JoinNode(ASTNode):
    join_type: str  # "INNER", "LEFT", "RIGHT"
    table_name: str
    left_col: str
    right_col: str


@dataclass
class SelectNode(ASTNode):
    fields: List[Any]
    table_name: str
    joins: List[JoinNode] = field(default_factory=list)
    where: Optional[Any] = None
    order_by: Optional[OrderByNode] = None
    limit: Optional[int] = None
    offset: Optional[int] = None
    distinct: bool = False
    hints: Dict[str, Any] = field(default_factory=dict)


@dataclass
class UpdateNode(ASTNode):
    table_name: str
    assignments: Dict[str, Any] = field(default_factory=dict)
    where: Optional[Any] = None
    hints: Dict[str, Any] = field(default_factory=dict)


@dataclass
class DeleteNode(ASTNode):
    table_name: str
    is_all: bool = False
    where: Optional[Any] = None
    confirmation_token: Optional[str] = None
    hints: Dict[str, Any] = field(default_factory=dict)


@dataclass
class DropTableNode(ASTNode):
    table_name: str
    confirmation_token: str
    if_exists: bool = True


@dataclass
class TruncateTableNode(ASTNode):
    table_name: str
    confirmation_token: str


@dataclass
class AlterTableNode(ASTNode):
    table_name: str
    action: str  # "ADD_COLUMN", "DROP_COLUMN"
    column_def: Optional[ColumnDefNode] = None
    drop_column: Optional[str] = None
    confirmation_token: Optional[str] = None


@dataclass
class ProgramNode(ASTNode):
    header: Optional[DomainHeaderNode]
    statements: List[ASTNode] = field(default_factory=list)

enlgdb/emitter.py:
"""Parameterized SQL emitter for enlgdb targeting SQLite, PostgreSQL, and ANSI SQL."""

from typing import List, Tuple, Any, Dict
from enlgdb.ast_nodes import (
    ProgramNode, CreateTableNode, ColumnDefNode, InsertNode,
    CreateDatabaseNode, UseDatabaseNode, ShowDatabasesNode, ShowTablesNode, DropDatabaseNode,
    SelectNode, UpdateNode, DeleteNode, DropTableNode,
    TruncateTableNode, AlterTableNode, BinaryOpNode,
    UnaryOpNode, FunctionCallNode, IdentifierNode, LiteralNode, ASTNode, HintNode
)


class SQLEmitter:
    def __init__(self, dialect: str = "sqlite"):
        self.dialect = dialect.lower()

    def emit(self, node: ProgramNode) -> List[Tuple[str, List[Any]]]:
        """Translates an enlgdb Program AST into a list of parameterized (sql_string, params_list)."""
        results: List[Tuple[str, List[Any]]] = []
        for stmt in node.statements:
            res = self.emit_statement(stmt)
            if res:
                results.append(res)
        return results

    def emit_statement(self, stmt: ASTNode) -> Tuple[str, List[Any]]:
        if isinstance(stmt, HintNode):
            hint_str = ", ".join(f"{k}={v!r}" for k, v in stmt.hints.items())
            return f"-- HINT: {hint_str}", []
        elif isinstance(stmt, CreateDatabaseNode):
            if self.dialect == "sqlite":
                return f'ATTACH DATABASE "{stmt.db_name}.db" AS "{stmt.db_name}";', []
            return f'CREATE DATABASE "{stmt.db_name}";', []
        elif isinstance(stmt, UseDatabaseNode):
            if self.dialect == "sqlite":
                return f'-- Switching active database to: {stmt.db_name}', []
            return f'USE "{stmt.db_name}";', []
        elif isinstance(stmt, ShowDatabasesNode):
            if self.dialect == "sqlite":
                return 'PRAGMA database_list;', []
            return 'SHOW DATABASES;', []
        elif isinstance(stmt, ShowTablesNode):
            if self.dialect == "sqlite":
                return "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%';", []
            return f'SHOW TABLES FROM "{stmt.db_name}";' if stmt.db_name else 'SHOW TABLES;', []
        elif isinstance(stmt, DropDatabaseNode):
            if self.dialect == "sqlite":
                return f'DETACH DATABASE "{stmt.db_name}";', []
            return f'DROP DATABASE IF EXISTS "{stmt.db_name}";', []
        elif isinstance(stmt, CreateTableNode):
            return self.emit_create_table(stmt)
        elif isinstance(stmt, InsertNode):
            return self.emit_insert(stmt)
        elif isinstance(stmt, SelectNode):
            return self.emit_select(stmt)
        elif isinstance(stmt, UpdateNode):
            return self.emit_update(stmt)
        elif isinstance(stmt, DeleteNode):
            return self.emit_delete(stmt)
        elif isinstance(stmt, DropTableNode):
            return self.emit_drop_table(stmt)
        elif isinstance(stmt, TruncateTableNode):
            return self.emit_truncate_table(stmt)
        elif isinstance(stmt, AlterTableNode):
            return self.emit_alter_table(stmt)
        else:
            raise ValueError(f"Unknown statement node type: {type(stmt)}")

    def emit_create_table(self, node: CreateTableNode) -> Tuple[str, List[Any]]:
        col_defs: List[str] = []
        for col in node.columns:
            parts = [f'"{col.name}"']
            # Type mapping
            t = col.data_type
            if self.dialect == "sqlite" and t == "BOOLEAN":
                t = "INTEGER"
            parts.append(t)

            if col.is_primary_key:
                parts.append("PRIMARY KEY")
                if col.autoincrement:
                    if self.dialect == "sqlite":
                        parts.append("AUTOINCREMENT")
                    elif self.dialect == "postgres":
                        # In Postgres serial handles it, or GENERATED ALWAYS
                        pass
            if col.not_null:
                parts.append("NOT NULL")
            if col.unique:
                parts.append("UNIQUE")
            if col.default_value is not None:
                if isinstance(col.default_value, str) and not col.default_value.upper().startswith("CURRENT_"):
                    parts.append(f"DEFAULT '{col.default_value}'")
                else:
                    parts.append(f"DEFAULT {col.default_value}")
            if col.references_table:
                ref = f'REFERENCES "{col.references_table}"'
                if col.references_column:
                    ref += f'("{col.references_column}")'
                parts.append(ref)

            col_defs.append("    " + " ".join(parts))

        if_not_exists = "IF NOT EXISTS " if node.if_not_exists else ""
        sql = f'CREATE TABLE {if_not_exists}"{node.table_name}" (\n' + ",\n".join(col_defs) + "\n);"
        return sql, []

    def emit_insert(self, node: InsertNode) -> Tuple[str, List[Any]]:
        columns = list(node.values.keys())
        params: List[Any] = []
        placeholders: List[str] = []

        for col in columns:
            val_node = node.values[col]
            sql_expr, val_params = self.emit_expression(val_node)
            placeholders.append(sql_expr)
            params.extend(val_params)

        cols_str = ", ".join([f'"{c}"' for c in columns])
        vals_str = ", ".join(placeholders)
        sql = f'INSERT INTO "{node.table_name}" ({cols_str}) VALUES ({vals_str});'
        return sql, params

    def emit_select(self, node: SelectNode) -> Tuple[str, List[Any]]:
        params: List[Any] = []
        fields_str_list: List[str] = []

        for f in node.fields:
            if f == "*":
                fields_str_list.append("*")
            elif isinstance(f, FunctionCallNode):
                args_str = ", ".join([f'"{a}"' if a != "*" else "*" for a in f.arguments])
                fields_str_list.append(f"{f.name}({args_str})")
            else:
                fields_str_list.append(f'"{f}"' if "." not in f else f)

        distinct_kw = "DISTINCT " if node.distinct else ""
        indexed_by = ""
        hint_comment = ""
        if node.hints:
            if "index" in node.hints and self.dialect == "sqlite":
                indexed_by = f' INDEXED BY "{node.hints["index"]}"'
            hint_str = ", ".join(f"{k}={v!r}" for k, v in node.hints.items())
            hint_comment = f" /*+ HINT({hint_str}) */"

        sql_parts = [f'SELECT {distinct_kw}{", ".join(fields_str_list)}{hint_comment} FROM "{node.table_name}"{indexed_by}']

        # Joins
        for j in node.joins:
            sql_parts.append(f'{j.join_type} JOIN "{j.table_name}" ON {j.left_col} = {j.right_col}')

        # Where
        if node.where:
            where_sql, where_params = self.emit_expression(node.where)
            sql_parts.append(f"WHERE {where_sql}")
            params.extend(where_params)

        # Order by
        if node.order_by:
            sql_parts.append(f'ORDER BY "{node.order_by.field}" {node.order_by.direction}')

        # Limit & Offset
        if node.limit is not None:
            sql_parts.append(f"LIMIT {node.limit}")
        if node.offset is not None:
            sql_parts.append(f"OFFSET {node.offset}")

        return " ".join(sql_parts) + ";", params

    def emit_update(self, node: UpdateNode) -> Tuple[str, List[Any]]:
        params: List[Any] = []
        set_parts: List[str] = []

        for col, val_expr in node.assignments.items():
            expr_sql, expr_params = self.emit_expression(val_expr)
            set_parts.append(f'"{col}" = {expr_sql}')
            params.extend(expr_params)

        sql_parts = [f'UPDATE "{node.table_name}" SET {", ".join(set_parts)}']
        if node.where:
            where_sql, where_params = self.emit_expression(node.where)
            sql_parts.append(f"WHERE {where_sql}")
            params.extend(where_params)

        return " ".join(sql_parts) + ";", params

    def emit_delete(self, node: DeleteNode) -> Tuple[str, List[Any]]:
        params: List[Any] = []
        sql_parts = [f'DELETE FROM "{node.table_name}"']
        if node.where:
            where_sql, where_params = self.emit_expression(node.where)
            sql_parts.append(f"WHERE {where_sql}")
            params.extend(where_params)

        return " ".join(sql_parts) + ";", params

    def emit_drop_table(self, node: DropTableNode) -> Tuple[str, List[Any]]:
        if_exists = "IF EXISTS " if node.if_exists else ""
        sql = f'DROP TABLE {if_exists}"{node.table_name}";'
        return sql, []

    def emit_truncate_table(self, node: TruncateTableNode) -> Tuple[str, List[Any]]:
        if self.dialect == "sqlite":
            sql = f'DELETE FROM "{node.table_name}";'
        else:
            sql = f'TRUNCATE TABLE "{node.table_name}";'
        return sql, []

    def emit_alter_table(self, node: AlterTableNode) -> Tuple[str, List[Any]]:
        if node.action == "ADD_COLUMN" and node.column_def:
            col = node.column_def
            parts = [f'"{col.name}"', col.data_type]
            if col.not_null:
                parts.append("NOT NULL")
            if col.default_value is not None:
                parts.append(f"DEFAULT '{col.default_value}'")
            return f'ALTER TABLE "{node.table_name}" ADD COLUMN {" ".join(parts)};', []
        elif node.action == "DROP_COLUMN" and node.drop_column:
            return f'ALTER TABLE "{node.table_name}" DROP COLUMN "{node.drop_column}";', []
        raise ValueError("Invalid AlterTable action")

    def emit_expression(self, node: Any) -> Tuple[str, List[Any]]:
        if isinstance(node, LiteralNode):
            if self.dialect == "postgres":
                return "$?", [node.value]
            else:
                return "?", [node.value]
        elif isinstance(node, IdentifierNode):
            return f'"{node.name}"' if "." not in node.name else node.name, []
        elif isinstance(node, BinaryOpNode):
            l_sql, l_params = self.emit_expression(node.left)
            r_sql, r_params = self.emit_expression(node.right)
            op = node.operator
            if op == "IS":
                op = "="
            return f"({l_sql} {op} {r_sql})", l_params + r_params
        elif isinstance(node, UnaryOpNode):
            expr_sql, params = self.emit_expression(node.operand)
            return f"{node.operator} ({expr_sql})", params
        elif isinstance(node, FunctionCallNode):
            args_sql = []
            params = []
            for arg in node.arguments:
                if arg == "*":
                    args_sql.append("*")
                else:
                    a_sql, a_params = self.emit_expression(arg)
                    args_sql.append(a_sql)
                    params.extend(a_params)
            return f"{node.name}({', '.join(args_sql)})", params
        elif isinstance(node, (int, float, str, bool)):
            return "?", [node]
        else:
            return str(node), []

