"""enlgm Abstract Syntax Tree (AST) Node Definitions.

Defines dataclasses for the Flutter / Dart Widget Tree, Navigation, State Management,
Lifecycle hooks, Network operations, and custom Widget Blueprints.
"""

from dataclasses import dataclass, field
from typing import List, Dict, Any, Optional

@dataclass
class ASTNode:
    pass

@dataclass
class MobileRootNode(ASTNode):
    imports: List['FlutterImportNode'] = field(default_factory=list)
    app: Optional['AppDefNode'] = None
    screens: List['ScreenDefNode'] = field(default_factory=list)
    blueprints: List['WidgetBlueprintNode'] = field(default_factory=list)
    raw_dart_blocks: List['RawDartNode'] = field(default_factory=list)

@dataclass
class FlutterImportNode(ASTNode):
    package_name: str
    is_flutter: bool = True
    as_alias: Optional[str] = None

@dataclass
class AppDefNode(ASTNode):
    name: str
    theme: str = "dark"           # "dark" or "light"
    primary_color: Optional[str] = None  # Hex or named color
    home_screen: str = "HomeScreen"

@dataclass
class ScreenDefNode(ASTNode):
    name: str
    is_stateful: bool = False
    title: Optional[str] = None
    state_vars: List['StateDeclNode'] = field(default_factory=list)
    lifecycle_inits: List[ASTNode] = field(default_factory=list)
    lifecycle_disposes: List[ASTNode] = field(default_factory=list)
    app_bar: Optional['AppBarNode'] = None
    body: List[ASTNode] = field(default_factory=list)
    fab: Optional['ButtonWidgetNode'] = None
    bottom_bar: Optional['BottomNavNode'] = None
    drawer: Optional['DrawerNode'] = None
    methods: List['MethodDefNode'] = field(default_factory=list)

@dataclass
class MethodDefNode(ASTNode):
    name: str
    params: List[str] = field(default_factory=list)
    body: List[ASTNode] = field(default_factory=list)

@dataclass
class StateDeclNode(ASTNode):
    name: str
    initial_val: str
    type_hint: Optional[str] = None

@dataclass
class StateAssignNode(ASTNode):
    target: str
    op: str = "="   # "=", "+=", "-="
    value: str = ""

@dataclass
class NavigationNode(ASTNode):
    action: str           # "push", "push_data", "pop", "pop_result", "replace", "clear"
    target_screen: str = ""
    data_expr: Optional[str] = None

@dataclass
class ToastFeedbackNode(ASTNode):
    feedback_type: str    # "toast", "snackbar", "alert"
    message_expr: str = ""
    duration: Optional[int] = None
    confirm_label: Optional[str] = None
    confirm_body: List[ASTNode] = field(default_factory=list)
    cancel_label: Optional[str] = None

@dataclass
class NetworkCallNode(ASTNode):
    method: str           # "GET" or "POST"
    url_expr: str = ""
    body_expr: Optional[str] = None
    on_success_param: str = "result"
    on_success_body: List[ASTNode] = field(default_factory=list)
    on_failure_param: str = "error"
    on_failure_body: List[ASTNode] = field(default_factory=list)

@dataclass
class WidgetNode(ASTNode):
    widget_type: str      # "column", "row", "stack", "center", "scroll", "safearea", "expanded", "container", "card", "padding"
    props: Dict[str, Any] = field(default_factory=dict)
    children: List[ASTNode] = field(default_factory=list)
    on_tap_body: List[ASTNode] = field(default_factory=list)

@dataclass
class TextWidgetNode(ASTNode):
    text_expr: str
    props: Dict[str, Any] = field(default_factory=dict)

@dataclass
class IconWidgetNode(ASTNode):
    icon_name: str
    props: Dict[str, Any] = field(default_factory=dict)

@dataclass
class ImageWidgetNode(ASTNode):
    source_type: str      # "network" or "asset"
    path_or_url: str
    width: Optional[str] = None
    height: Optional[str] = None
    props: Dict[str, Any] = field(default_factory=dict)

@dataclass
class AvatarWidgetNode(ASTNode):
    source_type: str      # "network", "asset", "initials"
    value: str
    size: Optional[str] = None
    props: Dict[str, Any] = field(default_factory=dict)

@dataclass
class ButtonWidgetNode(ASTNode):
    btn_type: str         # "elevated", "text", "icon", "fab"
    label_expr: Optional[str] = None
    icon_name: Optional[str] = None
    props: Dict[str, Any] = field(default_factory=dict)
    on_tap_body: List[ASTNode] = field(default_factory=list)

@dataclass
class InputWidgetNode(ASTNode):
    id_name: str
    placeholder: str = ""
    input_type: str = "text"  # "text", "email", "password", "number"
    is_hidden: bool = False
    lines: int = 1
    props: Dict[str, Any] = field(default_factory=dict)
    on_submit_body: List[ASTNode] = field(default_factory=list)

@dataclass
class SpacerWidgetNode(ASTNode):
    is_expandable: bool = False
    height: Optional[str] = None
    width: Optional[str] = None

@dataclass
class DividerWidgetNode(ASTNode):
    color: Optional[str] = None
    thickness: Optional[str] = None

@dataclass
class ChipWidgetNode(ASTNode):
    label_expr: str
    props: Dict[str, Any] = field(default_factory=dict)

@dataclass
class ProgressWidgetNode(ASTNode):
    is_circular: bool = True
    color: Optional[str] = None
    size: Optional[str] = None

@dataclass
class ControlWidgetNode(ASTNode):
    control_type: str     # "switch", "slider", "checkbox", "dropdown"
    value_var: str
    label: Optional[str] = None
    options: List[str] = field(default_factory=list)
    min_val: float = 0.0
    max_val: float = 100.0
    on_change_body: List[ASTNode] = field(default_factory=list)

@dataclass
class ListViewWidgetNode(ASTNode):
    items_expr: str
    item_var: str = "item"
    template: List[ASTNode] = field(default_factory=list)

@dataclass
class GridViewWidgetNode(ASTNode):
    columns: int = 2
    gap: int = 12
    children: List[ASTNode] = field(default_factory=list)

@dataclass
class AppBarNode(ASTNode):
    title_expr: str = ""
    has_back_btn: bool = True
    actions: List[ASTNode] = field(default_factory=list)

@dataclass
class BottomNavItem(ASTNode):
    icon_name: str
    label: str
    on_tap_body: List[ASTNode] = field(default_factory=list)

@dataclass
class BottomNavNode(ASTNode):
    items: List[BottomNavItem] = field(default_factory=list)

@dataclass
class DrawerItem(ASTNode):
    icon_name: str
    label: str
    on_tap_body: List[ASTNode] = field(default_factory=list)

@dataclass
class DrawerNode(ASTNode):
    header_children: List[ASTNode] = field(default_factory=list)
    items: List[DrawerItem] = field(default_factory=list)

@dataclass
class WidgetBlueprintNode(ASTNode):
    name: str
    params: List[str] = field(default_factory=list)
    body: List[ASTNode] = field(default_factory=list)

@dataclass
class BlueprintInstanceNode(ASTNode):
    name: str
    named_args: Dict[str, str] = field(default_factory=dict)

@dataclass
class CallFunctionNode(ASTNode):
    fn_name: str
    args: List[str] = field(default_factory=list)

@dataclass
class RawDartNode(ASTNode):
    code: str

enlgm/emitter.py:
"""enlgm Code Emitter.

Translates the Flutter / Dart AST (from ENLGMParser) into standard, clean,
compile-ready Dart source code targeting Flutter apps (lib/main.dart).
"""

from typing import List, Dict, Any, Optional
from .ast_nodes import (
    ASTNode, MobileRootNode, FlutterImportNode, AppDefNode, ScreenDefNode,
    WidgetNode, TextWidgetNode, IconWidgetNode, ImageWidgetNode, AvatarWidgetNode,
    ButtonWidgetNode, InputWidgetNode, SpacerWidgetNode, DividerWidgetNode,
    ChipWidgetNode, ProgressWidgetNode, ControlWidgetNode, ListViewWidgetNode,
    GridViewWidgetNode, AppBarNode, BottomNavNode, BottomNavItem, DrawerNode,
    DrawerItem, NavigationNode, StateDeclNode, StateAssignNode, ToastFeedbackNode,
    NetworkCallNode, RawDartNode, WidgetBlueprintNode, BlueprintInstanceNode,
    CallFunctionNode, MethodDefNode
)

def _hex_to_dart_color(hex_str: str) -> str:
    """Converts #00f2fe or #fff to Color(0xFF00F2FE) or Colors.xxx."""
    clean = hex_str.strip('"\' #')
    if len(clean) == 3:
        clean = "".join([c * 2 for c in clean])
    if len(clean) == 6:
        return f"const Color(0xFF{clean.upper()})"
    elif len(clean) == 8:
        return f"const Color(0x{clean.upper()})"

    # Named colors
    named_map = {
        "white": "Colors.white",
        "black": "Colors.black",
        "red": "Colors.red",
        "blue": "Colors.blue",
        "green": "Colors.green",
        "grey": "Colors.grey",
        "gray": "Colors.grey",
        "transparent": "Colors.transparent"
    }
    return named_map.get(clean.lower(), f"const Color(0xFF{clean.upper()})")

class ENLGMEmitter:
    """Emits clean Dart / Flutter code from MobileRootNode."""

    def __init__(self, root: MobileRootNode):
        self.root = root
        self.input_controllers: List[str] = []

    def emit(self) -> str:
        lines: List[str] = []

        # 1. Imports
        lines.append("// Generated by Enlang Mobile Compiler (.enlgm) -> Flutter / Dart")
        lines.append("import 'package:flutter/material.dart';")

        has_http = False
        for imp in self.root.imports:
            if imp.package_name == "http":
                has_http = True
                lines.append("import 'package:http/http.dart' as http;")
            elif imp.package_name == "google_fonts":
                lines.append("import 'package:google_fonts/google_fonts.dart';")
            elif imp.package_name == "provider":
                lines.append("import 'package:provider/provider.dart';")
            elif not imp.is_flutter:
                alias_clause = f" as {imp.as_alias}" if imp.as_alias else ""
                lines.append(f"import 'package:{imp.package_name}/{imp.package_name}.dart'{alias_clause};")

        # Auto-import http if any NetworkCallNode is present in AST
        if not has_http:
            lines.append("// Note: Add 'http: ^1.2.0' in pubspec.yaml if performing network requests")

        lines.append("")

        # 2. Main Entry Point
        app_node = self.root.app or AppDefNode(name="EnlangApp")
        app_class_name = f"{app_node.name}App"
        lines.append(f"void main() => runApp(const {app_class_name}());")
        lines.append("")

        # 3. MaterialApp Widget
        lines.append(f"class {app_class_name} extends StatelessWidget {{")
        lines.append(f"  const {app_class_name}({{super.key}});")
        lines.append("")
        lines.append("  @override")
        lines.append("  Widget build(BuildContext context) {")
        lines.append("    return MaterialApp(")
        lines.append(f"      title: '{app_node.name}',")
        lines.append("      debugShowCheckedModeBanner: false,")

        theme_expr = "ThemeData.dark()" if app_node.theme == "dark" else "ThemeData.light()"
        if app_node.primary_color:
            color_dart = _hex_to_dart_color(app_node.primary_color)
            lines.append(f"      theme: {theme_expr}.copyWith(")
            lines.append(f"        colorScheme: ColorScheme.{app_node.theme}(primary: {color_dart}),")
            lines.append("      ),")
        else:
            lines.append(f"      theme: {theme_expr},")

        lines.append(f"      home: const {app_node.home_screen}(),")
        lines.append("    );")
        lines.append("  }")
        lines.append("}")
        lines.append("")

        # 4. Custom Blueprints (Custom Widgets)
        for bp in self.root.blueprints:
            lines.append(self._emit_blueprint(bp))
            lines.append("")

        # 5. Screens
        for screen in self.root.screens:
            lines.append(self._emit_screen(screen))
            lines.append("")

        # 6. Raw Dart Blocks
        for raw in self.root.raw_dart_blocks:
            lines.append(raw.code)
            lines.append("")

        return "\n".join(lines)

    def _emit_blueprint(self, bp: WidgetBlueprintNode) -> str:
        lines = [
            f"class {bp.name} extends StatelessWidget {{",
        ]
        # Fields
        for p in bp.params:
            lines.append(f"  final dynamic {p};")

        # Constructor
        param_list = ", ".join([f"this.{p}" for p in bp.params])
        lines.append(f"  const {bp.name}({{{param_list}}}, {{super.key}});")
        lines.append("")
        lines.append("  @override")
        lines.append("  Widget build(BuildContext context) {")
        if bp.body:
            child_code = self._emit_widget(bp.body[0], indent=2)
            lines.append(f"    return {child_code};")
        else:
            lines.append("    return const SizedBox.shrink();")
        lines.append("  }")
        lines.append("}")
        return "\n".join(lines)

    def _emit_screen(self, screen: ScreenDefNode) -> str:
        if screen.is_stateful:
            return self._emit_stateful_screen(screen)
        else:
            return self._emit_stateless_screen(screen)

    def _emit_stateless_screen(self, screen: ScreenDefNode) -> str:
        lines = [
            f"class {screen.name} extends StatelessWidget {{",
            f"  const {screen.name}({{super.key}});",
            "",
            "  @override",
            "  Widget build(BuildContext context) {",
            "    return Scaffold("
        ]

        # App Bar
        if screen.app_bar:
            lines.append(f"      appBar: {self._emit_appbar(screen.app_bar, indent=3)},")

        # Body
        body_widget = self._emit_body_widget(screen.body, indent=3)
        lines.append(f"      body: {body_widget},")

        # FAB
        if screen.fab:
            lines.append(f"      floatingActionButton: {self._emit_fab(screen.fab, indent=3)},")

        # Bottom Bar
        if screen.bottom_bar:
            lines.append(f"      bottomNavigationBar: {self._emit_bottom_bar(screen.bottom_bar, indent=3)},")

        # Drawer
        if screen.drawer:
            lines.append(f"      drawer: {self._emit_drawer(screen.drawer, indent=3)},")

        lines.append("    );")
        lines.append("  }")
        lines.append("}")
        return "\n".join(lines)

    def _emit_stateful_screen(self, screen: ScreenDefNode) -> str:
        state_class_name = f"_{screen.name}State"
        lines = [
            f"class {screen.name} extends StatefulWidget {{",
            f"  const {screen.name}({{super.key}});",
            "",
            "  @override",
            f"  State<{screen.name}> createState() => {state_class_name}();",
            "}",
            "",
            f"class {state_class_name} extends State<{screen.name}> {{"
        ]

        # State Variables
        for var in screen.state_vars:
            lines.append(f"  dynamic {var.name} = {var.initial_val};")

        # Collect Input Controllers in screen body
        controllers = self._collect_input_controllers(screen.body)
        for ctrl_id in controllers:
            lines.append(f"  final TextEditingController _{ctrl_id}Controller = TextEditingController();")

        # Lifecycle Init
        if screen.lifecycle_inits or controllers:
            lines.append("")
            lines.append("  @override")
            lines.append("  void initState() {")
            lines.append("    super.initState();")
            for init_node in screen.lifecycle_inits:
                lines.append(f"    {self._emit_action(init_node, indent=2)}")
            lines.append("  }")

        # Lifecycle Dispose
        lines.append("")
        lines.append("  @override")
        lines.append("  void dispose() {")
        for ctrl_id in controllers:
            lines.append(f"    _{ctrl_id}Controller.dispose();")
        for disp_node in screen.lifecycle_disposes:
            lines.append(f"    {self._emit_action(disp_node, indent=2)}")
        lines.append("    super.dispose();")
        lines.append("  }")

        # Custom Methods
        for method in screen.methods:
            params_str = ", ".join(method.params)
            lines.append("")
            lines.append(f"  void {method.name}({params_str}) {{")
            for stmt in method.body:
                lines.append(f"    {self._emit_action(stmt, indent=2)}")
            lines.append("  }")

        # Build Method
        lines.append("")
        lines.append("  @override")
        lines.append("  Widget build(BuildContext context) {")
        lines.append("    return Scaffold(")

        # App Bar
        if screen.app_bar:
            lines.append(f"      appBar: {self._emit_appbar(screen.app_bar, indent=3)},")

        # Body
        body_widget = self._emit_body_widget(screen.body, indent=3)
        lines.append(f"      body: {body_widget},")

        # FAB
        if screen.fab:
            lines.append(f"      floatingActionButton: {self._emit_fab(screen.fab, indent=3)},")

        # Bottom Bar
        if screen.bottom_bar:
            lines.append(f"      bottomNavigationBar: {self._emit_bottom_bar(screen.bottom_bar, indent=3)},")

        # Drawer
        if screen.drawer:
            lines.append(f"      drawer: {self._emit_drawer(screen.drawer, indent=3)},")

        lines.append("    );")
        lines.append("  }")
        lines.append("}")
        return "\n".join(lines)

    def _collect_input_controllers(self, nodes: List[ASTNode]) -> List[str]:
        ctrls = []
        for n in nodes:
            if isinstance(n, InputWidgetNode):
                ctrls.append(n.id_name)
            elif isinstance(n, WidgetNode):
                ctrls.extend(self._collect_input_controllers(n.children))
        return list(dict.fromkeys(ctrls))

    def _emit_body_widget(self, body_nodes: List[ASTNode], indent: int) -> str:
        pad = "  " * indent
        if not body_nodes:
            return "const SizedBox.shrink()"
        if len(body_nodes) == 1:
            return self._emit_widget(body_nodes[0], indent=indent)
        else:
            children_str = ",\n".join([f"{pad}  {self._emit_widget(c, indent + 1)}" for c in body_nodes])
            return f"Column(\n{pad}  children: [\n{children_str}\n{pad}  ],\n{pad})"

    def _emit_widget(self, node: ASTNode, indent: int = 0) -> str:
        pad = "  " * indent

        # ── Text Widget ──
        if isinstance(node, TextWidgetNode):
            style_parts = []
            if "size" in node.props:
                style_parts.append(f"fontSize: {node.props['size']}")
            if "bold" in node.props:
                style_parts.append("fontWeight: FontWeight.bold")
            if "italic" in node.props:
                style_parts.append("fontStyle: FontStyle.italic")
            if "color" in node.props:
                style_parts.append(f"color: {_hex_to_dart_color(node.props['color'])}")

            style_clause = f", style: TextStyle({', '.join(style_parts)})" if style_parts else ""
            align_clause = ""
            if "align" in node.props:
                a = node.props["align"].lower()
                align_map = {"center": "TextAlign.center", "left": "TextAlign.left", "right": "TextAlign.right"}
                if a in align_map:
                    align_clause = f", textAlign: {align_map[a]}"

            # Handle variable expression vs literal string
            text_val = node.text_expr
            if not (text_val.startswith('"') or text_val.startswith("'")):
                text_val = f"{text_val}.toString()"

            return f"Text({text_val}{align_clause}{style_clause})"

        # ── Icon Widget ──
        elif isinstance(node, IconWidgetNode):
            icon_id = node.icon_name.lower().replace("-", "_")
            parts = [f"Icons.{icon_id}"]
            if "size" in node.props:
                parts.append(f"size: {node.props['size']}")
            if "color" in node.props:
                parts.append(f"color: {_hex_to_dart_color(node.props['color'])}")
            return f"Icon({', '.join(parts)})"

        # ── Image Widget ──
        elif isinstance(node, ImageWidgetNode):
            path_str = f"'{node.path_or_url}'"
            parts = [path_str]
            if node.width:
                parts.append(f"width: {node.width}")
            if node.height:
                parts.append(f"height: {node.height}")
            if node.source_type == "asset":
                return f"Image.asset({', '.join(parts)})"
            else:
                return f"Image.network({', '.join(parts)})"

        # ── Avatar Widget ──
        elif isinstance(node, AvatarWidgetNode):
            parts = []
            if node.size:
                radius = float(node.size) / 2
                parts.append(f"radius: {radius}")
            if node.source_type == "network":
                parts.append(f"backgroundImage: NetworkImage('{node.value}')")
            elif node.source_type == "asset":
                parts.append(f"backgroundImage: AssetImage('{node.value}')")
            elif node.source_type == "initials":
                parts.append(f"child: Text('{node.value}')")
            return f"CircleAvatar({', '.join(parts)})"

        # ── Button Widget ──
        elif isinstance(node, ButtonWidgetNode):
            action_code = self._emit_action_block(node.on_tap_body, indent + 1)
            label = node.label_expr or "'Button'"
            if node.btn_type == "text":
                return f"TextButton(onPressed: () {{\n{action_code}\n{pad}}}, child: Text({label}))"
            elif node.btn_type == "icon":
                icon_id = (node.icon_name or "star").lower().replace("-", "_")
                return f"IconButton(onPressed: () {{\n{action_code}\n{pad}}}, icon: const Icon(Icons.{icon_id}))"
            else:
                return f"ElevatedButton(onPressed: () {{\n{action_code}\n{pad}}}, child: Text({label}))"

        # ── Input Widget ──
        elif isinstance(node, InputWidgetNode):
            hint_str = f"hintText: '{node.placeholder}'"
            lines_str = f", maxLines: {node.lines}" if node.lines > 1 else ""
            obscure_str = ", obscureText: true" if node.is_hidden else ""
            return f"TextField(controller: _{node.id_name}Controller, decoration: const InputDecoration({hint_str}){lines_str}{obscure_str})"

        # ── Spacer & Divider ──
        elif isinstance(node, SpacerWidgetNode):
            if node.is_expandable:
                return "const Spacer()"
            elif node.height:
                return f"const SizedBox(height: {node.height})"
            elif node.width:
                return f"const SizedBox(width: {node.width})"
            return "const SizedBox.shrink()"

        elif isinstance(node, DividerWidgetNode):
            color_str = f"color: {_hex_to_dart_color(node.color)}" if node.color else ""
            return f"Divider({color_str})" if color_str else "const Divider()"

        # ── Chip & Progress ──
        elif isinstance(node, ChipWidgetNode):
            return f"Chip(label: Text({node.label_expr}))"

        elif isinstance(node, ProgressWidgetNode):
            if node.is_circular:
                return "const CircularProgressIndicator()"
            return "const LinearProgressIndicator()"

        # ── Layout Containers (Column, Row, Stack, Center, Scroll, Card, Container, Padding) ──
        elif isinstance(node, WidgetNode):
            children_str = ",\n".join([f"{pad}  {self._emit_widget(c, indent + 1)}" for c in node.children])

            if node.widget_type in ("column", "column_center", "column_spaced"):
                align = ""
                if node.widget_type == "column_center" or "centered" in node.props:
                    align = "mainAxisAlignment: MainAxisAlignment.center,\n" + pad + "  "
                elif node.widget_type == "column_spaced" or "spaced" in node.props:
                    align = "mainAxisAlignment: MainAxisAlignment.spaceBetween,\n" + pad + "  "
                return f"Column(\n{pad}  {align}children: [\n{children_str}\n{pad}  ],\n{pad})"

            elif node.widget_type in ("row", "row_center", "row_spaced"):
                align = ""
                if node.widget_type == "row_center" or "centered" in node.props:
                    align = "mainAxisAlignment: MainAxisAlignment.center,\n" + pad + "  "
                elif node.widget_type == "row_spaced" or "spaced" in node.props:
                    align = "mainAxisAlignment: MainAxisAlignment.spaceBetween,\n" + pad + "  "
                return f"Row(\n{pad}  {align}children: [\n{children_str}\n{pad}  ],\n{pad})"

            elif node.widget_type == "stack":
                return f"Stack(\n{pad}  children: [\n{children_str}\n{pad}  ],\n{pad})"

            elif node.widget_type == "center":
                child = self._emit_widget(node.children[0], indent + 1) if node.children else "const SizedBox.shrink()"
                return f"Center(child: {child})"

            elif node.widget_type == "scroll":
                child = self._emit_body_widget(node.children, indent + 1)
                return f"SingleChildScrollView(child: {child})"

            elif node.widget_type == "safearea":
                child = self._emit_body_widget(node.children, indent + 1)
                return f"SafeArea(child: {child})"

            elif node.widget_type == "expanded":
                child = self._emit_body_widget(node.children, indent + 1)
                flex_str = f"flex: {node.props.get('flex', 1)}, " if 'flex' in node.props else ""
                return f"Expanded({flex_str}child: {child})"

            elif node.widget_type == "card":
                child = self._emit_body_widget(node.children, indent + 1)
                elev = f"elevation: {node.props.get('elevation', 4)}, " if 'elevation' in node.props else ""
                shape_str = ""
                if "radius" in node.props or "corner_radius" in node.props:
                    r = node.props.get("radius") or node.props.get("corner_radius")
                    shape_str = f"shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular({r})), "
                return f"Card({elev}{shape_str}child: {child})"

            elif node.widget_type == "container":
                child = self._emit_body_widget(node.children, indent + 1)
                w_str = f"width: {node.props['width']}, " if 'width' in node.props else ""
                h_str = f"height: {node.props['height']}, " if 'height' in node.props else ""

                dec_parts = []
                if "color" in node.props:
                    dec_parts.append(f"color: {_hex_to_dart_color(node.props['color'])}")
                if "radius" in node.props or "corner_radius" in node.props:
                    r = node.props.get("radius") or node.props.get("corner_radius")
                    dec_parts.append(f"borderRadius: BorderRadius.circular({r})")

                dec_str = f"decoration: BoxDecoration({', '.join(dec_parts)}), " if dec_parts else ""
                return f"Container({w_str}{h_str}{dec_str}child: {child})"

            elif node.widget_type in ("padding", "padding_all", "padding_symmetric"):
                child = self._emit_body_widget(node.children, indent + 1)
                val = node.props.get("padding", "16")
                return f"Padding(padding: const EdgeInsets.all({val}), child: {child})"

        # ── Lists & Grids ──
        elif isinstance(node, ListViewWidgetNode):
            template_code = self._emit_body_widget(node.template, indent + 2)
            return (
                f"ListView.builder(\n"
                f"{pad}  itemCount: ({node.items_expr} as List).length,\n"
                f"{pad}  itemBuilder: (context, index) {{\n"
                f"{pad}    final {node.item_var} = {node.items_expr}[index];\n"
                f"{pad}    return {template_code};\n"
                f"{pad}  }},\n"
                f"{pad})"
            )

        elif isinstance(node, GridViewWidgetNode):
            children_str = ",\n".join([f"{pad}  {self._emit_widget(c, indent + 1)}" for c in node.children])
            return (
                f"GridView.count(\n"
                f"{pad}  crossAxisCount: {node.columns},\n"
                f"{pad}  mainAxisSpacing: {node.gap}.0,\n"
                f"{pad}  crossAxisSpacing: {node.gap}.0,\n"
                f"{pad}  children: [\n{children_str}\n{pad}  ],\n"
                f"{pad})"
            )

        return "const SizedBox.shrink()"

    def _emit_action_block(self, actions: List[ASTNode], indent: int) -> str:
        pad = "  " * indent
        if not actions:
            return f"{pad}// No action"
        lines = []
        for a in actions:
            lines.append(f"{pad}{self._emit_action(a, indent)}")
        return "\n".join(lines)

    def _emit_action(self, node: ASTNode, indent: int) -> str:
        # Navigation
        if isinstance(node, NavigationNode):
            if node.action == "push":
                return f"Navigator.push(context, MaterialPageRoute(builder: (_) => const {node.target_screen}()));"
            elif node.action == "clear":
                return f"Navigator.pushAndRemoveUntil(context, MaterialPageRoute(builder: (_) => const {node.target_screen}()), (_) => false);"
            elif node.action == "replace":
                return f"Navigator.pushReplacement(context, MaterialPageRoute(builder: (_) => const {node.target_screen}()));"
            elif node.action == "pop":
                return "Navigator.pop(context);"
            elif node.action == "pop_result":
                return f"Navigator.pop(context, {node.data_expr or 'true'});"

        # State Mutation
        elif isinstance(node, StateAssignNode):
            return f"setState(() {{ {node.target} {node.op} {node.value}; }});"

        # Toast / Snackbar / Alert Feedback
        elif isinstance(node, ToastFeedbackNode):
            if node.feedback_type in ("toast", "snackbar"):
                msg_val = node.message_expr
                if not (msg_val.startswith('"') or msg_val.startswith("'")):
                    msg_val = f"{msg_val}.toString()"
                return f"ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text({msg_val})));"
            elif node.feedback_type == "alert":
                return (
                    f"showDialog(context: context, builder: (ctx) => AlertDialog(\n"
                    f"  title: Text({node.message_expr}),\n"
                    f"  actions: [\n"
                    f"    TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('OK')),\n"
                    f"  ],\n"
                    f"));"
                )

        # Network Call
        elif isinstance(node, NetworkCallNode):
            lines = [
                f"http.get(Uri.parse({node.url_expr})).then(({node.on_success_param}) {{",
            ]
            for s in node.on_success_body:
                lines.append(f"  {self._emit_action(s, indent + 1)}")
            lines.append("}).catchError((" + node.on_failure_param + ") {")
            for f in node.on_failure_body:
                lines.append(f"  {self._emit_action(f, indent + 1)}")
            lines.append("});")
            return "\n".join(lines)

        # Raw Dart
        elif isinstance(node, RawDartNode):
            return node.code

        return "// action"

    def _emit_appbar(self, app_bar: AppBarNode, indent: int) -> str:
        pad = "  " * indent
        actions_str = ""
        if app_bar.actions:
            acts = ",\n".join([f"{pad}    {self._emit_widget(a, indent + 2)}" for a in app_bar.actions])
            actions_str = f",\n{pad}  actions: [\n{acts}\n{pad}  ]"
        return f"AppBar(\n{pad}  title: Text({app_bar.title_expr}){actions_str}\n{pad})"

    def _emit_fab(self, fab: ButtonWidgetNode, indent: int) -> str:
        pad = "  " * indent
        action_code = self._emit_action_block(fab.on_tap_body, indent + 1)
        icon_id = (fab.icon_name or "add").lower().replace("-", "_")
        return (
            f"FloatingActionButton(\n"
            f"{pad}  onPressed: () {{\n{action_code}\n{pad}  }},\n"
            f"{pad}  child: const Icon(Icons.{icon_id}),\n"
            f"{pad})"
        )

    def _emit_bottom_bar(self, nav: BottomNavNode, indent: int) -> str:
        pad = "  " * indent
        items_code = []
        for it in nav.items:
            icon_id = it.icon_name.lower().replace("-", "_")
            items_code.append(f"BottomNavigationBarItem(icon: Icon(Icons.{icon_id}), label: '{it.label}')")
        items_str = f",\n{pad}    ".join(items_code)
        return (
            f"BottomNavigationBar(\n"
            f"{pad}  items: const [\n{pad}    {items_str}\n{pad}  ],\n"
            f"{pad})"
        )

    def _emit_drawer(self, drawer: DrawerNode, indent: int) -> str:
        pad = "  " * indent
        return f"Drawer(\n{pad}  child: ListView(\n{pad}    children: const [DrawerHeader(child: Text('Menu'))],\n{pad}  ),\n{pad})"

enlgm/parser.py:
"""enlgm Parser.

Parses token streams from ENLGMLexer into a Flutter / Dart AST.
Enforces the mandatory 'in mobile:' architecture root, processes English hint phrases,
and constructs strongly-typed Widget Trees, Navigation graphs, State, and Network nodes.
"""

from typing import List, Optional, Dict, Any, Tuple
from .tokens import Token, ENLGMTokenType
from .ast_nodes import (
    ASTNode, MobileRootNode, FlutterImportNode, AppDefNode, ScreenDefNode,
    WidgetNode, TextWidgetNode, IconWidgetNode, ImageWidgetNode, AvatarWidgetNode,
    ButtonWidgetNode, InputWidgetNode, SpacerWidgetNode, DividerWidgetNode,
    ChipWidgetNode, ProgressWidgetNode, ControlWidgetNode, ListViewWidgetNode,
    GridViewWidgetNode, AppBarNode, BottomNavNode, BottomNavItem, DrawerNode,
    DrawerItem, NavigationNode, StateDeclNode, StateAssignNode, ToastFeedbackNode,
    NetworkCallNode, RawDartNode, WidgetBlueprintNode, BlueprintInstanceNode,
    CallFunctionNode, MethodDefNode
)

def _tokens_to_str(tokens: List[Token]) -> str:
    """Converts a token subslice into a clean expression or string representation."""
    parts = []
    for t in tokens:
        if t.type == ENLGMTokenType.STRING:
            parts.append(f'"{t.value}"')
        else:
            parts.append(t.value)
    return " ".join(parts).strip()

def _parse_props_from_tokens(tokens: List[Token]) -> Dict[str, Any]:
    """Extracts property key-values (e.g. size 28, bold, color "#fff", align center)."""
    props = {}
    i = 0
    length = len(tokens)

    while i < length:
        t = tokens[i]
        val_lower = t.value.lower()

        # Connectors can be skipped
        if t.type == ENLGMTokenType.CONNECTOR and val_lower in ("with", "and", "having", "is", "the", "a", "an"):
            i += 1
            continue

        if t.type == ENLGMTokenType.SYMBOL and t.value in (",", ":", ";"):
            i += 1
            continue

        # Standalone flags
        if val_lower in ("bold", "italic", "underline", "hidden", "centered", "spaced", "back_button"):
            props[val_lower] = True
            i += 1
            continue

        # Key-Value pairs
        if val_lower in (
            "size", "color", "font", "align", "radius", "corner-radius", "corner_radius",
            "elevation", "padding", "width", "height", "lines", "placeholder", "type",
            "max_lines", "max-lines", "overflow", "gap", "columns", "duration", "background",
            "border", "border-color", "border_color", "shadow", "flex"
        ):
            prop_key = val_lower.replace("-", "_")
            if i + 1 < length:
                next_t = tokens[i + 1]
                # Consume connector if any (e.g. 'color is "#fff"')
                if next_t.type == ENLGMTokenType.CONNECTOR and next_t.value.lower() in ("is", "as", "to", "of"):
                    if i + 2 < length:
                        props[prop_key] = tokens[i + 2].value
                        i += 3
                        continue
                props[prop_key] = next_t.value
                i += 2
                continue

        # Generic key-value fallback
        if t.type == ENLGMTokenType.IDENTIFIER and i + 1 < length and tokens[i+1].type in (ENLGMTokenType.STRING, ENLGMTokenType.NUMBER, ENLGMTokenType.IDENTIFIER):
            props[t.value.lower()] = tokens[i+1].value
            i += 2
            continue

        i += 1

    return props

class ENLGMParser:
    """Parses .enlgm token stream into a MobileRootNode AST."""

    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0
        self.length = len(tokens)
        self.root = MobileRootNode()

    def _peek(self, offset: int = 0) -> Optional[Token]:
        idx = self.pos + offset
        return self.tokens[idx] if idx < self.length else None

    def _match(self, token_type: ENLGMTokenType, value: Optional[str] = None) -> bool:
        tok = self._peek()
        if not tok or tok.type != token_type:
            return False
        if value is not None and tok.value.lower() != value.lower():
            return False
        return True

    def _consume(self) -> Optional[Token]:
        if self.pos < self.length:
            tok = self.tokens[self.pos]
            self.pos += 1
            return tok
        return None

    def _consume_newlines(self):
        while self._match(ENLGMTokenType.NEWLINE):
            self._consume()

    def parse(self) -> MobileRootNode:
        self._consume_newlines()

        has_type_header = False
        first_tok = self._peek()
        if first_tok and first_tok.type == ENLGMTokenType.HINT and first_tok.value == "TYPE_HEADER":
            has_type_header = True
            self._consume()
            self._consume_newlines()

        first_tok = self._peek()
        if first_tok and first_tok.type == ENLGMTokenType.HINT and first_tok.value == "MOBILE_DOMAIN":
            self._consume() # Consume 'in mobile'
            if self._match(ENLGMTokenType.SYMBOL, ":"):
                self._consume()
            self._consume_newlines()

            if self._match(ENLGMTokenType.INDENT):
                self._consume()
                while not (self._match(ENLGMTokenType.DEDENT) or self._match(ENLGMTokenType.EOF)):
                    self._consume_newlines()
                    if self._match(ENLGMTokenType.DEDENT) or self._match(ENLGMTokenType.EOF):
                        break
                    stmt = self._parse_top_level_statement()
                    if stmt:
                        self._add_top_level_node(stmt)
                if self._match(ENLGMTokenType.DEDENT):
                    self._consume()
            else:
                while not self._match(ENLGMTokenType.EOF):
                    self._consume_newlines()
                    if self._match(ENLGMTokenType.EOF):
                        break
                    stmt = self._parse_top_level_statement()
                    if stmt:
                        self._add_top_level_node(stmt)
        elif has_type_header:
            while not self._match(ENLGMTokenType.EOF):
                self._consume_newlines()
                if self._match(ENLGMTokenType.EOF):
                    break
                stmt = self._parse_top_level_statement()
                if stmt:
                    self._add_top_level_node(stmt)
        else:
            raise SyntaxError("Enlang Mobile files must begin with 'type enlgm' or 'in mobile:' as the first statement.")

        return self.root

    def _add_top_level_node(self, node: ASTNode):
        if isinstance(node, FlutterImportNode):
            self.root.imports.append(node)
        elif isinstance(node, AppDefNode):
            self.root.app = node
        elif isinstance(node, ScreenDefNode):
            self.root.screens.append(node)
        elif isinstance(node, WidgetBlueprintNode):
            self.root.blueprints.append(node)
        elif isinstance(node, RawDartNode):
            self.root.raw_dart_blocks.append(node)

    def _parse_top_level_statement(self) -> Optional[ASTNode]:
        line_tokens = self._gather_line_tokens()
        if not line_tokens:
            return None

        first = line_tokens[0]

        if first.type == ENLGMTokenType.HINT:
            intent = first.value

            if intent == "FLUTTER_IMPORT":
                pkg_name = line_tokens[1].value if len(line_tokens) > 1 else "material"
                return FlutterImportNode(package_name=pkg_name, is_flutter=True)

            elif intent == "PACKAGE_IMPORT":
                pkg_name = line_tokens[1].value if len(line_tokens) > 1 else "http"
                alias = line_tokens[3].value if len(line_tokens) > 3 and line_tokens[2].value.lower() == "as" else None
                return FlutterImportNode(package_name=pkg_name, is_flutter=False, as_alias=alias)

            elif intent == "APP_DEF":
                app_name = line_tokens[1].value if len(line_tokens) > 1 else "App"
                app_node = AppDefNode(name=app_name)
                # Parse app block
                if self._has_child_block():
                    body_stmts = self._parse_block()
                    for s in body_stmts:
                        if isinstance(s, dict):
                            if "theme" in s:
                                app_node.theme = s["theme"]
                            if "color" in s or "accent_color" in s:
                                app_node.primary_color = s.get("color") or s.get("accent_color")
                            if "home" in s or "home_screen" in s:
                                app_node.home_screen = s.get("home") or s.get("home_screen")
                return app_node

            elif intent in ("SCREEN_DEF", "STATEFUL_SCREEN_DEF"):
                is_stateful = (intent == "STATEFUL_SCREEN_DEF")
                screen_name = line_tokens[1].value if len(line_tokens) > 1 else "Screen"
                screen = ScreenDefNode(name=screen_name, is_stateful=is_stateful)

                if self._has_child_block():
                    body_nodes = self._parse_block()
                    for node in body_nodes:
                        if isinstance(node, StateDeclNode):
                            screen.state_vars.append(node)
                            screen.is_stateful = True
                        elif isinstance(node, AppBarNode):
                            screen.app_bar = node
                        elif isinstance(node, BottomNavNode):
                            screen.bottom_bar = node
                        elif isinstance(node, DrawerNode):
                            screen.drawer = node
                        elif isinstance(node, ButtonWidgetNode) and node.btn_type == "fab":
                            screen.fab = node
                        elif isinstance(node, MethodDefNode):
                            screen.methods.append(node)
                        elif isinstance(node, dict) and "title" in node:
                            screen.title = node["title"]
                        elif isinstance(node, dict) and "body" in node:
                            screen.body.extend(node["body"])
                        else:
                            screen.body.append(node)

                return screen

            elif intent == "WIDGET_BLUEPRINT":
                bp_name = line_tokens[1].value if len(line_tokens) > 1 else "CustomWidget"
                params = []
                # Extract 'needs p1, p2, p3' if present on the line
                for t in line_tokens[2:]:
                    if t.type == ENLGMTokenType.IDENTIFIER and t.value.lower() not in ("needs", "with", "and", "params", ","):
                        params.append(t.value)
                bp_body = []
                if self._has_child_block():
                    raw_body = self._parse_block()
                    for item in raw_body:
                        if isinstance(item, dict) and "needs" in item:
                            params.extend(item["needs"])
                        else:
                            bp_body.append(item)
                return WidgetBlueprintNode(name=bp_name, params=params, body=bp_body)

            elif intent == "RAW_DART":
                code_lines = self._gather_raw_block_text()
                return RawDartNode(code="\n".join(code_lines))

        return None

    def _has_child_block(self) -> bool:
        self._consume_newlines()
        return self._match(ENLGMTokenType.INDENT)

    def _gather_raw_block_text(self) -> List[str]:
        lines = []
        if self._match(ENLGMTokenType.INDENT):
            self._consume()
            while not (self._match(ENLGMTokenType.DEDENT) or self._match(ENLGMTokenType.EOF)):
                tok = self._consume()
                if tok:
                    if tok.type == ENLGMTokenType.NEWLINE:
                        lines.append(tok.raw_text)
                    elif not lines:
                        lines.append(tok.raw_text)
            if self._match(ENLGMTokenType.DEDENT):
                self._consume()
        return lines

    def _parse_block(self) -> List[Any]:
        nodes = []
        if not self._match(ENLGMTokenType.INDENT):
            return nodes
        self._consume() # Consume INDENT

        while not (self._match(ENLGMTokenType.DEDENT) or self._match(ENLGMTokenType.EOF)):
            self._consume_newlines()
            if self._match(ENLGMTokenType.DEDENT) or self._match(ENLGMTokenType.EOF):
                break
            stmt = self._parse_statement()
            if stmt:
                nodes.append(stmt)
            self._consume_newlines()

        if self._match(ENLGMTokenType.DEDENT):
            self._consume()

        return nodes

    def _gather_line_tokens(self) -> List[Token]:
        tokens = []
        while not (self._match(ENLGMTokenType.NEWLINE) or self._match(ENLGMTokenType.EOF) or self._match(ENLGMTokenType.INDENT) or self._match(ENLGMTokenType.DEDENT)):
            tokens.append(self._consume())
        if self._match(ENLGMTokenType.NEWLINE):
            self._consume()
        return tokens

    def _parse_statement(self) -> Optional[Any]:
        line_tokens = self._gather_line_tokens()
        if not line_tokens:
            return None

        first = line_tokens[0]

        # Check for simple screen property blocks (e.g. 'title "Home"', 'body:', 'state:')
        if first.type == ENLGMTokenType.IDENTIFIER:
            val_lower = first.value.lower()
            if val_lower == "title" and len(line_tokens) > 1:
                return {"title": line_tokens[1].value}
            elif val_lower == "theme" and len(line_tokens) > 1:
                return {"theme": line_tokens[1].value}
            elif val_lower in ("color", "accent_color", "accent") and len(line_tokens) > 1:
                color_val = line_tokens[1].value if line_tokens[1].value != "color" else (line_tokens[2].value if len(line_tokens) > 2 else "#00f2fe")
                return {"color": color_val}
            elif val_lower in ("home", "home_screen") and len(line_tokens) > 1:
                target = [t.value for t in line_tokens[1:] if t.value.lower() not in ("screen", "to", "at", "is", "as") and t.type in (ENLGMTokenType.IDENTIFIER, ENLGMTokenType.STRING, ENLGMTokenType.HINT)]
                # If a hint was matched like 'HomeScreen' where 'Home' wasn't recognized as hint but followed by screen
                candidate = target[-1] if target else "HomeScreen"
                return {"home": candidate}
            elif val_lower == "needs":
                param_names = [t.value for t in line_tokens[1:] if t.type == ENLGMTokenType.IDENTIFIER and t.value.lower() not in ("with", "and", "params", ",")]
                return {"needs": param_names}
            elif val_lower == "body":
                body_children = self._parse_block() if self._has_child_block() else []
                return {"body": body_children}
            elif val_lower == "actions":
                actions_list = self._parse_block() if self._has_child_block() else []
                return {"actions": actions_list}
            elif val_lower == "header":
                header_list = self._parse_block() if self._has_child_block() else []
                return {"header": header_list}

        if first.type == ENLGMTokenType.HINT:
            intent = first.value
            return self._build_node_from_intent(intent, line_tokens[1:], line_tokens)

        # Check for method definition or function call
        if first.type == ENLGMTokenType.IDENTIFIER and len(line_tokens) > 1 and line_tokens[1].value == "(":
            # Function call
            fn_name = first.value
            args = [t.value for t in line_tokens[2:] if t.value not in (")", ",")]
            return CallFunctionNode(fn_name=fn_name, args=args)

        return None

    def _build_node_from_intent(self, intent: str, args: List[Token], full_line: List[Token]) -> Any:
        props = _parse_props_from_tokens(args)

        # ── State Declarations & Assignments ──
        if intent == "STATE_DECLARE":
            # create x as 0  or  create name as "Prayas"
            var_name = args[0].value if args else "val"
            val_tokens = [t for t in args[1:] if t.value.lower() not in ("as", "is", "=")]
            val_expr = _tokens_to_str(val_tokens) if val_tokens else "0"
            return StateDeclNode(name=var_name, initial_val=val_expr)

        elif intent == "STATE_BLOCK":
            # state: block containing declarations
            state_nodes = self._parse_block() if self._has_child_block() else []
            return state_nodes

        elif intent == "STATE_SET":
            # set count to 10
            clean = [t for t in args if t.value.lower() not in ("to", "=")]
            target = clean[0].value if clean else "x"
            val_expr = _tokens_to_str(clean[1:]) if len(clean) > 1 else "0"
            return StateAssignNode(target=target, op="=", value=val_expr)

        elif intent in ("STATE_INC", "STATE_ADD"):
            # increase count by 1  or  add 1 to count
            clean = [t for t in args if t.value.lower() not in ("by", "to")]
            if len(clean) >= 2:
                # Disambiguate 'increase x by 1' vs 'add 1 to x'
                if clean[0].value.isdigit():
                    val = clean[0].value
                    target = clean[1].value
                else:
                    target = clean[0].value
                    val = clean[1].value
            else:
                target = clean[0].value if clean else "x"
                val = "1"
            return StateAssignNode(target=target, op="+=", value=val)

        elif intent in ("STATE_DEC", "STATE_SUB"):
            clean = [t for t in args if t.value.lower() not in ("by", "from")]
            if len(clean) >= 2:
                if clean[0].value.isdigit():
                    val = clean[0].value
                    target = clean[1].value
                else:
                    target = clean[0].value
                    val = clean[1].value
            else:
                target = clean[0].value if clean else "x"
                val = "1"
            return StateAssignNode(target=target, op="-=", value=val)

        # ── Navigation Actions (Flutter Navigator) ──
        elif intent in ("NAV_PUSH", "NAV_CLEAR", "NAV_REPLACE", "NAV_POP", "NAV_POP_RESULT"):
            is_clear = (intent == "NAV_CLEAR") or any(t.value.lower() in ("clear", "clear_all") for t in args)
            clean = [t for t in args if t.value.lower() not in ("to", "screen", "with", "carrying", "data", "result", "and", "all", "clear")]
            action_map = {
                "NAV_PUSH": "clear" if is_clear else "push",
                "NAV_CLEAR": "clear",
                "NAV_REPLACE": "replace",
                "NAV_POP": "pop",
                "NAV_POP_RESULT": "pop_result"
            }
            action = action_map[intent]
            target_screen = clean[0].value if clean else ""
            data_expr = _tokens_to_str(clean[1:]) if len(clean) > 1 else None
            return NavigationNode(action=action, target_screen=target_screen, data_expr=data_expr)

        # ── Feedback / Alerts ──
        elif intent in ("SHOW_TOAST", "SHOW_SNACKBAR"):
            msg_tokens = [t for t in args if t.type == ENLGMTokenType.STRING or t.type == ENLGMTokenType.IDENTIFIER]
            msg_expr = _tokens_to_str(msg_tokens) if msg_tokens else '""'
            fb_type = "toast" if intent == "SHOW_TOAST" else "snackbar"
            return ToastFeedbackNode(feedback_type=fb_type, message_expr=msg_expr)

        elif intent == "SHOW_ALERT":
            msg_tokens = [t for t in args if t.type == ENLGMTokenType.STRING]
            title_expr = msg_tokens[0].value if msg_tokens else "Alert"
            alert_node = ToastFeedbackNode(feedback_type="alert", message_expr=f'"{title_expr}"')
            if self._has_child_block():
                alert_body = self._parse_block()
                for item in alert_body:
                    if isinstance(item, dict):
                        if "message" in item:
                            alert_node.message_expr = item["message"]
                        if "confirm" in item:
                            alert_node.confirm_label = item["confirm"]
                            alert_node.confirm_body = item.get("body", [])
                        if "cancel" in item:
                            alert_node.cancel_label = item["cancel"]
            return alert_node

        # ── Layout Widgets ──
        elif intent in (
            "WIDGET_COLUMN", "WIDGET_COLUMN_CENTER", "WIDGET_COLUMN_SPACED",
            "WIDGET_ROW", "WIDGET_ROW_CENTER", "WIDGET_ROW_SPACED",
            "WIDGET_STACK", "WIDGET_CENTER", "WIDGET_SCROLL", "WIDGET_SAFEAREA",
            "WIDGET_EXPANDED", "WIDGET_EXPANDED_FLEX", "WIDGET_FLEXIBLE", "WIDGET_FLEXIBLE_FLEX",
            "WIDGET_CONTAINER", "WIDGET_CARD", "WIDGET_PADDING", "WIDGET_PADDING_ALL", "WIDGET_PADDING_SYMMETRIC"
        ):
            w_type_map = {
                "WIDGET_COLUMN": "column",
                "WIDGET_COLUMN_CENTER": "column_center",
                "WIDGET_COLUMN_SPACED": "column_spaced",
                "WIDGET_ROW": "row",
                "WIDGET_ROW_CENTER": "row_center",
                "WIDGET_ROW_SPACED": "row_spaced",
                "WIDGET_STACK": "stack",
                "WIDGET_CENTER": "center",
                "WIDGET_SCROLL": "scroll",
                "WIDGET_SAFEAREA": "safearea",
                "WIDGET_EXPANDED": "expanded",
                "WIDGET_EXPANDED_FLEX": "expanded",
                "WIDGET_FLEXIBLE": "flexible",
                "WIDGET_FLEXIBLE_FLEX": "flexible",
                "WIDGET_CONTAINER": "container",
                "WIDGET_CARD": "card",
                "WIDGET_PADDING": "padding",
                "WIDGET_PADDING_ALL": "padding_all",
                "WIDGET_PADDING_SYMMETRIC": "padding_symmetric"
            }
            w_type = w_type_map[intent]
            children = []
            on_tap_body = []

            if self._has_child_block():
                child_nodes = self._parse_block()
                for c in child_nodes:
                    if isinstance(c, tuple) and c[0] == "ON_TAP":
                        on_tap_body.extend(c[1])
                    else:
                        children.append(c)

            return WidgetNode(widget_type=w_type, props=props, children=children, on_tap_body=on_tap_body)

        # ── Text Widget ──
        elif intent == "WIDGET_TEXT":
            text_tokens = []
            prop_start = -1
            for idx, t in enumerate(args):
                if t.value.lower() in ("size", "color", "bold", "italic", "align", "font", "max_lines", "overflow"):
                    prop_start = idx
                    break
                text_tokens.append(t)

            text_expr = _tokens_to_str(text_tokens) if text_tokens else '""'

            # If multi-line property block exists
            if self._has_child_block():
                block_props = self._parse_block()
                for bp in block_props:
                    if isinstance(bp, dict):
                        props.update(bp)

            return TextWidgetNode(text_expr=text_expr, props=props)

        # ── Buttons ──
        elif intent in ("WIDGET_BUTTON", "WIDGET_TEXT_BUTTON", "WIDGET_ICON_BUTTON", "WIDGET_FAB"):
            btn_type = "elevated"
            if intent == "WIDGET_TEXT_BUTTON":
                btn_type = "text"
            elif intent == "WIDGET_ICON_BUTTON":
                btn_type = "icon"
            elif intent == "WIDGET_FAB":
                btn_type = "fab"

            label_expr = None
            icon_name = None
            if args:
                if btn_type in ("icon", "fab"):
                    icon_name = args[0].value.strip('"\'')
                elif args[0].type == ENLGMTokenType.STRING:
                    label_expr = f'"{args[0].value}"'
                else:
                    label_expr = args[0].value

            on_tap_body = []
            if self._has_child_block():
                child_nodes = self._parse_block()
                for c in child_nodes:
                    if isinstance(c, tuple) and c[0] == "ON_TAP":
                        on_tap_body.extend(c[1])
                    elif isinstance(c, NavigationNode) or isinstance(c, ToastFeedbackNode) or isinstance(c, StateAssignNode):
                        on_tap_body.append(c)

            return ButtonWidgetNode(btn_type=btn_type, label_expr=label_expr, icon_name=icon_name, props=props, on_tap_body=on_tap_body)

        # ── Input / TextField ──
        elif intent == "WIDGET_TEXTFIELD":
            id_name = args[0].value.strip('"\'') if args else "inputField"
            placeholder = props.get("placeholder", "")
            input_type = props.get("type", "text")
            is_hidden = "hidden" in props or input_type == "password"
            lines = int(props.get("lines", 1))

            on_submit_body = []
            if self._has_child_block():
                child_nodes = self._parse_block()
                for c in child_nodes:
                    if isinstance(c, tuple) and c[0] == "ON_SUBMIT":
                        on_submit_body.extend(c[1])

            return InputWidgetNode(
                id_name=id_name,
                placeholder=placeholder,
                input_type=input_type,
                is_hidden=is_hidden,
                lines=lines,
                props=props,
                on_submit_body=on_submit_body
            )

        # ── Image & Avatar ──
        elif intent in ("WIDGET_IMAGE_NETWORK", "WIDGET_IMAGE_ASSET"):
            src_type = "asset" if "ASSET" in intent else "network"
            path_or_url = args[0].value.strip('"\'') if args else ""
            return ImageWidgetNode(source_type=src_type, path_or_url=path_or_url, props=props)

        elif intent in ("WIDGET_AVATAR_NETWORK", "WIDGET_AVATAR_ASSET", "WIDGET_AVATAR_INITIALS"):
            src_type = "network"
            if "ASSET" in intent:
                src_type = "asset"
            elif "INITIALS" in intent:
                src_type = "initials"
            val = args[0].value.strip('"\'') if args else ""
            size = props.get("size")
            return AvatarWidgetNode(source_type=src_type, value=val, size=size, props=props)

        # ── Icon ──
        elif intent == "WIDGET_ICON":
            icon_name = args[0].value.strip('"\'') if args else "star"
            return IconWidgetNode(icon_name=icon_name, props=props)

        # ── Spacer & Divider ──
        elif intent in ("WIDGET_SPACER", "WIDGET_SIZED_BOX_H", "WIDGET_SIZED_BOX_W"):
            if intent == "WIDGET_SIZED_BOX_H":
                h = args[0].value if args else "16"
                return SpacerWidgetNode(is_expandable=False, height=h)
            elif intent == "WIDGET_SIZED_BOX_W":
                w = args[0].value if args else "16"
                return SpacerWidgetNode(is_expandable=False, width=w)
            else:
                # If number follows 'spacer 20' -> height 20
                if args and args[0].type == ENLGMTokenType.NUMBER:
                    return SpacerWidgetNode(is_expandable=False, height=args[0].value)
                return SpacerWidgetNode(is_expandable=True)

        elif intent == "WIDGET_DIVIDER":
            return DividerWidgetNode(color=props.get("color"))

        # ── Chip & Progress ──
        elif intent == "WIDGET_CHIP":
            label_val = args[0].value if args else "Tag"
            return ChipWidgetNode(label_expr=f'"{label_val}"', props=props)

        elif intent in ("WIDGET_PROGRESS_LINEAR", "WIDGET_PROGRESS_CIRCULAR"):
            is_circ = ("CIRCULAR" in intent)
            return ProgressWidgetNode(is_circular=is_circ, color=props.get("color"))

        # ── Lists & Grids ──
        elif intent == "WIDGET_LIST":
            items_expr = args[0].value if args else "items"
            template = self._parse_block() if self._has_child_block() else []
            return ListViewWidgetNode(items_expr=items_expr, template=template)

        elif intent == "WIDGET_GRID":
            cols = int(props.get("columns", 2))
            gap = int(props.get("gap", 12))
            children = self._parse_block() if self._has_child_block() else []
            return GridViewWidgetNode(columns=cols, gap=gap, children=children)

        # ── App Bar ──
        elif intent == "WIDGET_APPBAR":
            title_expr = props.get("title", '""')
            actions = []
            if self._has_child_block():
                body_items = self._parse_block()
                for bi in body_items:
                    if isinstance(bi, dict) and "title" in bi:
                        title_expr = f'"{bi["title"]}"'
                    elif isinstance(bi, dict) and "actions" in bi:
                        actions.extend(bi["actions"])
                    else:
                        actions.append(bi)
            return AppBarNode(title_expr=title_expr, actions=actions)

        # ── Bottom Navigation ──
        elif intent == "WIDGET_BOTTOM_NAV":
            nav_items = []
            if self._has_child_block():
                raw_items = self._parse_block()
                for ri in raw_items:
                    if isinstance(ri, BottomNavItem):
                        nav_items.append(ri)
            return BottomNavNode(items=nav_items)

        # ── Drawer ──
        elif intent == "WIDGET_DRAWER":
            header_children = []
            drawer_items = []
            if self._has_child_block():
                raw_items = self._parse_block()
                for ri in raw_items:
                    if isinstance(ri, dict) and "header" in ri:
                        header_children.extend(ri["header"])
                    elif isinstance(ri, DrawerItem):
                        drawer_items.append(ri)
            return DrawerNode(header_children=header_children, items=drawer_items)

        # ── Events (when tapped, when submitted, on change) ──
        elif intent == "EVENT_TAP":
            tap_body = self._parse_block() if self._has_child_block() else []
            return ("ON_TAP", tap_body)

        elif intent == "EVENT_SUBMITTED":
            submit_body = self._parse_block() if self._has_child_block() else []
            return ("ON_SUBMIT", submit_body)

        elif intent == "EVENT_CHANGED":
            change_body = self._parse_block() if self._has_child_block() else []
            return ("ON_CHANGE", change_body)

        # ── Network Calls ──
        elif intent in ("FETCH_GET", "FETCH_POST"):
            method = "POST" if "POST" in intent else "GET"
            clean_tokens = [t for t in args if t.value.lower() not in ("from", "to", "with", "body")]
            url_expr = clean_tokens[0].value if clean_tokens else '""'
            body_expr = clean_tokens[1].value if len(clean_tokens) > 1 else None

            net_node = NetworkCallNode(method=method, url_expr=f'"{url_expr}"', body_expr=body_expr)
            if self._has_child_block():
                callbacks = self._parse_block()
                for cb in callbacks:
                    if isinstance(cb, tuple):
                        if cb[0] == "NET_SUCCESS":
                            net_node.on_success_param = cb[1]
                            net_node.on_success_body = cb[2]
                        elif cb[0] == "NET_FAILURE":
                            net_node.on_failure_param = cb[1]
                            net_node.on_failure_body = cb[2]
            return net_node

        elif intent == "NET_SUCCESS":
            clean_p = [t.value for t in args if t.value.lower() not in ("with", "and", "as", ":", ",")]
            param = clean_p[0] if clean_p else "result"
            body = self._parse_block() if self._has_child_block() else []
            return ("NET_SUCCESS", param, body)

        elif intent == "NET_FAILURE":
            clean_p = [t.value for t in args if t.value.lower() not in ("with", "and", "as", ":", ",")]
            param = clean_p[0] if clean_p else "error"
            body = self._parse_block() if self._has_child_block() else []
            return ("NET_FAILURE", param, body)

        # ── Raw Dart Escape ──
        elif intent == "RAW_DART":
            code_lines = self._gather_raw_block_text()
            return RawDartNode(code="\n".join(code_lines))

        return None

enlgs/ast_nodes.py:
"""enlgs Abstract Syntax Tree (AST) Nodes.

Defines the strongly-typed nodes representing all JavaScript behavior constructs.
"""

from dataclasses import dataclass, field
from typing import List, Optional, Tuple, Dict, Any

class ASTNode:
    """Base class for all .enlgs AST nodes."""
    pass

@dataclass
class RawJSNode(ASTNode):
    """Represents a raw JavaScript passthrough line or block."""
    code: str

@dataclass
class VarDeclNode(ASTNode):
    """Represents a variable declaration (let / const)."""
    kind: str  # "let" or "const"
    name: str
    value: Optional[str] = None

@dataclass
class VarAssignNode(ASTNode):
    """Represents a variable assignment or compound mutation (x = 5, x += 1)."""
    name: str
    op: str  # "=", "+=", "-=", "*=", "/="
    value: str

@dataclass
class OutputNode(ASTNode):
    """Represents console/browser output (log, warn, error, alert)."""
    method: str  # "log", "warn", "error", "alert"
    args: List[str] = field(default_factory=list)

@dataclass
class FunctionDefNode(ASTNode):
    """Represents a JavaScript function definition."""
    name: str
    params: List[str] = field(default_factory=list)
    body: List[ASTNode] = field(default_factory=list)
    is_async: bool = False

@dataclass
class FunctionCallNode(ASTNode):
    """Represents a function call statement."""
    name: str
    args: List[str] = field(default_factory=list)

@dataclass
class ReturnNode(ASTNode):
    """Represents a return statement."""
    value: Optional[str] = None

@dataclass
class IfNode(ASTNode):
    """Represents an if/else if/else conditional structure."""
    condition: str
    body: List[ASTNode] = field(default_factory=list)
    elif_branches: List[Tuple[str, List[ASTNode]]] = field(default_factory=list)
    else_body: Optional[List[ASTNode]] = None

@dataclass
class LoopRepeatNode(ASTNode):
    """Represents a numeric loop: repeat N times: ..."""
    count: str
    body: List[ASTNode] = field(default_factory=list)

@dataclass
class LoopForNode(ASTNode):
    """Represents an iterable for loop: for each item in list: ..."""
    item_name: str
    iterable: str
    body: List[ASTNode] = field(default_factory=list)

@dataclass
class LoopWhileNode(ASTNode):
    """Represents a while loop: while condition: ..."""
    condition: str
    body: List[ASTNode] = field(default_factory=list)

@dataclass
class DOMSetNode(ASTNode):
    """Represents DOM property assignment (text, html, value, style)."""
    target: str
    prop_type: str  # "text", "html", "value", "color", "background", "width", "height", "style"
    value: str
    style_prop: Optional[str] = None

@dataclass
class DOMRefreshNode(ASTNode):
    """Represents refresh 'id' with value (textContent update)."""
    target: str
    value: str

@dataclass
class DOMClassNode(ASTNode):
    """Represents classList manipulation (add, remove, toggle)."""
    action: str  # "add", "remove", "toggle"
    class_name: str
    target: str

@dataclass
class DOMVisibilityNode(ASTNode):
    """Represents showing/hiding a DOM element."""
    action: str  # "show" (display = block/default) or "hide" (display = none)
    target: str

@dataclass
class EventNode(ASTNode):
    """Represents an event listener binding (when 'btn' clicked: ...)."""
    target: str
    event_type: str  # "click", "submit", "change", "load", "keydown", "mouseenter", "mouseleave", "message"
    key_filter: Optional[str] = None
    is_variable: bool = False
    body: List[ASTNode] = field(default_factory=list)

@dataclass
class FetchNode(ASTNode):
    """Represents an async network fetch or send operation."""
    method: str  # "GET" or "POST"
    url: str
    body_expr: Optional[str] = None
    response_var: str = "data"
    body: List[ASTNode] = field(default_factory=list)

@dataclass
class TimerNode(ASTNode):
    """Represents a setTimeout (after) or setInterval (every) timer."""
    timer_type: str  # "after" (setTimeout) or "every" (setInterval)
    duration_ms: str
    body: List[ASTNode] = field(default_factory=list)

@dataclass
class BrowserActionNode(ASTNode):
    """Represents browser navigation, clipboard, scrolling, or reload."""
    action: str  # "redirect", "reload", "back", "forward", "scroll", "copy", "open"
    arg: Optional[str] = None

@dataclass
class StorageNode(ASTNode):
    """Represents localStorage operations."""
    action: str  # "set", "get", "remove", "clear"
    key: Optional[str] = None
    value: Optional[str] = None

@dataclass
class TryCatchNode(ASTNode):
    """Represents a try/catch error handling block."""
    try_body: List[ASTNode] = field(default_factory=list)
    error_var: str = "error"
    catch_body: List[ASTNode] = field(default_factory=list)

@dataclass
class ClassDefNode(ASTNode):
    """Represents a JavaScript ES6 class definition."""
    name: str
    parent: Optional[str] = None
    body: List[ASTNode] = field(default_factory=list)

@dataclass
class ClassInitNode(ASTNode):
    """Represents a class constructor (to initialize with params: ...)."""
    params: List[str] = field(default_factory=list)
    body: List[ASTNode] = field(default_factory=list)

@dataclass
class ClassSuperNode(ASTNode):
    """Represents super() call in constructor."""
    args: List[str] = field(default_factory=list)

@dataclass
class ShapeDefNode(ASTNode):
    """Represents TypeScript-style interface/shape contract in Enlgs."""
    name: str
    fields: List[Tuple[str, str]] = field(default_factory=list)  # (field_name, field_type)

@dataclass
class ComponentDefNode(ASTNode):
    """Represents a declarative UI Component (React/Vue style in Enlgs)."""
    name: str
    props: List[str] = field(default_factory=list)
    body: List[ASTNode] = field(default_factory=list)

@dataclass
class DOMMakeElementNode(ASTNode):
    """Represents declarative element creation: make element 'div' with class 'card': ..."""
    tag: str
    attrs: Dict[str, str] = field(default_factory=dict)
    target_var: Optional[str] = None
    body: List[ASTNode] = field(default_factory=list)

@dataclass
class DOMAddElementNode(ASTNode):
    """Represents adding a child element inside a make element block."""
    tag: str
    attrs: Dict[str, str] = field(default_factory=dict)
    text: Optional[str] = None

@dataclass
class DOMAppendToNode(ASTNode):
    """Represents appending or prepending an element to a container."""
    child: str
    parent: str
    is_prepend: bool = False

@dataclass
class AnimateTargetNode(ASTNode):
    """Represents Web Animation API / CSS transition animation: animate 'box' over 500 ms with {...}."""
    target: str
    duration_ms: str
    properties: str

@dataclass
class FunctionalPipelineNode(ASTNode):
    """Represents functional array transformation (filter, map, reduce, find, sort)."""
    op: str  # "filter", "map", "reduce", "find", "sort"
    source_expr: str
    target_var: Optional[str] = None
    item_name: str = "item"
    acc_name: Optional[str] = None
    body_expr: str = ""
    initial_expr: Optional[str] = None

@dataclass
class HttpServerNode(ASTNode):
    """Represents a Node.js / Express-style HTTP server in Enlgs."""
    port: str
    routes: List[ASTNode] = field(default_factory=list)

@dataclass
class HttpRouteNode(ASTNode):
    """Represents an HTTP endpoint route (route get '/api': ...)."""
    method: str  # "GET", "POST", "PUT", "DELETE", "ANY"
    path: str
    body: List[ASTNode] = field(default_factory=list)

@dataclass
class HttpReturnJsonNode(ASTNode):
    """Represents returning JSON from an HTTP route."""
    data_expr: str

@dataclass
class StoreStateNode(ASTNode):
    """Represents a state property definition inside a store."""
    name: str
    value_expr: str

@dataclass
class StoreDefNode(ASTNode):
    """Represents a centralized reactive state store (Redux/Zustand style)."""
    name: str
    states: List[Tuple[str, str]] = field(default_factory=list)  # (state_name, initial_value)
    actions: List[FunctionDefNode] = field(default_factory=list)

@dataclass
class World3DNode(ASTNode):
    """Represents a Three.js / WebGL 3D canvas world declaration."""
    canvas_target: str
    body: List[ASTNode] = field(default_factory=list)

@dataclass
class AnimationFrameLoopNode(ASTNode):
    """Represents a 60FPS requestAnimationFrame loop block."""
    body: List[ASTNode] = field(default_factory=list)

@dataclass
class RenderSceneNode(ASTNode):
    """Represents rendering a 3D scene: render scene with camera."""
    scene: str = "scene"
    camera: str = "camera"

@dataclass
class MoveTargetNode(ASTNode):
    """Represents setting 3D object position: move obj to (x, y, z)."""
    target: str
    coordinates: List[str] = field(default_factory=list)

@dataclass
class RotateByNode(ASTNode):
    """Represents 3D object rotation: rotate obj by x 0.01, y 0.02."""
    target: str
    rotations: Dict[str, str] = field(default_factory=dict)

@dataclass
class TranslateByNode(ASTNode):
    """Represents 3D object translation: translate obj by x 1, y 2, z 3."""
    target: str
    translations: Dict[str, str] = field(default_factory=dict)

@dataclass
class ExtractDestructureNode(ASTNode):
    """Represents destructuring assignment: extract name, age from user."""
    variables: List[str] = field(default_factory=list)
    source_expr: str = ""

@dataclass
class WebSocketConnectNode(ASTNode):
    """Represents WebSocket connection."""
    url: str
    socket_var: str = "socket"

@dataclass
class WebSocketReceiveNode(ASTNode):
    """Represents WebSocket onmessage event."""
    socket_var: str = "socket"
    data_var: str = "data"
    body: List[ASTNode] = field(default_factory=list)

@dataclass
class GeneratorDefNode(ASTNode):
    """Represents a JavaScript generator function (function*)."""
    name: str
    params: List[str] = field(default_factory=list)
    body: List[ASTNode] = field(default_factory=list)

@dataclass
class GeneratorYieldNode(ASTNode):
    """Represents yield value in a generator."""
    value: Optional[str] = None

@dataclass
class PreventDefaultNode(ASTNode):
    """Represents event.preventDefault()."""
    pass

@dataclass
class ListAddNode(ASTNode):
    """Represents adding/pushing an item to an array: add X to list / push X to list."""
    item: str
    target: str

@dataclass
class ListRemoveAtNode(ASTNode):
    """Represents removing an item at an index from an array: remove item at idx from list."""
    index: str
    target: str

@dataclass
class ListInsertNode(ASTNode):
    """Represents inserting an item at an index into an array: insert X at idx in list."""
    item: str
    index: str
    target: str

@dataclass
class ScriptNode(ASTNode):
    """Root AST Node representing the compiled script."""
    body: List[ASTNode] = field(default_factory=list)

enlgs/emitter.py:
"""enlgs JavaScript Emitter.

Compiles an ENLGS AST (ScriptNode) into standard, clean, modern JavaScript.
Handles OOP classes, async/await, generators, DOM tree construction, component rendering,
functional array pipelines, WebSockets, Three.js 3D helpers, and full Node.js HTTP servers.
"""

from typing import List
from .ast_nodes import (
    ASTNode, ScriptNode, RawJSNode, VarDeclNode, VarAssignNode, OutputNode,
    FunctionDefNode, FunctionCallNode, ReturnNode, IfNode,
    LoopRepeatNode, LoopForNode, LoopWhileNode, DOMSetNode, DOMRefreshNode,
    DOMClassNode, DOMVisibilityNode, EventNode, FetchNode, TimerNode,
    BrowserActionNode, StorageNode, TryCatchNode, ClassDefNode, ClassInitNode,
    ClassSuperNode, ShapeDefNode, ComponentDefNode, DOMMakeElementNode,
    DOMAddElementNode, DOMAppendToNode, AnimateTargetNode, FunctionalPipelineNode,
    HttpServerNode, HttpRouteNode, HttpReturnJsonNode, StoreDefNode, StoreStateNode,
    World3DNode, AnimationFrameLoopNode, RotateByNode, TranslateByNode,
    RenderSceneNode, MoveTargetNode,
    ExtractDestructureNode, WebSocketConnectNode, WebSocketReceiveNode,
    GeneratorDefNode, GeneratorYieldNode, PreventDefaultNode,
    ListAddNode, ListRemoveAtNode, ListInsertNode
)

def _dom_el(target: str) -> str:
    """Helper to generate reliable element getter: checks id first, then selector."""
    target_clean = target.strip('"\'')
    if target_clean in ("window", "document", "body"):
        return f"document.{target_clean}" if target_clean == "body" else target_clean
    if target_clean.startswith(".") or target_clean.startswith("#") or " " in target_clean:
        return f'document.querySelector("{target_clean}")'
    return f'(document.getElementById("{target_clean}") || document.querySelector("{target_clean}"))'

class ENLGSEmitter:
    """Emits clean JavaScript code from an AST."""

    def __init__(self, script: ScriptNode):
        self.script = script
        self._loop_counter = 0

    def emit(self) -> str:
        lines: List[str] = []
        for node in self.script.body:
            code = self._emit_node(node, indent=0)
            if code:
                lines.append(code)
        return "\n\n".join(lines)

    def _emit_node(self, node: ASTNode, indent: int = 0) -> str:
        pad = "  " * indent

        # ── Raw JS Passthrough ──
        if isinstance(node, RawJSNode):
            return f"{pad}{node.code}"

        # ── Variables ──
        elif isinstance(node, VarDeclNode):
            val = f" = {node.value}" if node.value is not None else ""
            return f"{pad}{node.kind} {node.name}{val};"

        elif isinstance(node, VarAssignNode):
            return f"{pad}{node.name} {node.op} {node.value};"

        elif isinstance(node, ExtractDestructureNode):
            vars_str = ", ".join(node.variables)
            return f"{pad}const {{ {vars_str} }} = {node.source_expr};"

        # ── Output ──
        elif isinstance(node, OutputNode):
            args_str = ", ".join(node.args)
            if node.method == "alert":
                return f"{pad}alert({args_str});"
            elif node.method == "warn":
                return f"{pad}console.warn({args_str});"
            elif node.method == "error":
                return f"{pad}console.error({args_str});"
            return f"{pad}console.log({args_str});"

        # ── Prevent Default ──
        elif isinstance(node, PreventDefaultNode):
            return f"{pad}if (typeof event !== 'undefined' && event.preventDefault) event.preventDefault();"

        # ── Functions & Async ──
        elif isinstance(node, FunctionDefNode):
            async_prefix = "async " if node.is_async else ""
            params_str = ", ".join(node.params)
            lines = [f"{pad}{async_prefix}function {node.name}({params_str}) {{"]
            for child in node.body:
                c = self._emit_node(child, indent + 1)
                if c:
                    lines.append(c)
            lines.append(pad + "}")
            return "\n".join(lines)

        elif isinstance(node, GeneratorDefNode):
            params_str = ", ".join(node.params)
            lines = [f"{pad}function* {node.name}({params_str}) {{"]
            for child in node.body:
                c = self._emit_node(child, indent + 1)
                if c:
                    lines.append(c)
            lines.append(pad + "}")
            return "\n".join(lines)

        elif isinstance(node, GeneratorYieldNode):
            val_str = f" {node.value}" if node.value is not None else ""
            return f"{pad}yield{val_str};"

        elif isinstance(node, FunctionCallNode):
            args_str = ", ".join(node.args)
            return f"{pad}{node.name}({args_str});"

        elif isinstance(node, ReturnNode):
            val_str = f" {node.value}" if node.value is not None else ""
            return f"{pad}return{val_str};"

        elif isinstance(node, HttpReturnJsonNode):
            return pad + "res.writeHead(200, { 'Content-Type': 'application/json' });\n" + pad + f"res.end(JSON.stringify({node.data_expr}));"

        # ── Conditionals ──
        elif isinstance(node, IfNode):
            lines = [f"{pad}if ({node.condition}) {{"]
            for child in node.body:
                c = self._emit_node(child, indent + 1)
                if c:
                    lines.append(c)
            lines.append(pad + "}")

            for elif_cond, elif_body in node.elif_branches:
                lines.append(f"{pad}else if ({elif_cond}) {{")
                for child in elif_body:
                    c = self._emit_node(child, indent + 1)
                    if c:
                        lines.append(c)
                lines.append(pad + "}")

            if node.else_body:
                lines.append(pad + "else {")
                for child in node.else_body:
                    c = self._emit_node(child, indent + 1)
                    if c:
                        lines.append(c)
                lines.append(pad + "}")

            return "\n".join(lines)

        # ── Loops ──
        elif isinstance(node, LoopRepeatNode):
            self._loop_counter += 1
            idx_var = f"_i{self._loop_counter}"
            lines = [f"{pad}for (let {idx_var} = 0; {idx_var} < {node.count}; {idx_var}++) {{"]
            for child in node.body:
                c = self._emit_node(child, indent + 1)
                if c:
                    lines.append(c)
            lines.append(pad + "}")
            return "\n".join(lines)

        elif isinstance(node, LoopForNode):
            lines = [f"{pad}for (const {node.item_name} of {node.iterable}) {{"]
            for child in node.body:
                c = self._emit_node(child, indent + 1)
                if c:
                    lines.append(c)
            lines.append(pad + "}")
            return "\n".join(lines)

        elif isinstance(node, LoopWhileNode):
            lines = [f"{pad}while ({node.condition}) {{"]
            for child in node.body:
                c = self._emit_node(child, indent + 1)
                if c:
                    lines.append(c)
            lines.append(pad + "}")
            return "\n".join(lines)

        # ── DOM Setters ──
        elif isinstance(node, DOMSetNode):
            el = _dom_el(node.target)
            if node.prop_type == "text":
                return f"{pad}{el}.textContent = {node.value};"
            elif node.prop_type == "html":
                return f"{pad}{el}.innerHTML = {node.value};"
            elif node.prop_type == "value":
                return f"{pad}{el}.value = {node.value};"
            elif node.prop_type == "color":
                return f"{pad}{el}.style.color = {node.value};"
            elif node.prop_type == "background":
                return f"{pad}{el}.style.background = {node.value};"
            elif node.prop_type == "width":
                val = f"{node.value}px" if node.value.isdigit() else node.value
                return f"{pad}{el}.style.width = {val};"
            elif node.prop_type == "height":
                val = f"{node.value}px" if node.value.isdigit() else node.value
                return f"{pad}{el}.style.height = {val};"
            elif node.prop_type == "style" and node.style_prop:
                return f"{pad}{el}.style['{node.style_prop}'] = {node.value};"
            return f"{pad}{el}.textContent = {node.value};"

        elif isinstance(node, DOMRefreshNode):
            el = _dom_el(node.target)
            return f"{pad}{el}.textContent = {node.value};"

        elif isinstance(node, DOMClassNode):
            el = _dom_el(node.target)
            return f"{pad}{el}.classList.{node.action}('{node.class_name}');"

        elif isinstance(node, DOMVisibilityNode):
            el = _dom_el(node.target)
            display_val = "'block'" if node.action == "show" else "'none'"
            return f"{pad}{el}.style.display = {display_val};"

        # ── Declarative UI Elements ──
        elif isinstance(node, DOMMakeElementNode):
            lines = [pad + "(function() {", f"{pad}  const el = document.createElement('{node.tag}');"]
            for k, v in node.attrs.items():
                if k == "class":
                    lines.append(f"{pad}  el.className = '{v}';")
                elif k == "id":
                    lines.append(f"{pad}  el.id = '{v}';")
                elif k == "style":
                    lines.append(f"{pad}  el.setAttribute('style', '{v}');")
                else:
                    lines.append(f"{pad}  el.setAttribute('{k}', '{v}');")
            for child in node.body:
                c = self._emit_node(child, indent + 1)
                if c:
                    lines.append(c)
            lines.append(pad + "  return el;")
            lines.append(pad + "})();")
            return "\n".join(lines)

        elif isinstance(node, DOMAddElementNode):
            lines = [pad + "(function(parentEl) {", f"{pad}  const child = document.createElement('{node.tag}');"]
            if node.text:
                lines.append(f"{pad}  child.textContent = {node.text};")
            for k, v in node.attrs.items():
                if k == "class":
                    lines.append(f"{pad}  child.className = '{v}';")
                else:
                    lines.append(f"{pad}  child.setAttribute('{k}', '{v}');")
            lines.append(pad + "  (parentEl || document.body).appendChild(child);")
            lines.append(pad + "})(typeof el !== 'undefined' ? el : null);")
            return "\n".join(lines)

        elif isinstance(node, DOMAppendToNode):
            parent_el = _dom_el(node.parent)
            method = "prepend" if node.is_prepend else "appendChild"
            return f"{pad}{parent_el}.{method}({node.child});"

        elif isinstance(node, AnimateTargetNode):
            el = _dom_el(node.target)
            return pad + f"{el}.animate({node.properties}, {{ duration: {node.duration_ms}, fill: 'forwards' }});"

        # ── List / Array Operations ──
        elif isinstance(node, ListAddNode):
            return f"{pad}{node.target}.push({node.item});"

        elif isinstance(node, ListRemoveAtNode):
            return f"{pad}{node.target}.splice({node.index}, 1);"

        elif isinstance(node, ListInsertNode):
            return f"{pad}{node.target}.splice({node.index}, 0, {node.item});"

        # ── TypeScript Shapes ──
        elif isinstance(node, ShapeDefNode):
            lines = [pad + "/**", pad + f" * @typedef {{Object}} {node.name}"]
            for fname, ftype in node.fields:
                lines.append(pad + f" * @property {{{ftype}}} {fname}")
            lines.append(pad + " */")
            return "\n".join(lines)

        # ── Declarative UI Components ──
        elif isinstance(node, ComponentDefNode):
            props_str = ", ".join(node.props)
            lines = [
                pad + "function " + node.name + "({ " + props_str + " } = {}) {",
                f"{pad}  const componentRoot = document.createElement('div');",
                f"{pad}  componentRoot.className = '{node.name.lower()}-component';"
            ]
            for child in node.body:
                c = self._emit_node(child, indent + 1)
                if c:
                    lines.append(c)
            lines.append(pad + "  return componentRoot;")
            lines.append(pad + "}")
            return "\n".join(lines)

        # ── Events ──
        elif isinstance(node, EventNode):
            el = node.target if node.is_variable else _dom_el(node.target)
            ev_name = node.event_type
            if ev_name == "load" and node.target == "window":
                el = "window"
                ev_name = "DOMContentLoaded"

            if el in ("window", "document", "document.body"):
                lines = [f"{pad}{el}.addEventListener('{ev_name}', function(event) {{"]
                if node.key_filter:
                    lines.append(f"{pad}  if (event.key !== '{node.key_filter}') return;")
                for child in node.body:
                    c = self._emit_node(child, indent + 1)
                    if c:
                        lines.append(c)
                lines.append(pad + "});")
            else:
                lines = [
                    f"{pad}(function() {{",
                    f"{pad}  const targetEl = {el};",
                    f"{pad}  if (targetEl != null) {{",
                    f"{pad}    targetEl.addEventListener('{ev_name}', function(event) {{"
                ]
                if node.key_filter:
                    lines.append(f"{pad}      if (event.key !== '{node.key_filter}') return;")
                for child in node.body:
                    c = self._emit_node(child, indent + 3)
                    if c:
                        lines.append(c)
                lines.append(pad + "    });")
                lines.append(pad + "  }")
                lines.append(pad + "})();")
            return "\n".join(lines)

        # ── Fetch / Network ──
        elif isinstance(node, FetchNode):
            lines = [pad + "(async function() {", pad + "  try {"]
            if node.method == "POST":
                body_opt = f", body: JSON.stringify({node.body_expr})" if node.body_expr else ""
                lines.append(pad + f"    const response = await fetch('{node.url}', {{ method: 'POST', headers: {{ 'Content-Type': 'application/json' }}{body_opt} }});")
            else:
                lines.append(pad + f"    const response = await fetch('{node.url}');")

            lines.append(pad + f"    const {node.response_var} = await response.json();")
            for child in node.body:
                c = self._emit_node(child, indent + 2)
                if c:
                    lines.append(c)
            lines.append(pad + "  } catch (err) {")
            lines.append(pad + "    console.error('Fetch error:', err);")
            lines.append(pad + "  }")
            lines.append(pad + "})();")
            return "\n".join(lines)

        # ── Full-Stack Server ──
        elif isinstance(node, HttpServerNode):
            lines = [
                pad + "const http = require('http');",
                pad + "const server = http.createServer((req, res) => {",
                pad + "  const url = req.url.split('?')[0];",
                pad + "  const method = req.method;"
            ]
            for r in node.routes:
                lines.append(self._emit_node(r, indent + 1))
            lines.append(pad + "  res.writeHead(404, { 'Content-Type': 'text/plain' });")
            lines.append(pad + "  res.end('Not Found');")
            lines.append(pad + "});")
            lines.append(pad + f"server.listen({node.port}, () => console.log('Enlang HTTP Server running on port {node.port}'));")
            return "\n".join(lines)

        elif isinstance(node, HttpRouteNode):
            cond = f"method === '{node.method}' && url === '{node.path}'" if node.method != "ANY" else f"url === '{node.path}'"
            lines = [f"{pad}if ({cond}) {{"]
            for child in node.body:
                lines.append(self._emit_node(child, indent + 1))
            lines.append(pad + "  return;")
            lines.append(pad + "}")
            return "\n".join(lines)

        # ── Centralized State Store ──
        elif isinstance(node, StoreDefNode):
            lines = [
                pad + f"const {node.name} = (function() {{",
                pad + "  let state = {"
            ]
            for sname, sval in node.states:
                lines.append(f"{pad}    {sname}: {sval},")
            lines.append(pad + "  };")
            lines.append(pad + "  const listeners = [];")
            lines.append(pad + "  return {")
            lines.append(pad + "    getState: () => ({ ...state }),")
            lines.append(pad + "    subscribe: (fn) => listeners.push(fn),")
            for act in node.actions:
                params_str = ", ".join(act.params)
                lines.append(f"{pad}    {act.name}: function({params_str}) {{")
                for child in act.body:
                    lines.append(self._emit_node(child, indent + 3))
                lines.append(pad + "      listeners.forEach(fn => fn(state));")
                lines.append(pad + "    },")
            lines.append(pad + "  };")
            lines.append(pad + "})();")
            return "\n".join(lines)

        # ── 3D World & Canvas ──
        elif isinstance(node, World3DNode):
            lines = [
                pad + "(function() {",
                pad + "  if (typeof THREE === 'undefined') return;",
                pad + f"  const canvas = document.getElementById('{node.canvas_target}') || document.querySelector('{node.canvas_target}');",
                pad + "  if (!canvas) return;"
            ]
            for child in node.body:
                lines.append(self._emit_node(child, indent + 1))
            lines.append(pad + "})();")
            return "\n".join(lines)

        elif isinstance(node, AnimationFrameLoopNode):
            lines = [
                pad + "function _enlgs_animLoop() {",
                pad + "  requestAnimationFrame(_enlgs_animLoop);"
            ]
            for child in node.body:
                lines.append(self._emit_node(child, indent + 1))
            lines.append(pad + "}")
            lines.append(pad + "_enlgs_animLoop();")
            return "\n".join(lines)

        elif isinstance(node, RenderSceneNode):
            return pad + f"if (typeof renderer !== 'undefined' && renderer.render) renderer.render({node.scene}, {node.camera});"

        elif isinstance(node, MoveTargetNode):
            coords_str = ", ".join(node.coordinates)
            return pad + f"{node.target}.position.set({coords_str});"

        elif isinstance(node, RotateByNode):
            stmts = []
            for axis, val in node.rotations.items():
                stmts.append(f"{node.target}.rotation.{axis} += {val};")
            return f"{pad}" + f"\n{pad}".join(stmts)

        elif isinstance(node, TranslateByNode):
            stmts = []
            for axis, val in node.translations.items():
                stmts.append(f"{node.target}.position.{axis} += {val};")
            return f"{pad}" + f"\n{pad}".join(stmts)

        # ── WebSockets ──
        elif isinstance(node, WebSocketConnectNode):
            return f"{pad}const {node.socket_var} = new WebSocket('{node.url}');"

        elif isinstance(node, WebSocketReceiveNode):
            lines = [
                f"{pad}{node.socket_var}.addEventListener('message', function(event) {{",
                f"{pad}  let {node.data_var} = event.data;",
                pad + "  try { " + node.data_var + " = JSON.parse(event.data); } catch(e) {}"
            ]
            for child in node.body:
                lines.append(self._emit_node(child, indent + 1))
            lines.append(pad + "});")
            return "\n".join(lines)

        # ── Timers ──
        elif isinstance(node, TimerNode):
            fn_name = "setTimeout" if node.timer_type == "after" else "setInterval"
            lines = [f"{pad}{fn_name}(function() {{"]
            for child in node.body:
                c = self._emit_node(child, indent + 1)
                if c:
                    lines.append(c)
            lines.append(pad + "}, " + str(node.duration_ms) + ");")
            return "\n".join(lines)

        # ── Browser Actions ──
        elif isinstance(node, BrowserActionNode):
            if node.action == "redirect":
                return f"{pad}window.location.href = {node.arg};"
            elif node.action == "reload":
                return f"{pad}window.location.reload();"
            elif node.action == "back":
                return f"{pad}window.history.back();"
            elif node.action == "forward":
                return f"{pad}window.history.forward();"
            elif node.action == "scroll":
                target_el = _dom_el(node.arg) if node.arg else "window"
                return pad + f"{target_el}.scrollIntoView({{ behavior: 'smooth' }});"
            elif node.action == "copy":
                return f"{pad}navigator.clipboard.writeText({node.arg});"
            elif node.action == "open":
                return f"{pad}window.open({node.arg}, '_blank');"
            return ""

        # ── Storage ──
        elif isinstance(node, StorageNode):
            if node.action == "set":
                return f"{pad}localStorage.setItem('{node.key}', {node.value});"
            elif node.action == "get":
                return f"{pad}localStorage.getItem('{node.key}');"
            elif node.action == "remove":
                return f"{pad}localStorage.removeItem('{node.key}');"
            elif node.action == "clear":
                return f"{pad}localStorage.clear();"
            return ""

        # ── Error Handling ──
        elif isinstance(node, TryCatchNode):
            lines = [pad + "try {"]
            for child in node.try_body:
                c = self._emit_node(child, indent + 1)
                if c:
                    lines.append(c)
            lines.append(pad + f"}} catch ({node.error_var}) {{")
            for child in node.catch_body:
                c = self._emit_node(child, indent + 1)
                if c:
                    lines.append(c)
            lines.append(pad + "}")
            return "\n".join(lines)

        # ── OOP / Classes / Blueprints ──
        elif isinstance(node, ClassDefNode):
            heritage = f" extends {node.parent}" if node.parent else ""
            lines = [f"{pad}class {node.name}{heritage} {{"]
            for child in node.body:
                c = self._emit_node(child, indent + 1)
                if c:
                    lines.append(c)
            lines.append(pad + "}")
            return "\n".join(lines)

        elif isinstance(node, ClassInitNode):
            params_str = ", ".join(node.params)
            lines = [f"{pad}constructor({params_str}) {{"]
            for child in node.body:
                c = self._emit_node(child, indent + 1)
                if c:
                    lines.append(c)
            lines.append(pad + "}")
            return "\n".join(lines)

        elif isinstance(node, ClassSuperNode):
            args_str = ", ".join(node.args)
            return f"{pad}super({args_str});"

        return ""

