DatabaseEngine = NativeExecutionEngine

enlngdb/locking.py:
"""Sovereign Concurrency and Locking Subsystem for enlngdb (ZERO EXTERNAL DEPENDENCIES).

Provides:
- In-process Read-Write Lock (RWLock): multiple concurrent readers, exclusive single writer.
- Cross-process OS FileLock: uses msvcrt on Windows and fcntl on Unix for crash-resilient process locking.
- DatabaseLock: unified lock coordinator managing table and file-level integrity.
"""

import os
import sys
import time
import threading
from contextlib import contextmanager
from typing import Optional


class LockTimeoutError(Exception):
    """Raised when acquiring a lock exceeds the timeout threshold."""
    pass


class RWLock:
    """In-process Re-entrant Read-Write Lock supporting concurrent readers and exclusive writers."""

    def __init__(self):
        self._lock = threading.RLock()
        self._read_ready = threading.Condition(self._lock)
        self._readers = 0
        self._writers_waiting = 0
        self._writer_active = False
        self._writer_thread: Optional[int] = None
        self._writer_depth: int = 0

    def acquire_read(self, timeout: Optional[float] = None):
        """Acquires a shared read lock."""
        start_time = time.time()
        current_thread = threading.get_ident()
        with self._lock:
            # If current thread is already holding write lock, it can read its own writes reentrantly
            if self._writer_thread == current_thread:
                self._readers += 1
                return

            while self._writer_active or self._writers_waiting > 0:
                if timeout is not None:
                    elapsed = time.time() - start_time
                    remaining = timeout - elapsed
                    if remaining <= 0:
                        raise LockTimeoutError("Timed out waiting for read lock.")
                    self._read_ready.wait(remaining)
                else:
                    self._read_ready.wait()
            self._readers += 1

    def release_read(self):
        """Releases a shared read lock."""
        with self._lock:
            self._readers -= 1
            if self._readers == 0:
                self._read_ready.notify_all()

    def acquire_write(self, timeout: Optional[float] = None):
        """Acquires an exclusive write lock (re-entrant for the same thread)."""
        start_time = time.time()
        current_thread = threading.get_ident()
        with self._lock:
            if self._writer_thread == current_thread:
                self._writer_depth += 1
                return

            self._writers_waiting += 1
            try:
                while self._readers > 0 or self._writer_active:
                    if timeout is not None:
                        elapsed = time.time() - start_time
                        remaining = timeout - elapsed
                        if remaining <= 0:
                            raise LockTimeoutError("Timed out waiting for write lock.")
                        self._read_ready.wait(remaining)
                    else:
                        self._read_ready.wait()
                self._writer_active = True
                self._writer_thread = current_thread
                self._writer_depth = 1
            finally:
                self._writers_waiting -= 1

    def release_write(self):
        """Releases an exclusive write lock."""
        with self._lock:
            if self._writer_thread != threading.get_ident():
                return
            self._writer_depth -= 1
            if self._writer_depth == 0:
                self._writer_active = False
                self._writer_thread = None
                self._read_ready.notify_all()

    @contextmanager
    def read_lock(self, timeout: Optional[float] = None):
        self.acquire_read(timeout)
        try:
            yield
        finally:
            self.release_read()

    @contextmanager
    def write_lock(self, timeout: Optional[float] = None):
        self.acquire_write(timeout)
        try:
            yield
        finally:
            self.release_write()


class FileLock:
    """Cross-process OS-level advisory file lock with timeout and exponential backoff."""

    def __init__(self, lock_file_path: str, timeout: float = 10.0):
        self.lock_file_path = lock_file_path
        self.timeout = timeout
        self._fd: Optional[int] = None

    def acquire(self) -> bool:
        """Acquires an exclusive OS-level file lock."""
        start = time.time()
        backoff = 0.005

        os.makedirs(os.path.dirname(os.path.abspath(self.lock_file_path)) or ".", exist_ok=True)

        while True:
            try:
                self._fd = os.open(self.lock_file_path, os.O_CREAT | os.O_RDWR)
                if sys.platform == "win32":
                    import msvcrt
                    # Lock 1 byte from the beginning of the file non-blocking
                    msvcrt.locking(self._fd, msvcrt.LK_NBLCK, 1)
                else:
                    import fcntl
                    fcntl.flock(self._fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                return True
            except (BlockingIOError, PermissionError, OSError):
                if self._fd is not None:
                    try:
                        os.close(self._fd)
                    except OSError:
                        pass
                    self._fd = None

                elapsed = time.time() - start
                if elapsed >= self.timeout:
                    raise LockTimeoutError(
                        f"Failed to acquire cross-process lock on '{self.lock_file_path}' after {self.timeout:.1f}s."
                    )
                time.sleep(backoff)
                backoff = min(backoff * 1.5, 0.1)

    def release(self):
        """Releases the exclusive OS-level file lock."""
        if self._fd is not None:
            try:
                if sys.platform == "win32":
                    import msvcrt
                    try:
                        msvcrt.locking(self._fd, msvcrt.LK_UNLCK, 1)
                    except OSError:
                        pass
                else:
                    import fcntl
                    try:
                        fcntl.flock(self._fd, fcntl.LOCK_UN)
                    except OSError:
                        pass
            finally:
                try:
                    os.close(self._fd)
                except OSError:
                    pass
                self._fd = None

    def __enter__(self):
        self.acquire()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.release()


class DatabaseLock:
    """Unified lock coordinator combining in-process RWLock and cross-process FileLock."""

    def __init__(self, db_path: Optional[str] = None):
        self.db_path = db_path
        self._rwlock = RWLock()
        self._file_lock: Optional[FileLock] = None

        if self.db_path and self.db_path != ":memory:":
            lock_path = f"{self.db_path}.lock"
            self._file_lock = FileLock(lock_path)

    @contextmanager
    def read(self, timeout: Optional[float] = 10.0):
        """Shared read lock across threads."""
        with self._rwlock.read_lock(timeout):
            yield

    @contextmanager
    def write(self, timeout: Optional[float] = 10.0):
        """Exclusive write lock across threads and processes."""
        with self._rwlock.write_lock(timeout):
            if self._file_lock:
                with self._file_lock:
                    yield
            else:
                yield

enlngdb/paging.py:
"""Sovereign Memory Paging and Chunked Buffer Pool for enlngdb (ZERO EXTERNAL DEPENDENCIES).

Prevents RAM saturation when database size exceeds physical memory.
Features:
- LRUPageCache: Bounded in-memory page buffer pool with Least-Recently-Used eviction.
- ChunkedTable: Divides large datasets into manageable 4KB/record-bounded pages on disk.
- Lazy Page Swapping: Loads only queried chunks into RAM on-demand.
- Paging Iterator: Generator-based streaming for zero-copy queries with LIMIT and OFFSET.
"""

import os
import sys
import json
from collections import OrderedDict
from typing import Dict, List, Any, Optional, Callable, Generator


DEFAULT_PAGE_SIZE = 250       # Number of rows per page chunk
DEFAULT_CACHE_CAPACITY = 20   # Maximum pages kept in RAM (20 pages * 250 = 5000 rows in memory)


class LRUPageCache:
    """Least-Recently-Used (LRU) Page Buffer Pool for table record chunks."""

    def __init__(self, capacity: int = DEFAULT_CACHE_CAPACITY, on_evict: Optional[Callable[[int, List[Dict[str, Any]]], None]] = None):
        self.capacity = max(1, capacity)
        self.on_evict = on_evict
        self._cache: OrderedDict[int, List[Dict[str, Any]]] = OrderedDict()
        self._dirty_pages = set()

    def get(self, page_id: int) -> Optional[List[Dict[str, Any]]]:
        """Fetches page from buffer pool and marks it as recently used."""
        if page_id not in self._cache:
            return None
        self._cache.move_to_end(page_id)
        return self._cache[page_id]

    def put(self, page_id: int, page_data: List[Dict[str, Any]], is_dirty: bool = False):
        """Puts a page into the buffer pool, evicting the oldest page if capacity is reached."""
        if page_id in self._cache:
            self._cache.move_to_end(page_id)
        self._cache[page_id] = page_data
        if is_dirty:
            self._dirty_pages.add(page_id)

        # Evict oldest pages if over capacity
        while len(self._cache) > self.capacity:
            oldest_page_id, evicted_data = self._cache.popitem(last=False)
            if oldest_page_id in self._dirty_pages:
                if self.on_evict:
                    self.on_evict(oldest_page_id, evicted_data)
                self._dirty_pages.discard(oldest_page_id)

    def mark_dirty(self, page_id: int):
        self._dirty_pages.add(page_id)

    def flush_all(self):
        """Flushes all dirty pages through eviction callback."""
        if self.on_evict:
            for page_id in list(self._dirty_pages):
                if page_id in self._cache:
                    self.on_evict(page_id, self._cache[page_id])
        self._dirty_pages.clear()

    def clear(self):
        self.flush_all()
        self._cache.clear()

    def __len__(self):
        return len(self._cache)


class PagedRecordStream:
    """Streaming iterator that processes records chunk-by-chunk without full RAM allocation."""

    @staticmethod
    def stream_filter(rows_generator: Generator[Dict[str, Any], None, None],
                      filter_fn: Optional[Callable[[Dict[str, Any]], bool]] = None,
                      limit: Optional[int] = None,
                      offset: Optional[int] = None) -> Generator[Dict[str, Any], None, None]:
        skipped = 0
        yielded = 0

        target_offset = offset or 0
        target_limit = limit if (limit is not None and limit >= 0) else None

        for row in rows_generator:
            if filter_fn and not filter_fn(row):
                continue

            if skipped < target_offset:
                skipped += 1
                continue

            yield row
            yielded += 1

            if target_limit is not None and yielded >= target_limit:
                break


def estimate_memory_bytes(obj: Any) -> int:
    """Fast estimation of in-memory data footprint."""
    if isinstance(obj, dict):
        return sys.getsizeof(obj) + sum(estimate_memory_bytes(k) + estimate_memory_bytes(v) for k, v in obj.items())
    elif isinstance(obj, (list, tuple, set)):
        return sys.getsizeof(obj) + sum(estimate_memory_bytes(x) for x in obj)
    return sys.getsizeof(obj)

enlngdb/parser.py:
"""Parser for enlngdb (Sovereign Native Storage Engine - ZERO SQL)."""

from typing import List, Optional, Any, Dict
from enlngdb.tokens import Token, TokenType
from enlngdb.ast_nodes import (
    ProgramNode, DomainHeaderNode, DisplayNode, CreateTableNode, ColumnDefNode,
    InsertRecordNode, FindRecordsNode, UpdateRecordsNode, DeleteRecordsNode,
    CountRecordsNode, OpenDatabaseNode, SaveDatabaseNode, HintNode, OrderByNode,
    BinaryOpNode, UnaryOpNode, IdentifierNode, LiteralNode, ASTNode,
    ShowDatabasesNode, ShowTablesNode, UseDatabaseNode,
    DeleteColumnNode, DropTableNode, DropDatabaseNode
)


class ParserError(Exception):
    def __init__(self, message: str, token: Optional[Token] = None, hint: str = ""):
        self.message = message
        self.token = token
        self.hint = hint
        loc = f" at L{token.line}:C{token.column}" if token else ""
        hint_text = f"\n  💡 Hint: {hint}" if hint else ""
        super().__init__(f"Parser error{loc}: {message}{hint_text}")


class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Token:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return self.tokens[-1]

    def peek_token(self, offset: int = 1) -> Token:
        idx = self.pos + offset
        if idx < len(self.tokens):
            return self.tokens[idx]
        return self.tokens[-1]

    def match(self, *expected_types: TokenType) -> bool:
        return self.current_token().type in expected_types

    def consume(self, expected_type: TokenType, error_msg: str = "", hint: str = "") -> Token:
        tok = self.current_token()
        if tok.type == expected_type:
            self.pos += 1
            return tok
        msg = error_msg or f"Expected token {expected_type.name}, but found {tok.type.name} ('{tok.value}')"
        raise ParserError(msg, tok, hint)

    def skip_newlines(self):
        while self.match(TokenType.NEWLINE, TokenType.SEMICOLON):
            self.pos += 1

    def skip_silent_words(self):
        """Skips conversational filler words like 'the', 'a', 'an', 'please', 'records', 'rows', etc."""
        silent_types = {
            TokenType.THE, TokenType.A, TokenType.AN,
            TokenType.PLEASE, TokenType.KINDLY,
            TokenType.RECORD, TokenType.RECORDS,
            TokenType.ROW, TokenType.ROWS,
            TokenType.ENTRY, TokenType.ENTRIES,
            TokenType.DATA, TokenType.ITEM, TokenType.ITEMS
        }
        delimiters = {
            TokenType.WITH, TokenType.WHERE, TokenType.SET,
            TokenType.COMMA, TokenType.SEMICOLON, TokenType.NEWLINE,
            TokenType.EOF, TokenType.COLON, TokenType.EQUALS, TokenType.IS
        }
        while self.match(*silent_types):
            if self.peek_token(1).type in delimiters:
                break
            self.pos += 1

    def parse_hints_dict(self) -> Dict[str, Any]:
        """Parses 'hint key: val, key2: val2' into a dictionary."""
        self.consume(TokenType.HINT)
        hints: Dict[str, Any] = {}
        while True:
            self.skip_silent_words()
            key_tok = self.current_token()
            if self.match(TokenType.IDENTIFIER, TokenType.INDEX, TokenType.DEFAULT):
                self.pos += 1
                key = str(key_tok.value)
            else:
                break
            if self.match(TokenType.COLON, TokenType.EQUALS):
                self.pos += 1
            val_expr = self.parse_expression()
            if isinstance(val_expr, LiteralNode):
                hints[key] = val_expr.value
            elif isinstance(val_expr, IdentifierNode):
                hints[key] = val_expr.name
            else:
                hints[key] = val_expr

            if self.match(TokenType.COMMA):
                self.consume(TokenType.COMMA)
            else:
                break
        return hints

    def parse(self) -> ProgramNode:
        self.skip_newlines()
        while self.match(TokenType.INDENT, TokenType.DEDENT):
            self.pos += 1

        header = None
        if self.match(TokenType.TYPE):
            self.consume(TokenType.TYPE)
            if self.match(TokenType.ENLNGDB, TokenType.ENLGDB):
                dom_tok = self.consume(self.current_token().type)
                header = DomainHeaderNode(domain=str(dom_tok.value))
                self.skip_newlines()

        statements: List[ASTNode] = []
        while not self.match(TokenType.EOF):
            self.skip_newlines()
            while self.match(TokenType.INDENT, TokenType.DEDENT):
                self.pos += 1
            if self.match(TokenType.EOF):
                break
            stmt = self.parse_statement()
            if stmt:
                statements.append(stmt)
            while self.match(TokenType.SEMICOLON):
                self.consume(TokenType.SEMICOLON)
            self.skip_newlines()

        return ProgramNode(header=header, statements=statements)

    def parse_statement(self) -> ASTNode:
        self.skip_silent_words()
        tok = self.current_token()

        # DISPLAY ...
        if self.match(TokenType.DISPLAY):
            return self.parse_display()

        # HINT ...
        elif self.match(TokenType.HINT):
            return HintNode(hints=self.parse_hints_dict())

        # OPEN / CONNECT DATABASE ...
        elif self.match(TokenType.OPEN, TokenType.CONNECT):
            return self.parse_open_database()

        # USE DATABASE ...
        elif self.match(TokenType.USE):
            return self.parse_use_database()

        # SAVE DATABASE ...
        elif self.match(TokenType.SAVE):
            if self.peek_token(1).type == TokenType.DATABASE:
                return self.parse_save_database()
            return self.parse_insert()

        # CREATE TABLE ...
        elif self.match(TokenType.CREATE):
            return self.parse_create_table()

        # INSERT INTO / PUT ...
        elif self.match(TokenType.INSERT, TokenType.PUT):
            return self.parse_insert()

        # SHOW DATABASES / TABLES ...
        elif self.match(TokenType.SHOW):
            saved_pos = self.pos
            self.consume(TokenType.SHOW)
            self.skip_silent_words()
            if self.match(TokenType.DATABASES, TokenType.DATABASE):
                self.consume(self.current_token().type)
                return ShowDatabasesNode()
            elif self.match(TokenType.TABLES, TokenType.TABLE):
                is_plural = self.match(TokenType.TABLES)
                self.consume(self.current_token().type)
                self.skip_silent_words()
                db_name = None
                if self.match(TokenType.OF, TokenType.IN, TokenType.FROM):
                    self.consume(self.current_token().type)
                    self.skip_silent_words()
                    if self.match(TokenType.DATABASE):
                        self.consume(TokenType.DATABASE)
                        self.skip_silent_words()
                    db_name = self.parse_path_or_identifier("database name")
                    return ShowTablesNode(database_name=db_name)
                elif not is_plural and self.match(TokenType.IDENTIFIER, TokenType.STRING_LITERAL):
                    tbl = self.parse_identifier_or_string("table name")
                    return FindRecordsNode(table_name=tbl, fields=["*"])
                return ShowTablesNode(database_name=None)
            self.pos = saved_pos
            return self.parse_find()

        # FIND / FETCH / GET / SELECT ...
        elif self.match(TokenType.FIND, TokenType.FETCH, TokenType.GET, TokenType.SELECT):
            return self.parse_find()

        # UPDATE / CHANGE ...
        elif self.match(TokenType.UPDATE, TokenType.CHANGE):
            return self.parse_update()

        # COUNT ...
        elif self.match(TokenType.COUNT):
            return self.parse_count()

        # DELETE / REMOVE / DROP ...
        elif self.match(TokenType.DELETE, TokenType.REMOVE, TokenType.DROP):
            return self.parse_delete()

        else:
            raise ParserError(
                f"Unexpected enlngdb statement starting with '{tok.value}'",
                tok,
                "Valid statements: create table, insert record, find records, update records, count records, delete records, display, hint."
            )

    # -------------------------------------------------------------
    # 1. DISPLAY
    # -------------------------------------------------------------
    def parse_display(self) -> DisplayNode:
        self.consume(TokenType.DISPLAY)
        msg_expr = self.parse_expression()
        return DisplayNode(message=msg_expr)

    # -------------------------------------------------------------
    # 2. DATABASE OPEN, USE & SAVE
    # -------------------------------------------------------------
    def parse_use_database(self) -> UseDatabaseNode:
        self.consume(TokenType.USE)
        self.skip_silent_words()
        if self.match(TokenType.DATABASE):
            self.consume(TokenType.DATABASE)
            self.skip_silent_words()
        path = self.parse_path_or_identifier("database name or path")
        return UseDatabaseNode(db_path=path)

    def parse_open_database(self) -> OpenDatabaseNode:
        self.consume(self.current_token().type)  # OPEN or CONNECT
        self.skip_silent_words()
        if self.match(TokenType.TO):
            self.consume(TokenType.TO)
            self.skip_silent_words()
        if self.match(TokenType.DATABASE):
            self.consume(TokenType.DATABASE)
            self.skip_silent_words()
        path = self.parse_path_or_identifier("database file path")
        return OpenDatabaseNode(db_path=path)

    def parse_save_database(self) -> SaveDatabaseNode:
        self.consume(TokenType.SAVE)
        self.consume(TokenType.DATABASE)
        self.skip_silent_words()
        if self.match(TokenType.TO):
            self.consume(TokenType.TO)
            self.skip_silent_words()
        path = self.parse_path_or_identifier("database file path")
        return SaveDatabaseNode(db_path=path)

    # -------------------------------------------------------------
    # 3. CREATE TABLE
    # -------------------------------------------------------------
    def parse_create_table(self) -> CreateTableNode:
        self.consume(TokenType.CREATE)
        self.consume(TokenType.TABLE)
        self.skip_silent_words()

        if_not_exists = False
        if self.match(TokenType.IF):
            self.consume(TokenType.IF)
            if self.match(TokenType.NOT):
                self.consume(TokenType.NOT)
            if self.match(TokenType.EXISTS):
                self.consume(TokenType.EXISTS)
            if_not_exists = True
            self.skip_silent_words()

        table_name = self.parse_identifier_or_string("table name")
        self.skip_silent_words()

        self.consume(TokenType.WITH, "Expected 'with' after table name", "Use: create table accounts with id, name, balance")
        columns: List[ColumnDefNode] = []
        table_hints: Dict[str, Any] = {}

        if self.match(TokenType.COLON):
            # Indented block schema definition
            self.consume(TokenType.COLON)
            self.skip_newlines()
            self.consume(TokenType.INDENT, "Expected indented column definitions")
            while not self.match(TokenType.DEDENT, TokenType.EOF):
                self.skip_newlines()
                if self.match(TokenType.DEDENT, TokenType.EOF):
                    break
                if self.match(TokenType.HINT):
                    table_hints.update(self.parse_hints_dict())
                else:
                    col_def = self.parse_indented_column_def()
                    columns.append(col_def)
                self.skip_newlines()
            self.consume(TokenType.DEDENT)
        else:
            # Inline comma-separated field list: with id, account_holder, balance, status
            while True:
                self.skip_silent_words()
                col_name = self.parse_identifier_or_string("column name")
                columns.append(ColumnDefNode(name=col_name, data_type="ANY"))
                self.skip_silent_words()
                if self.match(TokenType.COMMA):
                    self.consume(TokenType.COMMA)
                else:
                    break

        return CreateTableNode(table_name=table_name, columns=columns, if_not_exists=if_not_exists, hints=table_hints)

    def parse_indented_column_def(self) -> ColumnDefNode:
        col_name = self.parse_identifier_or_string("column name")
        data_type = "ANY"
        if self.match(TokenType.AS):
            self.consume(TokenType.AS)
            type_tok = self.current_token()
            data_type = str(type_tok.value).upper()
            self.pos += 1

        is_primary = False
        col_hints = {}
        while not self.match(TokenType.NEWLINE, TokenType.DEDENT, TokenType.EOF):
            if self.match(TokenType.PRIMARY):
                self.consume(TokenType.PRIMARY)
                if self.match(TokenType.KEY):
                    self.consume(TokenType.KEY)
                is_primary = True
            elif self.match(TokenType.HINT):
                col_hints.update(self.parse_hints_dict())
            else:
                break

        return ColumnDefNode(name=col_name, data_type=data_type, is_primary_key=is_primary, hints=col_hints)

    # -------------------------------------------------------------
    # 4. INSERT RECORD
    # -------------------------------------------------------------
    def parse_insert(self) -> InsertRecordNode:
        self.consume(self.current_token().type)  # INSERT, PUT, SAVE
        self.skip_silent_words()
        if self.match(TokenType.INTO):
            self.consume(TokenType.INTO)
        self.skip_silent_words()
        table_name = self.parse_identifier_or_string("table name")
        self.skip_silent_words()

        if self.match(TokenType.VALUES, TokenType.WITH):
            self.consume(self.current_token().type)
        if self.match(TokenType.COLON):
            self.consume(TokenType.COLON)

        self.skip_newlines()
        values: Dict[str, Any] = {}

        if self.match(TokenType.INDENT):
            self.consume(TokenType.INDENT)
            while not self.match(TokenType.DEDENT, TokenType.EOF):
                self.skip_newlines()
                if self.match(TokenType.DEDENT, TokenType.EOF):
                    break
                k, v = self.parse_key_value_assignment()
                values[k] = v
                self.skip_newlines()
            self.consume(TokenType.DEDENT)
        else:
            # Inline key-value pairs: with id 101, account_holder "Bibhu", balance 85000
            while True:
                self.skip_silent_words()
                k, v = self.parse_key_value_assignment()
                values[k] = v
                self.skip_silent_words()
                if self.match(TokenType.COMMA, TokenType.AND):
                    self.consume(self.current_token().type)
                else:
                    break

        hints = {}
        self.skip_silent_words()
        if self.match(TokenType.HINT):
            hints = self.parse_hints_dict()

        return InsertRecordNode(table_name=table_name, values=values, hints=hints)

    def parse_key_value_assignment(self) -> tuple:
        self.skip_silent_words()
        key = self.parse_identifier_or_string("field name")
        self.skip_silent_words()
        if self.match(TokenType.COLON, TokenType.EQUALS, TokenType.AS, TokenType.TO, TokenType.IS):
            self.consume(self.current_token().type)

        self.skip_silent_words()
        val = self.parse_expression()
        return key, val

    # -------------------------------------------------------------
    # 5. FIND RECORDS
    # -------------------------------------------------------------
    def parse_find(self) -> FindRecordsNode:
        self.consume(self.current_token().type)  # FIND, FETCH, GET, SELECT, SHOW
        self.skip_silent_words()

        limit = None
        if self.match(TokenType.TOP):
            self.consume(TokenType.TOP)
            self.skip_silent_words()
            num_tok = self.consume(TokenType.NUMBER_LITERAL, "Expected integer after 'top'")
            limit = int(num_tok.value)
            self.skip_silent_words()

        fields: List[str] = []
        if self.match(TokenType.ALL):
            self.consume(TokenType.ALL)
            fields = ["*"]
            self.skip_silent_words()
            if self.match(TokenType.VALUES):
                self.consume(TokenType.VALUES)
                self.skip_silent_words()
        elif self.match(TokenType.VALUES):
            self.consume(TokenType.VALUES)
            fields = ["*"]
            self.skip_silent_words()
        elif self.match(TokenType.FROM, TokenType.IN):
            fields = ["*"]
        else:
            while True:
                self.skip_silent_words()
                f_name = self.parse_identifier_or_string("field name")
                fields.append(f_name)
                self.skip_silent_words()
                if self.match(TokenType.COMMA, TokenType.AND):
                    self.consume(self.current_token().type)
                else:
                    break

        if self.match(TokenType.FROM, TokenType.IN):
            self.consume(self.current_token().type)
        else:
            raise ParserError("Expected 'from' or 'in' after field list in find statement", self.current_token())

        self.skip_silent_words()
        table_name = self.parse_identifier_or_string("table name")
        self.skip_silent_words()

        where = None
        if self.match(TokenType.WHERE):
            self.consume(TokenType.WHERE)
            self.skip_silent_words()
            where = self.parse_expression()

        order_by = None
        self.skip_silent_words()
        if self.match(TokenType.ORDER, TokenType.SORTED):
            self.consume(self.current_token().type)
            self.skip_silent_words()
            if self.match(TokenType.BY):
                self.consume(TokenType.BY)
                self.skip_silent_words()
            f_name = self.parse_identifier_or_string("sort field")
            direction = "ASC"
            self.skip_silent_words()
            if self.match(TokenType.DESCENDING, TokenType.DESC, TokenType.HIGHEST):
                self.pos += 1
                if self.match(TokenType.FIRST):
                    self.consume(TokenType.FIRST)
                direction = "DESC"
            elif self.match(TokenType.ASCENDING, TokenType.ASC, TokenType.LOWEST):
                self.pos += 1
                if self.match(TokenType.FIRST):
                    self.consume(TokenType.FIRST)
                direction = "ASC"
            order_by = OrderByNode(field=f_name, direction=direction)

        self.skip_silent_words()
        offset = None
        if self.match(TokenType.LIMIT):
            self.consume(TokenType.LIMIT)
            self.skip_silent_words()
            if self.match(TokenType.TO):
                self.consume(TokenType.TO)
                self.skip_silent_words()
            num_tok = self.consume(TokenType.NUMBER_LITERAL, "Expected limit count")
            limit = int(num_tok.value)

        self.skip_silent_words()
        if self.match(TokenType.OFFSET):
            self.consume(TokenType.OFFSET)
            self.skip_silent_words()
            num_tok = self.consume(TokenType.NUMBER_LITERAL, "Expected offset count")
            offset = int(num_tok.value)

        hints = {}
        self.skip_silent_words()
        if self.match(TokenType.HINT):
            hints = self.parse_hints_dict()

        return FindRecordsNode(
            table_name=table_name,
            fields=fields,
            where=where,
            order_by=order_by,
            limit=limit,
            offset=offset,
            hints=hints
        )

    # -------------------------------------------------------------
    # 6. UPDATE RECORDS
    # -------------------------------------------------------------
    def parse_update(self) -> UpdateRecordsNode:
        self.consume(self.current_token().type)  # UPDATE or CHANGE
        self.skip_silent_words()
        if self.match(TokenType.IN):
            self.consume(TokenType.IN)
        self.skip_silent_words()
        table_name = self.parse_identifier_or_string("table name")
        self.skip_silent_words()

        self.consume(TokenType.SET, "Expected 'set' in update statement", "Use: update accounts set status = 'VIP' where ...")
        self.skip_silent_words()

        assignments: Dict[str, Any] = {}
        while True:
            self.skip_silent_words()
            k, v = self.parse_key_value_assignment()
            assignments[k] = v
            self.skip_silent_words()
            if self.match(TokenType.COMMA, TokenType.AND):
                self.consume(self.current_token().type)
            else:
                break

        where = None
        self.skip_silent_words()
        if self.match(TokenType.WHERE):
            self.consume(TokenType.WHERE)
            self.skip_silent_words()
            where = self.parse_expression()

        hints = {}
        self.skip_silent_words()
        if self.match(TokenType.HINT):
            hints = self.parse_hints_dict()

        return UpdateRecordsNode(table_name=table_name, assignments=assignments, where=where, hints=hints)

    # -------------------------------------------------------------
    # 7. COUNT RECORDS
    # -------------------------------------------------------------
    def parse_count(self) -> CountRecordsNode:
        self.consume(TokenType.COUNT)
        self.skip_silent_words()
        if self.match(TokenType.ALL):
            self.consume(TokenType.ALL)
            self.skip_silent_words()

        if self.match(TokenType.IN, TokenType.FROM):
            self.consume(self.current_token().type)
        else:
            raise ParserError("Expected 'in' or 'from' in count statement", self.current_token(),
                              "Use: count records in accounts where ...")

        self.skip_silent_words()
        table_name = self.parse_identifier_or_string("table name")
        self.skip_silent_words()

        where = None
        if self.match(TokenType.WHERE):
            self.consume(TokenType.WHERE)
            self.skip_silent_words()
            where = self.parse_expression()

        hints = {}
        self.skip_silent_words()
        if self.match(TokenType.HINT):
            hints = self.parse_hints_dict()

        return CountRecordsNode(table_name=table_name, where=where, hints=hints)

    # -------------------------------------------------------------
    # 8. DELETE RECORDS
    # -------------------------------------------------------------
    def parse_delete(self) -> ASTNode:
        self.consume(self.current_token().type)  # DELETE, REMOVE, DROP
        self.skip_silent_words()

        # 1. DELETE/DROP DATABASE <database_name> [CONFIRMED]
        if self.match(TokenType.DATABASE):
            self.consume(TokenType.DATABASE)
            self.skip_silent_words()
            db_name = self.parse_path_or_identifier("database name")
            self.skip_silent_words()
            confirm_tok = None
            if self.match(TokenType.CONFIRMED, TokenType.CONFIRM):
                self.consume(self.current_token().type)
                confirm_tok = "CONFIRMED"
            hints = {}
            self.skip_silent_words()
            if self.match(TokenType.HINT):
                hints = self.parse_hints_dict()
            return DropDatabaseNode(database_name=db_name, confirmation_token=confirm_tok, hints=hints)

        # 2. DELETE/DROP TABLE <table_name> [CONFIRMED]
        if self.match(TokenType.TABLE):
            self.consume(TokenType.TABLE)
            self.skip_silent_words()
            table_name = self.parse_identifier_or_string("table name")
            self.skip_silent_words()
            confirm_tok = None
            if self.match(TokenType.CONFIRMED, TokenType.CONFIRM):
                self.consume(self.current_token().type)
                confirm_tok = "CONFIRMED"
            hints = {}
            self.skip_silent_words()
            if self.match(TokenType.HINT):
                hints = self.parse_hints_dict()
            return DropTableNode(table_name=table_name, confirmation_token=confirm_tok, hints=hints)

        # 3. DELETE/DROP COLUMN <column_name> FROM/IN <table_name>
        if self.match(TokenType.COLUMN):
            self.consume(TokenType.COLUMN)
            self.skip_silent_words()
            col_name = self.parse_identifier_or_string("column name")
            self.skip_silent_words()
            if self.match(TokenType.FROM, TokenType.IN):
                self.consume(self.current_token().type)
            else:
                raise ParserError("Expected 'from' or 'in' after column name in delete statement", self.current_token())
            self.skip_silent_words()
            table_name = self.parse_identifier_or_string("table name")
            hints = {}
            self.skip_silent_words()
            if self.match(TokenType.HINT):
                hints = self.parse_hints_dict()
            return DeleteColumnNode(table_name=table_name, column_name=col_name, hints=hints)

        # 4. DELETE <column_name> FROM/IN <table_name> (e.g. "delete rollno from student;")
        if not self.match(TokenType.FROM, TokenType.IN, TokenType.ALL, TokenType.WHERE) and self.match(TokenType.IDENTIFIER):
            saved = self.pos
            potential_col = self.parse_identifier_or_string("column name")
            self.skip_silent_words()
            if self.match(TokenType.FROM, TokenType.IN):
                self.consume(self.current_token().type)
                self.skip_silent_words()
                table_name = self.parse_identifier_or_string("table name")
                hints = {}
                self.skip_silent_words()
                if self.match(TokenType.HINT):
                    hints = self.parse_hints_dict()
                return DeleteColumnNode(table_name=table_name, column_name=potential_col, hints=hints)
            self.pos = saved

        # 5. DELETE RECORDS (Entire Row or filtered rows)
        is_all = False
        if self.match(TokenType.ALL):
            self.consume(TokenType.ALL)
            is_all = True
            self.skip_silent_words()

        if self.match(TokenType.FROM, TokenType.IN):
            self.consume(self.current_token().type)
        else:
            raise ParserError("Expected 'from' or 'in' in delete statement", self.current_token())

        self.skip_silent_words()
        table_name = self.parse_identifier_or_string("table name")

        where = None
        self.skip_silent_words()
        if self.match(TokenType.WHERE):
            self.consume(TokenType.WHERE)
            self.skip_silent_words()
            where = self.parse_expression()

        confirm_tok = None
        self.skip_silent_words()
        if self.match(TokenType.CONFIRMED, TokenType.CONFIRM):
            self.consume(self.current_token().type)
            confirm_tok = "CONFIRMED"

        hints = {}
        self.skip_silent_words()
        if self.match(TokenType.HINT):
            hints = self.parse_hints_dict()

        return DeleteRecordsNode(table_name=table_name, where=where, is_all=is_all, confirmation_token=confirm_tok, hints=hints)

    # -------------------------------------------------------------
    # Expressions, Comparators & Primary Literals
    # -------------------------------------------------------------
    def parse_expression(self) -> Any:
        return self.parse_logical_or()

    def parse_logical_or(self) -> Any:
        expr = self.parse_logical_and()
        while self.match(TokenType.OR):
            self.consume(TokenType.OR)
            right = self.parse_logical_and()
            expr = BinaryOpNode(left=expr, operator="OR", right=right)
        return expr

    def parse_logical_and(self) -> Any:
        expr = self.parse_comparison()
        while self.match(TokenType.AND):
            self.consume(TokenType.AND)
            right = self.parse_comparison()
            expr = BinaryOpNode(left=expr, operator="AND", right=right)
        return expr

    def parse_comparison(self) -> Any:
        self.skip_silent_words()
        expr = self.parse_additive()
        self.skip_silent_words()

        # Natural English comparisons
        if self.match(TokenType.IS):
            self.consume(TokenType.IS)
            self.skip_silent_words()
            if self.match(TokenType.NOT):
                self.consume(TokenType.NOT)
                self.skip_silent_words()
                if self.match(TokenType.EQUAL, TokenType.EQUALS):
                    self.consume(self.current_token().type)
                    if self.match(TokenType.TO):
                        self.consume(TokenType.TO)
                right = self.parse_additive()
                return BinaryOpNode(left=expr, operator="!=", right=right)

            elif self.match(TokenType.GREATER, TokenType.MORE, TokenType.ABOVE):
                self.consume(self.current_token().type)
                if self.match(TokenType.THAN):
                    self.consume(TokenType.THAN)
                self.skip_silent_words()
                if self.match(TokenType.OR):
                    self.consume(TokenType.OR)
                    if self.match(TokenType.EQUAL, TokenType.EQUALS):
                        self.consume(self.current_token().type)
                        if self.match(TokenType.TO):
                            self.consume(TokenType.TO)
                    right = self.parse_additive()
                    return BinaryOpNode(left=expr, operator=">=", right=right)
                right = self.parse_additive()
                return BinaryOpNode(left=expr, operator=">", right=right)

            elif self.match(TokenType.AT):
                self.consume(TokenType.AT)
                if self.match(TokenType.LEAST):
                    self.consume(TokenType.LEAST)
                    right = self.parse_additive()
                    return BinaryOpNode(left=expr, operator=">=", right=right)
                elif self.match(TokenType.MOST):
                    self.consume(TokenType.MOST)
                    right = self.parse_additive()
                    return BinaryOpNode(left=expr, operator="<=", right=right)

            elif self.match(TokenType.LESS, TokenType.UNDER, TokenType.BELOW):
                self.consume(self.current_token().type)
                if self.match(TokenType.THAN):
                    self.consume(TokenType.THAN)
                self.skip_silent_words()
                if self.match(TokenType.OR):
                    self.consume(TokenType.OR)
                    if self.match(TokenType.EQUAL, TokenType.EQUALS):
                        self.consume(self.current_token().type)
                        if self.match(TokenType.TO):
                            self.consume(TokenType.TO)
                    right = self.parse_additive()
                    return BinaryOpNode(left=expr, operator="<=", right=right)
                right = self.parse_additive()
                return BinaryOpNode(left=expr, operator="<", right=right)

            elif self.match(TokenType.EQUAL, TokenType.EQUALS):
                self.consume(self.current_token().type)
                if self.match(TokenType.TO):
                    self.consume(TokenType.TO)
                right = self.parse_additive()
                return BinaryOpNode(left=expr, operator="=", right=right)

            else:
                right = self.parse_additive()
                return BinaryOpNode(left=expr, operator="=", right=right)

        elif self.match(TokenType.AT):
            self.consume(TokenType.AT)
            if self.match(TokenType.LEAST):
                self.consume(TokenType.LEAST)
                right = self.parse_additive()
                return BinaryOpNode(left=expr, operator=">=", right=right)
            elif self.match(TokenType.MOST):
                self.consume(TokenType.MOST)
                right = self.parse_additive()
                return BinaryOpNode(left=expr, operator="<=", right=right)

        elif self.match(TokenType.GREATER, TokenType.MORE, TokenType.ABOVE):
            self.consume(self.current_token().type)
            if self.match(TokenType.THAN):
                self.consume(TokenType.THAN)
            self.skip_silent_words()
            if self.match(TokenType.OR):
                self.consume(TokenType.OR)
                if self.match(TokenType.EQUAL, TokenType.EQUALS):
                    self.consume(self.current_token().type)
                    if self.match(TokenType.TO):
                        self.consume(TokenType.TO)
                right = self.parse_additive()
                return BinaryOpNode(left=expr, operator=">=", right=right)
            right = self.parse_additive()
            return BinaryOpNode(left=expr, operator=">", right=right)

        elif self.match(TokenType.LESS, TokenType.UNDER, TokenType.BELOW):
            self.consume(self.current_token().type)
            if self.match(TokenType.THAN):
                self.consume(TokenType.THAN)
            self.skip_silent_words()
            if self.match(TokenType.OR):
                self.consume(TokenType.OR)
                if self.match(TokenType.EQUAL, TokenType.EQUALS):
                    self.consume(self.current_token().type)
                    if self.match(TokenType.TO):
                        self.consume(TokenType.TO)
                right = self.parse_additive()
                return BinaryOpNode(left=expr, operator="<=", right=right)
            right = self.parse_additive()
            return BinaryOpNode(left=expr, operator="<", right=right)

        elif self.match(TokenType.EQUALS):
            self.consume(TokenType.EQUALS)
            right = self.parse_additive()
            return BinaryOpNode(left=expr, operator="=", right=right)

        op_map = {
            TokenType.EQUALS: "=",
            TokenType.NOT_EQUALS: "!=",
            TokenType.GT: ">",
            TokenType.GTE: ">=",
            TokenType.LT: "<",
            TokenType.LTE: "<=",
            TokenType.LIKE: "LIKE"
        }
        if self.current_token().type in op_map:
            op_tok = self.current_token()
            self.pos += 1
            right = self.parse_additive()
            return BinaryOpNode(left=expr, operator=op_map[op_tok.type], right=right)

        return expr

    def parse_additive(self) -> Any:
        expr = self.parse_primary()
        while self.match(TokenType.PLUS, TokenType.MINUS):
            op = self.consume(self.current_token().type).value
            right = self.parse_primary()
            expr = BinaryOpNode(left=expr, operator=op, right=right)
        return expr

    def parse_primary(self) -> Any:
        self.skip_silent_words()
        tok = self.current_token()
        if self.match(TokenType.NUMBER_LITERAL):
            self.consume(TokenType.NUMBER_LITERAL)
            return LiteralNode(value=tok.value, literal_type="number")
        elif self.match(TokenType.STRING_LITERAL):
            self.consume(TokenType.STRING_LITERAL)
            return LiteralNode(value=tok.value, literal_type="string")
        elif self.match(TokenType.BOOLEAN_LITERAL):
            self.consume(TokenType.BOOLEAN_LITERAL)
            return LiteralNode(value=tok.value, literal_type="boolean")
        elif self.match(TokenType.NULL_LITERAL):
            self.consume(TokenType.NULL_LITERAL)
            return LiteralNode(value=None, literal_type="null")
        elif self.match(TokenType.IDENTIFIER):
            self.consume(TokenType.IDENTIFIER)
            name = str(tok.value)
            self.skip_silent_words()
            if self.match(TokenType.DOT):
                self.consume(TokenType.DOT)
                sub_tok = self.consume(TokenType.IDENTIFIER, "Expected sub-field after '.'")
                name = f"{name}.{sub_tok.value}"
            elif self.match(TokenType.OF):
                self.consume(TokenType.OF)
                self.skip_silent_words()
                parent_tok = self.consume(TokenType.IDENTIFIER, "Expected parent table/object after 'of'")
                name = f"{parent_tok.value}.{name}"
            return IdentifierNode(name=name)
        elif self.match(TokenType.LPAREN):
            self.consume(TokenType.LPAREN)
            expr = self.parse_expression()
            self.consume(TokenType.RPAREN, "Expected ')'")
            return expr
        else:
            raise ParserError(f"Unexpected token in expression: '{tok.value}'", tok)

    def parse_identifier_or_string(self, context: str = "identifier", allow_qualification: bool = True) -> str:
        self.skip_silent_words()
        if self.match(TokenType.TABLE):
            self.consume(TokenType.TABLE)
            self.skip_silent_words()
        elif self.match(TokenType.COLUMN):
            self.consume(TokenType.COLUMN)
            self.skip_silent_words()

        tok = self.current_token()
        if self.match(TokenType.STRING_LITERAL, TokenType.IDENTIFIER):
            self.pos += 1
            name = str(tok.value)
            if allow_qualification:
                self.skip_silent_words()
                if self.match(TokenType.DOT):
                    self.consume(TokenType.DOT)
                    sub_tok = self.consume(TokenType.IDENTIFIER, "Expected column name after '.'")
                    name = f"{name}.{sub_tok.value}"
                elif self.match(TokenType.OF):
                    self.consume(TokenType.OF)
                    self.skip_silent_words()
                    parent_tok = self.consume(TokenType.IDENTIFIER, "Expected parent table/object after 'of'")
                    name = f"{parent_tok.value}.{name}"
            return name
        elif tok.type not in (TokenType.WITH, TokenType.WHERE, TokenType.FROM, TokenType.INTO, TokenType.SET, TokenType.EOF, TokenType.SEMICOLON, TokenType.NEWLINE, TokenType.COLON, TokenType.COMMA) and isinstance(tok.value, str):
            self.pos += 1
            return str(tok.value)
        raise ParserError(f"Expected {context}, but found '{tok.value}'", tok)

    def parse_path_or_identifier(self, context: str = "identifier") -> str:
        self.skip_silent_words()
        tok = self.current_token()
        if self.match(TokenType.STRING_LITERAL):
            self.pos += 1
            return str(tok.value)
        base = self.parse_identifier_or_string(context, allow_qualification=False)
        if self.match(TokenType.DOT):
            self.consume(TokenType.DOT)
            ext = self.parse_identifier_or_string("file extension", allow_qualification=False)
            return f"{base}.{ext}"
        return base

